// Conversaciones en familia: 100 full dialogues (5 per topic).
// The first answer of each of your turns is the one the conversation follows; the others are alternatives.
// Each dialogue alternates the other person's line [es, sk] with your turn: a list of model answers [style, es, sk].
const familyDialogues=[];
function D(topic,title,who,turns){familyDialogues.push({id:`dlg-${topic}-${familyDialogues.filter(d=>d.topic===topic).length+1}`,topic,title:{es:title[0],sk:title[1]},who:{es:who[0],sk:who[1]},turns:turns.map(t=>Array.isArray(t[0])?{you:true,answers:t.map(([style,es,sk])=>({style,es,sk}))}:{you:false,es:t[0],sk:t[1]})})}
const familyAnswerStyles={
 si:['Aceptar','Súhlasiť'],alt:['Proponer otra opción','Navrhnúť inú možnosť'],preg:['Preguntar más','Spýtať sa viac'],cari:['Con cariño','S láskou'],
 form:['Más formal','Formálnejšie'],colo:['Muy coloquial','Veľmi hovorovo'],duda:['Con dudas','S váhaním'],no:['Decir que no con amabilidad','Milo odmietnuť'],
 grac:['Agradecer','Poďakovať'],hum:['Con humor','S humorom'],apoyo:['Apoyar','Podporiť'],opin:['Dar tu opinión','Povedať svoj názor'],
 expl:['Explicar','Vysvetliť'],lim:['Poner un límite','Určiť hranicu'],ofre:['Ofrecer ayuda','Ponúknuť pomoc'],recu:['Recordar','Zaspomínať si'],
 breve:['Respuesta breve','Krátka odpoveď'],cuenta:['Contar algo tuyo','Povedať niečo o sebe'],disc:['Disculparse','Ospravedlniť sa'],anim:['Animar','Povzbudiť']
};
D("visits",["¿Venís el domingo?","Prídete v nedeľu?"],["Tu hija Laura, por teléfono","Tvoja dcéra Laura, telefonicky"],[
 ["Mamá, ¿os va bien que vayamos a veros el domingo?","Mami, vyhovuje vám, ak vás prídeme pozrieť v nedeľu?"],
 [["preg","Sí, ¿venís a comer o solo por la tarde?","Áno, prídete na obed alebo len poobede?"],["si","¡Claro que sí! El domingo nos viene genial.","Jasné! Nedeľa nám úplne vyhovuje."],["alt","El domingo tenemos un compromiso. ¿Os viene bien el sábado?","V nedeľu už niečo máme. Vyhovovala by vám sobota?"],["cari","¡Qué alegría! Tengo muchas ganas de veros.","Aká radosť! Veľmi sa na vás teším."],["duda","Creo que sí, pero déjame mirarlo con papá y te digo.","Myslím, že áno, ale pozriem sa na to s otcom a dám ti vedieť."],["colo","¡Pues claro, hija! Aquí os esperamos.","No jasné, dcérka! Čakáme vás."]],
 ["Genial. Iríamos a comer, si no es mucho lío para vosotros.","Super. Prišli by sme na obed, ak to pre vás nie je veľa starostí."],
 [["preg","¿Cuántos seréis? ¿Viene también el novio de Marta?","Koľkí budete? Príde aj Martin priateľ?"],["si","Ningún lío. Preparo una paella, ¿vale?","Žiadne starosti. Urobím paellu, dobre?"],["ofre","Al contrario. ¿Hay algo que no puedan comer los niños?","Naopak. Je niečo, čo deti nemôžu jesť?"],["alt","Mejor comemos fuera, así nadie cocina. ¿Qué os parece?","Radšej sa najedzme vonku, aby nikto nevaril. Čo poviete?"],["hum","Lío ninguno; lío es cuando no venís.","Starosti žiadne; starosti sú, keď neprídete."],["cari","Para mí es un placer cocinar para vosotros.","Pre mňa je radosť variť pre vás."]],
 ["Seremos cuatro. ¿Llevamos algo? ¿Postre, pan, bebida?","Budeme štyria. Máme niečo priniesť? Dezert, chlieb, pitie?"],
 [["si","Si queréis, traed el postre. Lo demás lo tengo.","Ak chcete, doneste dezert. Ostatné mám."],["no","No hace falta nada, de verdad. Venid tranquilos.","Naozaj nič netreba. Príďte v pokoji."],["preg","¿Podéis pasar por la panadería de la esquina? Allí el pan es buenísimo.","Môžete sa zastaviť v pekárni na rohu? Majú tam výborný chlieb."],["alt","Traed solo pan; el postre lo hago yo, que me apetece.","Doneste len chlieb; dezert urobím ja, mám naň chuť."],["hum","Traed hambre, que de lo demás me encargo yo.","Doneste hlad, o ostatné sa postarám ja."],["breve","Con que vengáis, es suficiente.","Stačí, že prídete."]],
 ["Perfecto. Entonces llegamos sobre la una y media. ¡Un beso!","Výborne. Tak prídeme okolo pol druhej. Pusa!"]
]);
D("visits",["Quedarse a dormir","Prespať u nás"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["Papá, en Navidad habíamos pensado quedarnos tres noches en vuestra casa. ¿Es demasiado?","Oci, na Vianoce sme rozmýšľali, že by sme u vás zostali tri noci. Je to priveľa?"],
 [["preg","¿Qué días serían exactamente?","Ktoré dni by to presne boli?"],["si","¿Demasiado? ¡Ojalá fueran más!","Priveľa? Kiežby to bolo viac!"],["duda","Tres noches está bien, pero las camas son pocas. Habrá que organizarse.","Tri noci sú v poriadku, ale postelí je málo. Bude sa treba zorganizovať."],["alt","Mejor dos noches, que el día veintiséis vienen tus tíos.","Radšej dve noci, lebo dvadsiateho šiesteho prídu tvoji strýkovia."],["cari","Para nosotros es el mejor regalo de Navidad.","Pre nás je to najkrajší vianočný darček."],["lim","Encantados, pero el último día nos gustaría descansar un poco.","Radi, ale posledný deň by sme si chceli trochu oddýchnuť."]],
 ["Del veinticuatro al veintisiete. Los niños pueden dormir en el sofá cama.","Od dvadsiateho štvrtého do dvadsiateho siedmeho. Deti môžu spať na rozkladacej pohovke."],
 [["breve","Muy bien, así lo hacemos.","Dobre, tak to urobíme."],["si","Perfecto. Os dejo preparada la habitación de arriba.","Výborne. Pripravím vám izbu hore."],["ofre","Tengo un colchón hinchable también, por si acaso.","Mám aj nafukovací matrac, keby niečo."],["preg","¿Necesitáis toallas o traéis las vuestras?","Potrebujete uteráky, alebo si prinesiete svoje?"],["expl","El sofá cama está un poco duro; mejor pongo una manta encima.","Rozkladacia pohovka je trochu tvrdá; radšej na ňu dám deku."],["hum","Los niños pueden dormir donde quieran, menos en mi sillón.","Deti môžu spať, kde chcú, okrem môjho kresla."]],
 ["Y no os preocupéis por las comidas, que cocinamos nosotros algún día.","A nerobte si starosti s jedlom, niektorý deň uvaríme my."],
 [["si","Trato hecho: el veinticinco cocinamos todos juntos.","Platí: dvadsiateho piateho varíme všetci spolu."],["grac","Os lo agradezco mucho, así descanso un poco.","Veľmi vám ďakujem, aspoň si trochu oddýchnem."],["no","Ni hablar, sois nuestros invitados.","Ani nápad, ste naši hostia."],["alt","Mejor me ayudáis en la cocina, que es más divertido.","Radšej mi pomôžte v kuchyni, je to zábavnejšie."],["hum","Vale, pero la cena de Nochebuena no se toca.","Dobre, ale Štedrú večeru mi nikto nechytá."],["cari","Lo que de verdad me importa es que estemos juntos.","Naozaj mi záleží len na tom, aby sme boli spolu."]],
 ["Genial. Entonces lo dejamos así. ¡Qué ganas de que llegue Navidad!","Super. Tak to necháme tak. Už sa neviem dočkať Vianoc!"]
]);
D("visits",["Cambiar la fecha","Zmeniť termín"],["Tu nuera Sofía","Tvoja nevesta Sofía"],[
 ["Hola. Lo siento mucho, pero este fin de semana no vamos a poder ir. Pablo tiene fiebre.","Ahoj. Veľmi ma to mrzí, ale tento víkend nebudeme môcť prísť. Pablo má horúčku."],
 [["preg","¡Vaya! ¿Cuánta fiebre tiene? ¿Le ha visto el médico?","Ach jaj! Akú má horúčku? Videl ho lekár?"],["apoyo","No te preocupes, lo primero es que se ponga bueno.","Nerob si starosti, najdôležitejšie je, aby sa uzdravil."],["cari","Pobrecito. Dale un abrazo muy fuerte de mi parte.","Chudáčik. Silno ho za mňa objím."],["ofre","¿Necesitáis algo? Puedo llevaros comida.","Potrebujete niečo? Môžem vám priniesť jedlo."],["alt","No pasa nada, lo dejamos para la semana que viene.","Nič sa nedeje, presunieme to na budúci týždeň."],["breve","Claro, otra vez será.","Jasné, nabudúce."]],
 ["Treinta y ocho y medio. Mañana lo lleva Javier al pediatra. ¿Os importa si lo cambiamos al otro sábado?","Tridsaťosem a pol. Zajtra ho Javier vezme k pediatrovi. Vadilo by vám, keby sme to presunuli na ďalšiu sobotu?"],
 [["si","En absoluto. El otro sábado nos viene perfecto.","Vôbec nie. Ďalšia sobota nám úplne vyhovuje."],["duda","El otro sábado tengo médico por la mañana, pero por la tarde sí.","Na budúcu sobotu mám ráno lekára, ale poobede áno."],["alt","¿Y si venimos nosotros a veros cuando esté mejor?","A čo keby sme prišli my k vám, keď mu bude lepšie?"],["preg","Claro. ¿Prefieres que lo confirmemos el jueves, según cómo esté?","Jasné. Chceš, aby sme to potvrdili vo štvrtok podľa toho, ako mu bude?"],["cari","Lo que mejor os venga. Nosotros nos adaptamos.","Ako vám to najlepšie vyhovuje. My sa prispôsobíme."],["form","Por supuesto, no hay ningún problema.","Samozrejme, to vôbec nie je problém."]],
 ["Mil gracias por entenderlo. Pablo estaba muy triste porque quería ver al abuelo.","Ďakujem pekne za pochopenie. Pablo bol veľmi smutný, lebo chcel vidieť dedka."],
 [["anim","Dile que cuando venga tendremos una sorpresa para él.","Povedz mu, že keď príde, budeme mať pre neho prekvapenie."],["cari","Dile que el abuelo lo llama esta tarde por videollamada.","Povedz mu, že dedko mu dnes poobede zavolá cez video."],["hum","Dile que el abuelo también está triste, pero que se aguanta.","Povedz mu, že aj dedko je smutný, ale vydrží to."],["grac","Gracias a ti por avisarnos con tiempo.","Vďaka tebe, že si nám dala vedieť včas."],["ofre","Si queréis, le mando un cuento grabado con mi voz.","Ak chcete, pošlem mu rozprávku nahratú mojím hlasom."],["breve","Ya nos veremos pronto. ¡Que se mejore!","Čoskoro sa uvidíme. Nech sa má lepšie!"]],
 ["¡Le va a encantar! Os mando un mensaje mañana con lo que diga el médico.","To sa mu bude páčiť! Zajtra vám pošlem správu, čo povedal lekár."]
]);
D("visits",["Una visita sorpresa","Prekvapivá návšteva"],["Tu nieta Lucía, en la puerta","Tvoja vnučka Lucía, pri dverách"],[
 ["¡Sorpresa! Estaba por el barrio y he pensado subir a saludar. ¿Te pillo en mal momento?","Prekvapenie! Bola som v okolí a napadlo mi zájsť pozdraviť. Prišla som v nevhodnej chvíli?"],
 [["preg","¡Hola, cariño! ¿Qué hacías por aquí?","Ahoj, zlatko! Čo si tu robila?"],["cari","¡Qué sorpresa tan bonita! Pasa, pasa.","Aké milé prekvapenie! Poď ďalej."],["hum","Para ti nunca es mal momento. Bueno, casi nunca.","Pre teba nikdy nie je nevhodná chvíľa. No, takmer nikdy."],["duda","Estaba a punto de salir, pero tengo media hora. ¡Pasa!","Práve som chcela odísť, ale mám polhodinu. Poď ďalej!"],["disc","Pasa, pero perdona el desorden, que no esperaba a nadie.","Poď ďalej, ale prepáč ten neporiadok, nikoho som nečakala."],["breve","¡Qué va! Entra.","Ale kdeže! Vojdi."]],
 ["He venido a una entrevista de trabajo aquí al lado. ¡Creo que ha ido bien!","Bola som tu neďaleko na pracovnom pohovore. Myslím, že dopadol dobre!"],
 [["preg","¿Ah, sí? ¿De qué es el trabajo? Cuéntame.","Naozaj? Aká je to práca? Porozprávaj."],["anim","¡Qué bien! Seguro que les has encantado.","To je skvelé! Určite si ich nadchla."],["cari","Me alegro muchísimo. Te lo mereces.","Veľmi sa teším. Zaslúžiš si to."],["cuenta","Yo también recuerdo mi primera entrevista. ¡Qué nervios pasé!","Aj ja si pamätám svoj prvý pohovor. Taká som bola nervózna!"],["hum","Esto hay que celebrarlo con un café y unas galletas.","Toto treba osláviť kávou a sušienkami."],["form","Enhorabuena. ¿Cuándo te darán una respuesta?","Blahoželám. Kedy ti dajú odpoveď?"]],
 ["Es en una editorial, de correctora. Me dicen algo el viernes. Oye, ¿tienes algo de comer? Me muero de hambre.","Je to vo vydavateľstve, ako korektorka. Ozvú sa v piatok. Počuj, máš niečo na jedenie? Umieram od hladu."],
 [["si","Claro, tengo croquetas de ayer. ¿Te las caliento?","Jasné, mám krokety zo včera. Mám ti ich zohriať?"],["ofre","Te preparo un bocadillo en un momento.","Hneď ti pripravím sendvič."],["preg","¿Qué te apetece, algo dulce o salado?","Na čo máš chuť, niečo sladké alebo slané?"],["hum","En casa de la abuela nadie pasa hambre, ya lo sabes.","U babky nikto nehladuje, to predsa vieš."],["alt","Tengo poca cosa, pero bajamos al bar y te invito.","Veľa toho nemám, ale zídeme do baru a pozvem ťa."],["cari","Siéntate, que ahora mismo te traigo algo.","Sadni si, hneď ti niečo donesiem."]],
 ["¡Eres la mejor! Y el viernes te llamo para contarte qué me dicen.","Si najlepšia! A v piatok ti zavolám a poviem ti, čo mi povedali."]
]);
D("visits",["Visitar a la tía en el hospital","Návšteva tety v nemocnici"],["Tu hermana Rosa","Tvoja sestra Rosa"],[
 ["¿Te vienes conmigo mañana a ver a la tía Pilar al hospital?","Pôjdeš so mnou zajtra pozrieť tetu Pilar do nemocnice?"],
 [["preg","¿Cómo está? ¿Le han dicho ya cuándo sale?","Ako sa má? Už jej povedali, kedy ju prepustia?"],["si","Sí, claro. ¿A qué hora quedamos?","Áno, jasné. O koľkej sa stretneme?"],["duda","Mañana me cuesta un poco, pero intento organizarme.","Zajtra sa mi to trochu ťažko stíha, ale skúsim si to zariadiť."],["alt","Mañana no puedo, pero el jueves sí. ¿Te va bien?","Zajtra nemôžem, ale vo štvrtok áno. Vyhovuje ti?"],["cari","Por supuesto. Le hará ilusión vernos a las dos.","Samozrejme. Poteší sa, keď nás uvidí obe."],["ofre","Sí, y si quieres te recojo en coche.","Áno, a ak chceš, vyzdvihnem ťa autom."]],
 ["Está mejor, pero se aburre muchísimo. El horario de visitas es de cinco a ocho.","Je jej lepšie, ale strašne sa nudí. Návštevné hodiny sú od piatej do ôsmej."],
 [["si","Pues quedamos a las cinco en la puerta principal.","Tak sa stretneme o piatej pri hlavnom vchode."],["ofre","Le llevo unas revistas y un libro de crucigramas.","Donesiem jej časopisy a knihu krížoviek."],["preg","¿Se puede llevar comida, o es mejor no?","Môže sa nosiť jedlo, alebo radšej nie?"],["hum","Si se aburre, es que está mejor. ¡Buena señal!","Ak sa nudí, znamená to, že je jej lepšie. Dobré znamenie!"],["expl","Mejor a las seis, que antes tengo que recoger a la niña.","Radšej o šiestej, lebo predtým musím vyzdvihnúť malú."],["cari","Me alegra que esté mejor. Me tenía preocupada.","Teším sa, že je jej lepšie. Robila som si o ňu starosti."]],
 ["Perfecto. Ah, y no le digas nada del perro, que no sabe que lo tenemos nosotras.","Výborne. Jaj, a nehovor jej nič o psovi, nevie, že ho máme my."],
 [["si","Tranquila, no diré ni una palabra.","Neboj, nepoviem ani slovo."],["preg","¿Por qué no? ¿Crees que se preocuparía?","Prečo nie? Myslíš, že by sa trápila?"],["hum","Vale, pero si me pregunta, no sé mentir muy bien.","Dobre, ale ak sa ma spýta, veľmi dobre klamať neviem."],["opin","Yo creo que le gustaría saber que está bien cuidado.","Ja si myslím, že by bola rada, že je o neho dobre postarané."],["duda","Vale, pero tarde o temprano se lo tendremos que contar.","Dobre, ale skôr či neskôr jej to budeme musieť povedať."],["breve","Entendido. Hasta mañana.","Rozumiem. Do zajtra."]],
 ["Gracias, de verdad. Me quedo más tranquila yendo contigo. Hasta mañana.","Naozaj ďakujem. Som pokojnejšia, keď idem s tebou. Do zajtra."]
]);
D("arrivals",["Llegáis a casa","Prichádzate domov"],["Tu yerno Andrés, abriendo la puerta","Tvoj zať Andrés otvára dvere"],[
 ["¡Bienvenidos! ¿Qué tal el viaje? Pasad, pasad.","Vitajte! Aká bola cesta? Poďte ďalej."],
 [["breve","Cansados, pero contentos.","Unavení, ale spokojní."],["si","Muy bien, gracias. Sin tráfico casi todo el camino.","Veľmi dobre, ďakujeme. Takmer celou cestou bez zápch."],["cuenta","Un poco largo; el avión salió con una hora de retraso.","Trochu dlhá; lietadlo odletelo s hodinovým meškaním."],["hum","Bien, pero mis rodillas dicen que demasiado largo.","Dobre, ale moje kolená tvrdia, že pridlhá."],["grac","Bien, gracias por venir a buscarnos al aeropuerto.","Dobre, ďakujeme, že ste po nás prišli na letisko."],["cari","¡Qué ganas teníamos de veros!","Ako veľmi sme sa na vás tešili!"]],
 ["Dejad las maletas aquí. Os hemos preparado la habitación del fondo. ¿Queréis tomar algo?","Kufre nechajte tu. Pripravili sme vám izbu vzadu. Dáte si niečo?"],
 [["cari","Lo que quiero es abrazar a los niños. ¿Dónde están?","Najviac chcem objať deti. Kde sú?"],["si","Un vaso de agua, por favor. Tengo mucha sed.","Pohár vody, prosím. Som veľmi smädná."],["alt","Ahora no, gracias. Primero me gustaría lavarme las manos.","Teraz nie, ďakujem. Najprv by som si rada umyla ruky."],["preg","¿Dónde está el baño? Perdona, no me acuerdo.","Kde je kúpeľňa? Prepáč, nepamätám si."],["colo","Un cafelito no me vendría nada mal.","Kávička by mi vôbec nezaškodila."],["form","Muy amable. Un té, si no es molestia.","Veľmi milé. Čaj, ak to nie je problém."]],
 ["Los niños están en el parque con Laura; vuelven en diez minutos. Poneos cómodos.","Deti sú s Laurou v parku; vrátia sa o desať minút. Urobte si pohodlie."],
 [["grac","Gracias por todo, Andrés. Estamos como en casa.","Vďaka za všetko, Andrés. Cítime sa ako doma."],["si","Perfecto, así deshacemos la maleta mientras.","Výborne, zatiaľ si vybalíme kufor."],["preg","¿Hace falta que bajemos a buscarlos?","Treba, aby sme po nich zišli?"],["ofre","¿Te ayudo a poner la mesa mientras tanto?","Mám ti zatiaľ pomôcť prestrieť stôl?"],["cuenta","Les hemos traído unos regalos de Eslovaquia.","Priniesli sme im darčeky zo Slovenska."],["hum","Diez minutos: justo lo que necesito para parecer una persona.","Desať minút: presne toľko potrebujem, aby som vyzerala ako človek."]],
 ["Estáis en vuestra casa. ¡Ah, ya los oigo en la escalera!","Ste u seba doma. Ó, už ich počujem na schodoch!"]
]);
D("arrivals",["Recibir a los nietos","Privítať vnúčatá"],["Tu nieto Hugo, de ocho años","Tvoj osemročný vnuk Hugo"],[
 ["¡Abuela! ¿Me has echado de menos?","Babi! Chýbal som ti?"],
 [["colo","¡Un montón! Uy, qué grande estás.","Strašne veľa! Jéj, aký si veľký."],["cari","¡Muchísimo, mi vida! Ven aquí, dame un abrazo.","Strašne, zlatko moje! Poď sem, objím ma."],["hum","¿Echarte de menos? ¡Si no sé quién eres! Es broma, ven aquí.","Chýbal? Veď ani neviem, kto si! Žartujem, poď sem."],["preg","Mucho. ¿Y tú a mí?","Veľmi. A ja tebe?"],["cuenta","Cada día miraba tu foto en la nevera.","Každý deň som sa pozerala na tvoju fotku na chladničke."],["breve","¡Sí, mucho!","Áno, veľmi!"]],
 ["¡Mira, se me ha caído un diente! El ratoncito Pérez me trajo dos euros.","Pozri, vypadol mi zub! Myška Pérez mi priniesla dve eurá."],
 [["cuenta","En Eslovaquia no hay ratoncito; el diente se tira detrás de la estufa.","Na Slovensku myška nie je; zub sa hádže za pec."],["preg","¡Anda! ¿Y qué vas a hacer con los dos euros?","No toto! A čo urobíš s tými dvoma eurami?"],["hum","¿Dos euros? En mis tiempos traía una peseta, ¡y gracias!","Dve eurá? Za mojich čias nosila pesetu, a buď rád!"],["anim","¡Qué valiente! ¿Te dolió?","Aký si statočný! Bolelo to?"],["cari","Déjame ver esa sonrisa nueva.","Ukáž mi ten nový úsmev."],["breve","¡Qué suerte tienes!","Ty máš ale šťastie!"]],
 ["¿Me has traído algo de tu país?","Priniesla si mi niečo zo svojej krajiny?"],
 [["si","Claro. Tengo en la maleta chocolate y un libro de cuentos.","Jasné. V kufri mám čokoládu a knihu rozprávok."],["hum","Te he traído a mí. ¿Te parece poco?","Priniesla som seba. Je to málo?"],["lim","Sí, pero te lo doy después de comer.","Áno, ale dám ti to po obede."],["preg","A ver si lo adivinas. Es algo que se come y es dulce.","Skús uhádnuť. Je to niečo, čo sa je a je to sladké."],["cari","Un regalo pequeñito, pero hecho con mucho cariño.","Malý darček, ale s veľkou láskou."],["expl","Sí, unas galletas típicas que se llaman «medovníky».","Áno, typické sušienky, volajú sa medovníky."]],
 ["¡Bieeen! ¿Puedo abrirlo ya, porfa?","Hurá! Môžem to už otvoriť, prosím?"]
]);
D("arrivals",["Llegar tarde","Prísť neskoro"],["Tu hijo Javier, al teléfono","Tvoj syn Javier, telefonicky"],[
 ["Mamá, perdona, vamos a llegar tarde. Hay un atasco enorme en la autovía.","Mami, prepáč, prídeme neskoro. Na diaľnici je obrovská zápcha."],
 [["preg","¿Cuánto calculas que vais a tardar?","Koľko asi budete meškať?"],["apoyo","No pasa nada, lo importante es que lleguéis bien.","Nič sa nedeje, dôležité je, aby ste dorazili v poriadku."],["cari","Tranquilo, hijo. Conduce con cuidado.","Pokojne, synček. Šoféruj opatrne."],["ofre","¿Queréis que empecemos a comer o os esperamos?","Chcete, aby sme začali jesť, alebo na vás počkáme?"],["hum","Bueno, así la comida tiene más tiempo para hacerse.","No, aspoň má jedlo viac času, aby sa uvarilo."],["breve","Vale, sin prisa.","Dobre, bez náhlenia."]],
 ["Unos cuarenta y cinco minutos, más o menos. Los niños ya están pidiendo comida.","Asi štyridsaťpäť minút, viac-menej. Deti už pýtajú jesť."],
 [["ofre","Si queréis, os guardo los platos calientes en el horno.","Ak chcete, odložím vám taniere do rúry, nech sú teplé."],["si","Pues esperamos. Mientras, preparo la mesa con calma.","Tak počkáme. Zatiaľ v pokoji prestriem stôl."],["alt","Dadles algo en el coche, una fruta o unas galletas.","Dajte im niečo v aute, ovocie alebo sušienky."],["opin","No paréis en ninguna gasolinera, que ya falta poco.","Nezastavujte na žiadnej pumpe, už to nie je ďaleko."],["hum","Diles a los niños que la abuela ha hecho croquetas. Eso los calma.","Povedz deťom, že babka urobila krokety. To ich upokojí."],["cari","Pobrecitos. Dales un beso de mi parte.","Chudáčikovia. Daj im za mňa pusu."]],
 ["Gracias, mamá. Te escribo cuando estemos saliendo de la autovía.","Ďakujem, mami. Napíšem ti, keď budeme schádzať z diaľnice."],
 [["hum","Vale. Y si tardáis mucho, empiezo yo con el postre.","Dobre. A ak budete meškať veľmi, začnem ja s dezertom."],["si","Perfecto. Así pongo el arroz en el momento justo.","Výborne. Tak dám ryžu variť presne v správnej chvíli."],["cari","Vale, cariño. Y no te pongas nervioso por llegar tarde.","Dobre, zlatko. A nebuď nervózny, že meškáte."],["form","De acuerdo. Avísame, por favor.","Dobre. Daj mi, prosím, vedieť."],["preg","¿Necesitáis que os abra la puerta del garaje?","Potrebujete, aby som vám otvorila garáž?"],["breve","De acuerdo. Hasta ahora.","Dobre. Zatiaľ."]],
 ["Ja, ja. ¡Ni se te ocurra! Hasta ahora, mamá.","Ha-ha. Ani na to nepomysli! Zatiaľ, mami."]
]);
D("arrivals",["Primera vez en la casa nueva","Prvýkrát v novom byte"],["Tu hija Laura","Tvoja dcéra Laura"],[
 ["Bueno, ¿qué os parece el piso nuevo? Todavía falta colgar los cuadros.","Tak čo poviete na nový byt? Ešte treba zavesiť obrazy."],
 [["preg","¿Cuántas habitaciones tiene? Enséñanoslo todo.","Koľko má izieb? Ukáž nám všetko."],["cari","¡Es precioso! Se nota que lo habéis hecho con cariño.","Je nádherný! Vidno, že ste ho zariadili s láskou."],["opin","Me encanta la luz que entra por el salón.","Páči sa mi, koľko svetla vchádza do obývačky."],["hum","Muy bonito. Y sin cuadros parece más grande.","Veľmi pekný. A bez obrazov vyzerá väčší."],["form","Es muy acogedor. Enhorabuena a los dos.","Je veľmi útulný. Blahoželám vám obom."],["duda","Es bonito, aunque la escalera es un poco empinada para mí.","Je pekný, aj keď schody sú pre mňa trochu strmé."]],
 ["Mira, esta será la habitación de invitados. Así podréis quedaros siempre que queráis.","Pozri, toto bude izba pre hostí. Tak môžete zostať, kedykoľvek budete chcieť."],
 [["ofre","Si queréis, os cosemos unas cortinas para esta habitación.","Ak chcete, ušijeme vám do tejto izby záclony."],["grac","¡Qué detalle! Muchas gracias, hija.","To je od teba milé! Ďakujem pekne, dcérka."],["hum","Cuidado con lo que dices, que a lo mejor no nos vamos nunca.","Pozor, čo hovoríš, lebo možno nikdy neodídeme."],["si","Nos encantará venir más a menudo.","Radi budeme chodiť častejšie."],["lim","Gracias, pero tampoco queremos molestar demasiado.","Ďakujem, ale ani nechceme príliš obťažovať."],["cari","Me hace muy feliz veros tan bien instalados.","Veľmi ma teší, že ste sa tak pekne zabývali."]],
 ["¿De verdad nos coseríais las cortinas? Sería un regalo perfecto.","Naozaj by ste nám ušili záclony? To by bol dokonalý darček."],
 [["si","Claro. Mañana medimos la ventana y compramos la tela.","Jasné. Zajtra zmeriame okno a kúpime látku."],["preg","¿De qué color las queréis? ¿Claras u oscuras?","Akú farbu chcete? Svetlé alebo tmavé?"],["hum","Sí, pero si quedan torcidas, no protestes.","Áno, ale ak budú nakrivo, nesťažuj sa."],["cuenta","Tu abuela me enseñó a coser cortinas cuando era joven.","Tvoja stará mama ma naučila šiť záclony, keď som bola mladá."],["duda","Lo intentamos, aunque hace tiempo que no coso.","Skúsime, aj keď som už dlho nešila."],["cari","Para tu casa, lo que haga falta.","Pre tvoj domov čokoľvek treba."]],
 ["¡Gracias, mamá! Ahora vamos a la terraza, que os he preparado algo de picar.","Ďakujem, mami! Teraz poďme na terasu, pripravila som vám niečo na zahryznutie."]
]);
D("arrivals",["Recoger en la estación","Vyzdvihnúť na stanici"],["Tu sobrino Diego, por mensaje de voz","Tvoj synovec Diego, hlasová správa"],[
 ["Tía, ya he llegado a la estación de Atocha. ¿Dónde nos vemos?","Teta, už som na stanici Atocha. Kde sa stretneme?"],
 [["alt","Espérame en la cafetería del jardín tropical, que es fácil de encontrar.","Počkaj ma v kaviarni pri tropickej záhrade, ľahko sa nájde."],["expl","Estoy en la salida principal, junto a la parada de taxis.","Som pri hlavnom východe, vedľa stanovišťa taxíkov."],["preg","¿Por qué salida has salido? Dime qué ves.","Ktorým východom si vyšiel? Povedz mi, čo vidíš."],["disc","Perdona, voy un poco tarde. Llego en cinco minutos.","Prepáč, trochu meškám. Budem tam o päť minút."],["cari","¡Bienvenido a Madrid! Ahora mismo voy a por ti.","Vitaj v Madride! Hneď idem po teba."],["breve","Voy para allá.","Už idem."]],
 ["Estoy al lado de unas plantas enormes y una tortuga. ¿Es aquí?","Som pri obrovských rastlinách a korytnačke. Je to tu?"],
 [["expl","Sí. Yo estoy entrando por la puerta del reloj.","Áno. Ja vchádzam dverami pri hodinách."],["si","¡Sí, ese es el jardín! Quédate ahí, que te veo.","Áno, to je tá záhrada! Zostaň tam, už ťa vidím."],["hum","Si hay una tortuga, estás en el sitio correcto.","Ak je tam korytnačka, si na správnom mieste."],["preg","¿Llevas la chaqueta roja? Creo que te estoy viendo.","Máš červenú bundu? Myslím, že ťa vidím."],["cari","Perfecto, cariño. No te muevas.","Výborne, zlatko. Nehýb sa."],["breve","Ahí mismo. Espera.","Presne tam. Počkaj."]],
 ["¡Te veo! Oye, traigo una maleta muy pesada, ¿hay que andar mucho hasta el coche?","Vidím ťa! Počuj, mám veľmi ťažký kufor, treba ísť ďaleko k autu?"],
 [["hum","¿Qué llevas, piedras? ¡Si solo vienes una semana!","Čo v ňom máš, kamene? Veď ideš len na týždeň!"],["expl","Unos cinco minutos. El coche está en el aparcamiento de abajo.","Asi päť minút. Auto je na parkovisku dole."],["ofre","Te ayudo; entre los dos la llevamos sin problema.","Pomôžem ti; vo dvoch ju bez problémov donesieme."],["alt","Mejor cogemos un taxi, que mi coche está lejos.","Radšej si vezmime taxík, moje auto je ďaleko."],["si","No, está muy cerca. Hay ascensor.","Nie, je to blízko. Je tam výťah."],["cari","Tranquilo, tú dame un abrazo y lo demás lo vemos.","Pokojne, ty ma objím a ostatné vyriešime."]],
 ["Ja, ja. Traigo regalos de mi madre. ¡Allá voy!","Ha-ha. Nesiem darčeky od mamy. Už idem!"]
]);
D("table",["¿Quieres repetir?","Dáš si ešte?"],["Tu consuegra Carmen, en una comida","Tvoja svatka Carmen pri obede"],[
 ["¿Te sirvo un poco más de cocido? Hay de sobra.","Naložím ti ešte trochu cocida? Je ho dosť."],
 [["preg","¿Cómo lo haces para que quede tan sabroso?","Ako to robíš, že je také chutné?"],["si","Sí, por favor, un poquito más. Está buenísimo.","Áno, prosím, ešte trošku. Je výborné."],["no","No, gracias, de verdad. Estoy llenísima.","Nie, ďakujem, naozaj. Som úplne plná."],["alt","Solo garbanzos, sin carne, gracias.","Len cícer, bez mäsa, ďakujem."],["hum","Si me sirves más, me tendréis que llevar rodando a casa.","Ak mi naložíš viac, budete ma musieť domov odkotúľať."],["form","Muchas gracias, pero prefiero dejar sitio para el postre.","Veľmi pekne ďakujem, ale radšej si nechám miesto na dezert."]],
 ["Es la receta de mi madre. El secreto es dejarlo toda la noche a fuego lento.","Je to recept po mojej mame. Tajomstvo je nechať ho celú noc na miernom ohni."],
 [["cuenta","En mi tierra hacemos una sopa parecida, con col y salchicha.","U nás doma robíme podobnú polievku s kapustou a klobásou."],["preg","¿Toda la noche? ¿Y no te da miedo dejar el fuego encendido?","Celú noc? A nebojíš sa nechať zapálený oheň?"],["cari","Se nota que está hecho con paciencia y cariño.","Vidno, že je to robené s trpezlivosťou a láskou."],["si","¿Me la apuntarías? Me encantaría hacerla en casa.","Napísala by si mi ho? Rada by som ho urobila doma."],["hum","Con esa receta podrías abrir un restaurante.","S takým receptom by si mohla otvoriť reštauráciu."],["opin","Las recetas de las madres siempre son las mejores.","Recepty od mám sú vždy najlepšie."]],
 ["¿Ah, sí? ¿Y cómo se llama esa sopa vuestra?","Naozaj? A ako sa volá tá vaša polievka?"],
 [["si","«Kapustnica». ¿Hacemos un intercambio de recetas?","Kapustnica. Vymeníme si recepty?"],["expl","Se llama «kapustnica». La hacemos sobre todo en Navidad.","Volá sa kapustnica. Robíme ju najmä na Vianoce."],["ofre","«Kapustnica». La próxima vez os la preparo yo.","Kapustnica. Nabudúce vám ju pripravím ja."],["hum","«Kapustnica». Sí, ya sé que suena a trabalenguas.","Kapustnica. Áno, viem, že to znie ako jazykolam."],["cuenta","«Kapustnica». Mi abuela le ponía setas del bosque.","Kapustnica. Moja stará mama do nej dávala lesné huby."],["breve","«Kapustnica». Es de col fermentada.","Kapustnica. Je z kyslej kapusty."]],
 ["¡Me encanta la idea! Tú me enseñas la kapustnica y yo te enseño el cocido.","Ten nápad sa mi páči! Ty ma naučíš kapustnicu a ja teba cocido."]
]);
D("table",["No me gusta mucho","Veľmi mi to nechutí"],["Tu nieto Hugo","Tvoj vnuk Hugo"],[
 ["Abuela, no me gustan las espinacas. ¿Tengo que comérmelas?","Babi, nemám rád špenát. Musím ho zjesť?"],
 [["lim","Por lo menos pruébalas. Si no te gustan, no pasa nada.","Aspoň ho ochutnaj. Ak ti nebude chutiť, nič sa nestane."],["preg","¿Las has probado alguna vez con queso?","Ochutnal si ho niekedy so syrom?"],["hum","Popeye se las comía y mira qué fuerte estaba.","Pepek ho jedol a pozri, aký bol silný."],["alt","Vale, cómete la mitad y te dejo el resto.","Dobre, zjedz polovicu a zvyšok ti odpustím."],["cuenta","A mí de pequeña tampoco me gustaban.","Ani mne ako malej nechutil."],["cari","Las he hecho con cariño para ti, prueba un poquito.","Urobila som ho s láskou pre teba, ochutnaj trošku."]],
 ["Vale... Uf, saben a hierba. ¿Puedo comer solo la tortilla?","Dobre... Fuj, chutí ako tráva. Môžem jesť len omeletu?"],
 [["alt","La próxima vez te las hago en croquetas, a ver qué tal.","Nabudúce ti ho urobím v kroketách, uvidíme."],["si","Bueno, has probado, que es lo importante. Come la tortilla.","No, ochutnal si, a to je hlavné. Zjedz omeletu."],["lim","Tres cucharadas más y luego la tortilla.","Ešte tri lyžice a potom omeletu."],["hum","¿A hierba? ¿Desde cuándo comes tú hierba?","Ako tráva? Odkedy ty ješ trávu?"],["preg","¿Y qué verdura te gusta a ti?","A akú zeleninu máš rád ty?"],["anim","Muy bien por probarlas. Eso es ser valiente.","Výborne, že si ho ochutnal. To je odvaha."]],
 ["¡Las croquetas de espinacas sí me gustan! Las hace mamá a veces.","Špenátové krokety mám rád! Mama ich niekedy robí."],
 [["preg","¿Me ayudas a hacerlas? Tú las enrollas y yo las frío.","Pomôžeš mi ich urobiť? Ty ich budeš šúľať a ja smažiť."],["si","Pues trato hecho: mañana hacemos croquetas juntos.","Tak platí: zajtra spolu urobíme krokety."],["hum","Ah, entonces lo que no te gusta es cómo cocino yo.","Aha, takže ti nechutí, ako varím ja."],["cari","Pues para ti, croquetas siempre que quieras.","Tak pre teba krokety, kedykoľvek budeš chcieť."],["expl","Es que en las croquetas la espinaca se mezcla con bechamel.","V kroketách sa špenát mieša s bešamelom."],["breve","¡Apuntado!","Zapísané!"]],
 ["¡Sí! ¿Y puedo comerme las que se rompan?","Áno! A môžem zjesť tie, čo sa rozpadnú?"]
]);
D("table",["Pagar la cuenta","Zaplatiť účet"],["Tu yerno Andrés, en un restaurante","Tvoj zať Andrés v reštaurácii"],[
 ["Bueno, ¿pedimos la cuenta? Hoy invito yo, que es vuestro aniversario.","Tak čo, vypýtame si účet? Dnes pozývam ja, máte výročie."],
 [["no","Ni hablar. Hoy pagamos nosotros, que nos hace ilusión.","Ani nápad. Dnes platíme my, robí nám to radosť."],["grac","¡Qué detalle, Andrés! Muchísimas gracias.","To je od teba milé, Andrés! Veľmi pekne ďakujem."],["alt","Vale, pero entonces el café lo pagamos nosotros.","Dobre, ale kávu potom zaplatíme my."],["duda","No sé... Nos da un poco de apuro.","Neviem... Je nám to trochu nepríjemné."],["hum","Bueno, si insistes tanto, no te voy a llevar la contraria.","No, keď tak trváš, nebudem ti odporovať."],["form","Es muy generoso por tu parte, de verdad.","Je to od teba naozaj veľmi veľkorysé."]],
 ["Insisto. Lleváis toda la semana cuidando de los niños. Es lo mínimo.","Trvám na tom. Celý týždeň sa staráte o deti. To je to najmenej."],
 [["alt","Bueno, pero la próxima comida la pagamos nosotros. Prométemelo.","Dobre, ale ďalší obed platíme my. Sľúb mi to."],["si","Pues muchas gracias. Lo aceptamos encantados.","Tak veľmi pekne ďakujeme. Radi to prijímame."],["cari","Cuidar de los niños es un placer, no un trabajo.","Starať sa o deti je radosť, nie práca."],["hum","Vale, pero que conste que los niños se han portado regular.","Dobre, ale nech je jasné, že deti sa správali tak-tak."],["grac","Gracias. Nos sentimos muy queridos en esta familia.","Ďakujeme. V tejto rodine sa cítime veľmi milovaní."],["breve","Bueno, gracias. Eres un sol.","Tak ďakujeme. Si zlatý."]],
 ["Prometido. ¿Pedimos también unos cafés antes de irnos?","Sľubujem. Dáme si ešte pred odchodom kávu?"],
 [["colo","Venga, un cafelito y nos vamos.","Tak dobre, kávička a ideme."],["si","Sí, un cortado para mí, por favor.","Áno, pre mňa cortado, prosím."],["no","Para mí no, gracias, que luego no duermo.","Pre mňa nie, ďakujem, potom nespím."],["alt","Mejor una manzanilla, que he comido mucho.","Radšej harmančekový čaj, veľa som zjedla."],["preg","¿Tienen descafeinado? Pregúntale al camarero.","Majú bezkofeínovú? Spýtaj sa čašníka."],["hum","Un café solo, bien cargado, para aguantar a los niños esta tarde.","Silné čierne kafe, aby som popoludní vydržala deti."]],
 ["Perfecto. ¡Camarero, cuando pueda: tres cafés y la cuenta, por favor!","Výborne. Pán čašník, keď budete mať čas: tri kávy a účet, prosím!"]
]);
D("table",["Una alergia","Alergia"],["La novia de tu nieto, Irene","Priateľka tvojho vnuka, Irene"],[
 ["Perdona, ¿esta salsa lleva frutos secos? Es que soy alérgica.","Prepáčte, je v tejto omáčke orechy? Som alergická."],
 [["preg","Creo que no, pero déjame mirar la receta. ¿Es grave la alergia?","Myslím, že nie, ale pozriem sa do receptu. Je tá alergia vážna?"],["expl","Sí, lleva almendras. Mejor no la tomes.","Áno, sú v nej mandle. Radšej si ju nedávaj."],["disc","¡Ay, perdona! No lo sabía. Lleva nueces.","Joj, prepáč! Nevedela som. Sú v nej vlašské orechy."],["ofre","Lleva almendras, pero te preparo otra salsa en un momento.","Sú v nej mandle, ale hneď ti pripravím inú omáčku."],["form","Gracias por avisar. Sí, contiene avellanas.","Ďakujem, že ste upozornili. Áno, obsahuje lieskové orechy."],["cari","Gracias por decírmelo, hija. Para ti hago algo aparte.","Ďakujem, že si mi to povedala, zlatko. Pre teba urobím niečo zvlášť."]],
 ["Es bastante fuerte, sí. No te preocupes, con la ensalada y el pan tengo de sobra.","Je dosť silná, áno. Nerobte si starosti, so šalátom a chlebom mám dosť."],
 [["no","De eso nada. Te hago un filete a la plancha, son cinco minutos.","To nie. Urobím ti rezeň na grile, je to päť minút."],["si","Bueno, pero si te quedas con hambre, me lo dices.","Dobre, ale ak budeš hladná, povedz mi."],["preg","¿El pan te va bien? Es de la panadería; no sé si lleva semillas.","Chlieb je v poriadku? Je z pekárne; neviem, či sú v ňom semienka."],["disc","Lo siento mucho. La próxima vez pregunto antes de cocinar.","Veľmi ma to mrzí. Nabudúce sa spýtam pred varením."],["cari","No quiero que te vayas de mi casa con hambre.","Nechcem, aby si od nás odchádzala hladná."],["hum","¿Solo ensalada? Aquí nadie se va sin postre, alergias aparte.","Len šalát? Odtiaľto nikto neodíde bez dezertu, alergia-nealergia."]],
 ["Eres muy amable. Un filete me parece perfecto, gracias.","Ste veľmi milá. Rezeň mi úplne stačí, ďakujem."],
 [["si","Ahora mismo. ¿Lo quieres muy hecho o poco hecho?","Hneď. Chceš ho dobre prepečený alebo menej?"],["preg","¿Hay algo más que no puedas comer? Así lo apunto.","Je ešte niečo, čo nemôžeš jesť? Zapíšem si to."],["cari","Siéntate tranquila, que yo me encargo.","Sadni si v pokoji, ja sa o to postarám."],["hum","Marchando un filete para la invitada de honor.","Jeden rezeň pre čestnú hostku, už sa robí."],["expl","Lo hago en una sartén limpia, para que no haya ningún riesgo.","Urobím ho na čistej panvici, aby nehrozilo žiadne riziko."],["breve","Enseguida está.","Hneď to bude."]],
 ["Muy hecho, por favor. ¡Qué bien me cuidáis en esta casa!","Dobre prepečený, prosím. Ako dobre sa o mňa v tomto dome staráte!"]
]);
D("table",["La sobremesa","Posedenie po jedle"],["Tu hermano Luis","Tvoj brat Luis"],[
 ["¿Qué prisa hay? Quedaos un rato más, que hace mucho que no charlamos.","Kam sa ponáhľate? Zostaňte ešte chvíľu, dlho sme sa nerozprávali."],
 [["preg","Vale. ¿Qué tal te va en el trabajo nuevo?","Dobre. Ako sa ti darí v novej práci?"],["si","Venga, media hora más. ¿Sacas el café?","Tak dobre, ešte polhodinku. Uvaríš kávu?"],["no","Me encantaría, pero tenemos que recoger a los niños a las seis.","Veľmi rada, ale o šiestej musíme vyzdvihnúť deti."],["alt","Hoy no podemos, pero ¿por qué no venís vosotros el viernes?","Dnes nemôžeme, ale prečo neprídete vy v piatok?"],["cari","Tienes razón. Con vosotros el tiempo se pasa volando.","Máš pravdu. S vami čas letí."],["hum","Bueno, si hay más tarta, nos quedamos.","No, ak je ešte torta, zostaneme."]],
 ["Bien, aunque cansado. Los primeros meses son duros. ¿Y vosotros? ¿Ya estáis jubilados del todo?","Dobre, aj keď som unavený. Prvé mesiace sú ťažké. A vy? Už ste úplne na dôchodku?"],
 [["cuenta","Sí, desde marzo. Al principio no sabía qué hacer con tanto tiempo.","Áno, od marca. Najprv som nevedela, čo s toľkým časom."],["hum","Sí, y ahora tengo menos tiempo libre que cuando trabajaba.","Áno, a teraz mám menej voľného času, ako keď som pracovala."],["apoyo","Ánimo con el trabajo. Los comienzos siempre cuestan.","Veľa síl v práci. Začiatky sú vždy ťažké."],["expl","Casi. Todavía doy alguna clase particular de vez en cuando.","Takmer. Ešte z času na čas dávam súkromné hodiny."],["preg","Sí. Oye, ¿y tus compañeros nuevos qué tal son?","Áno. Počuj, a akí sú noví kolegovia?"],["opin","Jubilarse está muy bien, pero hay que tener proyectos.","Dôchodok je fajn, ale treba mať nejaké plány."]],
 ["Ya me imagino. Oye, y ese curso de pintura del que me hablabas, ¿al final lo hiciste?","Viem si to predstaviť. Počuj, a ten kurz maľovania, o ktorom si mi hovorila, nakoniec si ho absolvovala?"],
 [["ofre","Sí. Si quieres, te enseño las fotos de lo que he pintado.","Áno. Ak chceš, ukážem ti fotky toho, čo som namaľovala."],["si","¡Sí! Voy los martes. Ya he terminado mi primer cuadro.","Áno! Chodím v utorky. Už som dokončila prvý obraz."],["hum","Sí, y mi profesor dice que tengo mucho... entusiasmo.","Áno, a môj učiteľ hovorí, že mám veľa... nadšenia."],["no","Al final no; era demasiado caro. Pero pinto en casa.","Nakoniec nie, bol pridrahý. Ale maľujem doma."],["duda","Empecé, pero no sé si es lo mío.","Začala som, ale neviem, či je to pre mňa."],["cuenta","Sí, y me ha cambiado la forma de mirar las cosas.","Áno a zmenilo mi to spôsob, akým sa pozerám na veci."]],
 ["¡Enséñamelo! Y luego te pongo otro café, que ya no os dejo ir.","Ukáž mi to! A potom ti dám ďalšiu kávu, už vás nepustím."]
]);
D("kitchen",["Repartir tareas","Rozdeliť úlohy"],["Tu hija Laura, en la cocina","Tvoja dcéra Laura v kuchyni"],[
 ["Mamá, ¿en qué te ayudo? Dime algo concreto.","Mami, s čím ti pomôžem? Povedz mi niečo konkrétne."],
 [["si","Pela las patatas, por favor. Están en la bolsa de la puerta.","Ošúp zemiaky, prosím. Sú vo vrecku pri dverách."],["expl","Corta la cebolla bien finita, que es para el sofrito.","Nakrájaj cibuľu na drobno, je na základ."],["no","Nada, hija, siéntate y hazme compañía.","Nič, dcérka, sadni si a rob mi spoločnosť."],["preg","¿Prefieres cortar o remover? Elige tú.","Chceš radšej krájať alebo miešať? Vyber si."],["hum","Ayúdame a no quemar nada, que es lo más difícil.","Pomôž mi nič nespáliť, to je najťažšie."],["alt","Pon la mesa, que yo aquí me apaño sola.","Prestri stôl, ja si tu poradím sama."]],
 ["Vale. ¿Las patatas en rodajas o en dados?","Dobre. Zemiaky na plátky alebo na kocky?"],
 [["cari","Como te enseñé de pequeña, ¿te acuerdas?","Ako som ťa učila, keď si bola malá, pamätáš?"],["expl","En rodajas finas, que son para la tortilla.","Na tenké plátky, sú na tortillu."],["preg","¿Tú cómo las cortas para la tortilla? A ver si lo haces como yo.","Ako ich krájaš ty na tortillu? Uvidíme, či ako ja."],["hum","Como quieras, mientras no te cortes un dedo.","Ako chceš, len si neodrež prst."],["alt","En dados, que hoy hago patatas a lo pobre.","Na kocky, dnes robím zemiaky „a lo pobre“."],["breve","En rodajas, finitas.","Na plátky, tenučké."]],
 ["¡Claro que me acuerdo! Siempre me decías que las patatas tienen que «sonar» al cortarlas.","Jasné, že si pamätám! Vždy si mi hovorila, že zemiaky musia pri krájaní „chrumkať“."],
 [["preg","¿Y tú se lo dices a tus hijos?","A ty to hovoríš svojim deťom?"],["recu","Eso me lo decía mi madre a mí. ¡Qué memoria tienes!","To mne hovorila moja mama. Aká máš pamäť!"],["hum","Y tú siempre cortabas la mitad y te comías la otra mitad cruda.","A ty si vždy polovicu nakrájala a druhú polovicu zjedla surovú."],["cari","Me encanta cocinar contigo otra vez.","Veľmi rada s tebou zase varím."],["expl","Si suenan, es que están frescas. Si no, son viejas.","Ak chrumkajú, sú čerstvé. Ak nie, sú staré."],["breve","¡Así es! Muy bien.","Presne tak! Výborne."]],
 ["Sí, y se ríen de mí. Bueno, ya están. ¿Qué hago ahora?","Áno, a smejú sa mi. Tak, sú hotové. Čo mám robiť teraz?"]
]);
D("kitchen",["Cambiar la receta","Zmeniť recept"],["Tu nuera Sofía","Tvoja nevesta Sofía"],[
 ["Oye, ¿te importa si le pongo un poco de picante al guiso? A Javier le encanta.","Počuj, vadilo by ti, keby som do guláša dala trochu pálivého? Javier ho zbožňuje."],
 [["preg","¿Qué picante usas? ¿Guindilla o pimentón?","Aké pálivé používaš? Feferónku alebo papriku?"],["si","Claro que no. Ponle lo que quieras.","Jasné, že nie. Daj doň, čo chceš."],["duda","Un poquito sí, pero los niños no lo soportan bien.","Trošku áno, ale deti to neznášajú dobre."],["alt","Mejor sírvelo aparte, así cada uno se pone lo que quiera.","Radšej ho podávaj zvlášť, nech si každý dá, koľko chce."],["hum","Ponle, pero si me sale fuego por la boca, es culpa tuya.","Daj, ale ak mi bude šľahať oheň z úst, je to tvoja vina."],["cari","Gracias por preguntar. Me gusta que lo decidamos juntas.","Vďaka, že sa pýtaš. Páči sa mi, že rozhodujeme spolu."]],
 ["Pimentón picante de la Vera. Es ahumado, no pica demasiado.","Pálivú papriku z Very. Je údená, nie je príliš pálivá."],
 [["preg","¿Ahumado? No lo he probado nunca. ¿Me dejas olerlo?","Údený? Ten som nikdy neochutnala. Môžem ovoňať?"],["si","Ah, entonces sí. Ese me encanta.","Aha, tak potom áno. Ten zbožňujem."],["cuenta","En mi país también usamos mucho pimentón en el guiso.","U nás tiež dávame do guláša veľa papriky."],["duda","Bueno, pero solo media cucharadita, por si acaso.","Dobre, ale len pol lyžičky, pre istotu."],["opin","El pimentón le da mucho sabor. Buena idea.","Paprika mu dodá veľa chuti. Dobrý nápad."],["breve","Perfecto, adelante.","Výborne, do toho."]],
 ["Toma, huele. ¿A que tiene un aroma increíble?","Na, ovoňaj. Má neuveriteľnú vôňu, však?"],
 [["preg","¿Dónde lo compras? Me gustaría llevarme un bote a casa.","Kde ho kupuješ? Chcela by som si zobrať plechovku domov."],["si","¡Huele a leña! Es buenísimo.","Vonia ako drevo z ohňa! Je výborný."],["hum","Huele tan bien que me lo comería a cucharadas.","Vonia tak dobre, že by som ho jedla lyžicou."],["recu","Me recuerda al olor de las matanzas en el pueblo.","Pripomína mi vôňu zabíjačky na dedine."],["cari","Cocinar contigo es un gusto. Aprendo cosas nuevas.","Variť s tebou je radosť. Učím sa nové veci."],["form","Es un aroma muy especial, sí.","Je to veľmi zvláštna vôňa, áno."]],
 ["Te regalo un bote antes de que os vayáis. ¡Y ahora, a esperar que se haga!","Darujem ti plechovku, než odídete. A teraz čakáme, kým sa to uvarí!"]
]);
D("kitchen",["Algo se ha quemado","Niečo sa pripálilo"],["Tu nieta Lucía","Tvoja vnučka Lucía"],[
 ["¡Abuela! Huele a quemado... Creo que me he olvidado las galletas en el horno.","Babi! Cítiť spáleninu... Myslím, že som zabudla sušienky v rúre."],
 [["apoyo","Tranquila, sácalas. Seguro que alguna se salva.","Pokojne, vyber ich. Určite sa niektoré dajú zachrániť."],["preg","¿Cuánto tiempo llevan dentro?","Ako dlho tam sú?"],["hum","Bueno, las galletas tostadas también tienen su público.","No, aj opečené sušienky majú svojich fanúšikov."],["ofre","Abre la ventana, que yo apago el horno.","Otvor okno, ja vypnem rúru."],["cari","No pasa nada, cariño. A todos nos ha pasado.","Nič sa nedeje, zlatko. Stalo sa to každému."],["breve","¡Rápido, sácalas!","Rýchlo, vyber ich!"]],
 ["Están negras por abajo. Qué rabia, eran para la fiesta de mañana.","Zospodu sú čierne. To ma štve, boli na zajtrajšiu oslavu."],
 [["preg","¿Tenemos harina y mantequilla para repetirlas?","Máme múku a maslo, aby sme ich zopakovali?"],["alt","Pues hacemos otra tanda ahora. Tenemos tiempo de sobra.","Tak urobíme ďalšiu várku hneď teraz. Máme času dosť."],["expl","Ráspalas por abajo con un cuchillo; quedan casi perfectas.","Zoškrab ich zospodu nožom; budú takmer dokonalé."],["cuenta","La primera vez que hice un bizcocho, quemé hasta el molde.","Keď som prvýkrát piekla piškótu, spálila som aj formu."],["anim","Te salen muy ricas; esto ha sido solo un despiste.","Robíš ich veľmi dobré; toto bola len nepozornosť."],["hum","Las quemadas nos las comemos nosotras, como premio.","Spálené zjeme my, ako odmenu."]],
 ["Hay harina, pero solo queda un huevo. ¿Sirve?","Múka je, ale zostalo len jedno vajce. Stačí?"],
 [["expl","Puedes cambiar un huevo por un poco de yogur.","Jedno vajce môžeš nahradiť trochou jogurtu."],["si","Sí, con uno basta si hacemos media receta.","Áno, jedno stačí, ak urobíme polovicu receptu."],["ofre","Bajo un momento a la tienda a por huevos.","Na chvíľu zbehnem do obchodu po vajcia."],["alt","Pídele dos huevos a la vecina, que siempre tiene.","Popros susedu o dve vajcia, vždy má."],["hum","Con un huevo y mucha imaginación, lo que haga falta.","S jedným vajcom a veľkou fantáziou čokoľvek."],["duda","No sé si quedarán igual, pero probamos.","Neviem, či budú rovnaké, ale skúsime."]],
 ["¡Lo del yogur no lo sabía! Venga, empezamos otra vez. Esta vez pongo una alarma.","To s jogurtom som nevedela! Tak poďme odznova. Tentoraz si nastavím budík."]
]);
D("kitchen",["Enseñar un plato típico","Naučiť tradičné jedlo"],["Tu yerno Andrés","Tvoj zať Andrés"],[
 ["Me han dicho que haces unos «halušky» buenísimos. ¿Me enseñas?","Vraj robíš výborné halušky. Naučíš ma ich?"],
 [["expl","Claro. Es el plato nacional de Eslovaquia, ¿lo sabías?","Jasné. Je to národné jedlo Slovenska, vedel si?"],["si","¡Con mucho gusto! Necesitamos patatas, harina y queso de oveja.","S veľkou radosťou! Potrebujeme zemiaky, múku a ovčí syr."],["hum","¿Quién te ha dicho eso? Seguro que ha sido mi hija.","Kto ti to povedal? Určite moja dcéra."],["preg","¿Tienes rallador? Es lo más importante.","Máš strúhadlo? To je najdôležitejšie."],["duda","Sí, aunque aquí no sé si encontraremos el queso adecuado.","Áno, hoci neviem, či tu nájdeme ten správny syr."],["cari","Me hace mucha ilusión que quieras aprender.","Veľmi ma teší, že sa chceš naučiť."]],
 ["No lo sabía. ¿Y el queso de oveja se puede cambiar por otro?","Nevedel. A dá sa ovčí syr nahradiť iným?"],
 [["cuenta","Yo he traído un poco de bryndza en la maleta, por si acaso.","Priniesla som si v kufri trochu bryndze, pre istotu."],["expl","Lo ideal es la «bryndza», pero un queso fresco de oveja también vale.","Ideálna je bryndza, ale poslúži aj čerstvý ovčí syr."],["opin","Se puede, pero no es lo mismo. Pierde la gracia.","Dá sa, ale nie je to to isté. Stratí to svoje čaro."],["alt","Podemos probar con queso de cabra, a ver qué tal.","Môžeme skúsiť kozí syr, uvidíme."],["hum","Se puede, pero no se lo digas a ningún eslovaco.","Dá sa, ale nehovor to žiadnemu Slovákovi."],["breve","Más o menos. Ya verás.","Viac-menej. Uvidíš."]],
 ["¡Has traído bryndza! Eres la mejor. ¿Por dónde empezamos?","Priniesla si bryndzu! Si najlepšia. Kde začneme?"],
 [["hum","Primero nos ponemos el delantal, que esto mancha.","Najprv si dáme zásteru, toto špiní."],["expl","Primero pelamos y rallamos las patatas crudas.","Najprv ošúpeme a nastrúhame surové zemiaky."],["si","Por las patatas. Pélalas tú mientras pongo el agua a hervir.","Zemiakmi. Ošúp ich, kým dám variť vodu."],["ofre","Yo te guío y tú lo haces todo. Así aprendes de verdad.","Ja ťa budem viesť a ty urobíš všetko. Tak sa naozaj naučíš."],["cuenta","Mi madre empezaba siempre friendo el beicon. Huele de maravilla.","Moja mama vždy začínala opekaním slaniny. Krásne to vonia."],["preg","¿Tienes una olla grande?","Máš veľký hrniec?"]],
 ["Vale, delantal puesto. ¡A rallar patatas!","Dobre, zástera je na mne. Ideme strúhať zemiaky!"]
]);
D("kitchen",["¿Quién friega?","Kto bude umývať riad?"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["Mamá, deja los platos. Hoy friego yo.","Mami, nechaj taniere. Dnes umývam ja."],
 [["preg","¿Seguro? ¿No tenías que irte pronto?","Si si istý? Nemal si odísť skoro?"],["grac","¡Gracias, hijo! Te lo agradezco mucho.","Ďakujem, synček! Veľmi si to vážim."],["no","No te preocupes, si son cuatro platos.","Nerob si starosti, sú to štyri taniere."],["alt","Mejor friegas tú y yo seco. Así acabamos antes.","Radšej ty umývaj a ja utieram. Tak to skôr skončíme."],["hum","¿Tú? ¿Fregar? ¿Estás enfermo?","Ty? Umývať? Nie si chorý?"],["si","Vale, pero ten cuidado con las copas, que son de tu abuela.","Dobre, ale opatrne s pohármi, sú po tvojej starej mame."]],
 ["Seguro. Siéntate en el sofá y descansa un rato, que has cocinado tú.","Istý. Sadni si na gauč a chvíľu si oddýchni, varila si ty."],
 [["breve","Gracias, cariño.","Ďakujem, zlatko."],["si","Pues no te digo que no. Me vendrá bien.","Tak nepoviem nie. Prospeje mi to."],["cari","Qué bien te he educado, ¿eh?","Ako dobre som ťa vychovala, čo?"],["duda","Me cuesta estar sentada mientras otros trabajan.","Ťažko sa mi sedí, kým iní pracujú."],["hum","Vale, pero desde el sofá te voy a dar instrucciones.","Dobre, ale z gauča ti budem dávať pokyny."],["expl","El lavavajillas no funciona bien; mejor a mano.","Umývačka dobre nefunguje; radšej ručne."]],
 ["¿Dónde se guardan las sartenes? Nunca me acuerdo.","Kam sa odkladajú panvice? Nikdy si nepamätám."],
 [["expl","En el armario de abajo, a la izquierda del horno.","V spodnej skrinke, vľavo od rúry."],["hum","Donde llevan treinta años: debajo del horno.","Tam, kde sú už tridsať rokov: pod rúrou."],["ofre","Déjalas en la encimera, que luego las guardo yo.","Nechaj ich na linke, potom ich odložím ja."],["preg","¿Las has secado bien? Que se oxidan.","Dobre si ich vysušil? Inak hrdzavejú."],["cari","En el cajón grande. Muchas gracias por todo, hijo.","Vo veľkej zásuvke. Veľmi pekne ďakujem za všetko, synček."],["breve","Abajo a la izquierda.","Dole vľavo."]],
 ["Hecho. Cocina limpia. ¿Ves como no soy un desastre?","Hotovo. Kuchyňa je čistá. Vidíš, že nie som katastrofa?"]
]);
D("home",["El desorden del salón","Neporiadok v obývačke"],["Tu nieto Pablo, de catorce años","Tvoj štrnásťročný vnuk Pablo"],[
 ["¿Qué pasa, abuela? Te veo seria.","Čo sa deje, babi? Vyzeráš vážne."],
 [["lim","Necesito que recojas tus cosas del sofá antes de cenar.","Potrebujem, aby si si pred večerou upratal veci z gauča."],["expl","Pablo, el salón está lleno de tus cosas desde ayer.","Pablo, obývačka je od včera plná tvojich vecí."],["preg","¿Me ayudas a recoger el salón antes de que vengan tus padres?","Pomôžeš mi upratať obývačku, kým prídu tvoji rodičia?"],["hum","Nada, que creo que en el salón vive un adolescente.","Nič, len si myslím, že v obývačke býva tínedžer."],["cari","No estoy enfadada, solo cansada. ¿Me echas una mano?","Nehnevám sa, som len unavená. Pomôžeš mi?"],["breve","Las zapatillas, la mochila, los cables...","Tenisky, batoh, káble..."]],
 ["Uf, vale... Pero es que luego lo voy a volver a usar todo.","Uf, dobre... Ale veď to potom budem zase všetko používať."],
 [["preg","¿Qué te parece si dejamos una caja para tus cosas?","Čo keby sme tu nechali krabicu na tvoje veci?"],["lim","Lo entiendo, pero el salón es de todos. Tu cuarto es tuyo.","Chápem, ale obývačka je pre všetkých. Tvoja izba je tvoja."],["alt","Vale: deja aquí lo que uses hoy y el resto a tu cuarto.","Dobre: nechaj tu, čo dnes použiješ, a zvyšok do izby."],["hum","Y la cama la vuelves a usar por la noche, y aun así la haces.","Aj posteľ zase v noci použiješ, a predsa si ju ustelieš."],["expl","Es que la abuela se tropieza con los cables y me da miedo caerme.","Babka zakopáva o káble a bojím sa, že spadnem."],["opin","A mí me cuesta descansar con todo desordenado.","Mne sa ťažko oddychuje, keď je všade neporiadok."]],
 ["Lo de la caja está bien. ¿Y si tiro algo dentro, ya cuenta como recogido?","Tá krabica je dobrý nápad. A keď niečo hodím dnu, počíta sa to ako upratané?"],
 [["si","Sí, mientras quede todo dentro de la caja, me vale.","Áno, kým bude všetko v krabici, stačí mi to."],["hum","Cuenta como «casi recogido». Es un buen comienzo.","Počíta sa to ako „takmer upratané“. Je to dobrý začiatok."],["lim","Vale, pero los cables me los recoges bien, por favor.","Dobre, ale káble mi poriadne odlož, prosím."],["grac","Trato hecho. Gracias por entenderlo.","Platí. Ďakujem, že si to pochopil."],["cari","Me vale. Y luego te hago tu merienda favorita.","Stačí. A potom ti urobím tvoj obľúbený olovrant."],["breve","Vale, trato hecho.","Dobre, platí."]],
 ["¡Trato hecho! Dame cinco minutos y te dejo el salón como nuevo.","Platí! Daj mi päť minút a obývačka bude ako nová."]
]);
D("home",["La calefacción","Kúrenie"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["Hace un calor aquí dentro... ¿Bajamos un poco la calefacción?","Je tu dnu ale teplo... Stiahneme trochu kúrenie?"],
 [["preg","¿A cuánto está ahora el termostato?","Na koľko je teraz nastavený termostat?"],["si","Vale, bájala un par de grados.","Dobre, stiahni ho o pár stupňov."],["no","Uy, no, que yo estoy helada.","Oj, nie, ja som celá zmrznutá."],["alt","Mejor abre un poco la ventana diez minutos.","Radšej na desať minút trochu otvor okno."],["hum","Será que te has puesto el jersey gordo otra vez.","Asi si si zase dal ten hrubý sveter."],["duda","Un poco, pero no mucho, que por la noche refresca.","Trochu, ale nie veľa, v noci sa ochladí."]],
 ["Está a veintitrés. Y el recibo del gas del mes pasado fue carísimo.","Je na dvadsaťtri. A účet za plyn za minulý mesiac bol strašne drahý."],
 [["alt","¿Y si bajamos la calefacción en las habitaciones que no usamos?","A čo keby sme stiahli kúrenie v izbách, ktoré nepoužívame?"],["si","Pues ponlo a veintiuno y yo me pongo una chaqueta.","Tak ho daj na dvadsaťjeden a ja si oblečiem sveter."],["opin","Tienes razón; tenemos que ahorrar un poco.","Máš pravdu; musíme trochu šetriť."],["preg","¿Cuánto vino? No me lo habías dicho.","Koľko prišlo? Nepovedal si mi."],["expl","Es que yo paso mucho tiempo quieta leyendo y me enfrío.","Ja veľa času presedím pri čítaní a prechladnem."],["hum","Veintitrés grados es el clima de mi infancia en verano.","Dvadsaťtri stupňov je klíma môjho detstva v lete."]],
 ["Buena idea lo de las habitaciones. Y te regalo una manta para el sillón, ¿vale?","Dobrý nápad s tými izbami. A darujem ti deku do kresla, dobre?"],
 [["preg","¿Y tú qué vas a hacer para ahorrar?","A čo budeš robiť ty, aby sme ušetrili?"],["grac","Me parece perfecto. Gracias por pensar en mí.","Výborne. Ďakujem, že na mňa myslíš."],["cari","Con una manta y tu compañía no necesito calefacción.","S dekou a tvojou spoločnosťou nepotrebujem kúrenie."],["hum","Que sea de cuadros, como la de mi madre.","Nech je kockovaná, ako mala moja mama."],["si","Vale, trato hecho. Veintiún grados y manta.","Dobre, platí. Dvadsaťjeden stupňov a deka."],["breve","Me parece bien.","Súhlasím."]],
 ["Yo apagaré la tele cuando me quede dormido en el sofá. ¡Prometido!","Ja vypnem telku, keď zaspím na gauči. Sľubujem!"]
]);
D("home",["Turnos para el baño","Poradie v kúpeľni"],["Tu hija Laura, durante una visita","Tvoja dcéra Laura počas návštevy"],[
 ["Mamá, por las mañanas el baño parece la estación de tren. ¿Nos organizamos?","Mami, ráno je kúpeľňa ako železničná stanica. Zorganizujeme sa?"],
 [["opin","Buena idea. Así no hay prisas ni discusiones.","Dobrý nápad. Tak nebude zhon ani hádky."],["si","Sí, por favor. Esta mañana he esperado veinte minutos.","Áno, prosím. Dnes ráno som čakala dvadsať minút."],["preg","¿Cómo lo hacéis en vuestra casa?","Ako to robíte u vás doma?"],["hum","Sí, y el que más tarda es tu padre, aunque no lo reconozca.","Áno, a najdlhšie to trvá tvojmu otcovi, aj keď to nepriznáva."],["alt","Yo puedo ducharme por la noche; así dejo libre la mañana.","Ja sa môžem sprchovať večer; ráno tak nechám voľné."],["breve","Sí, nos hace falta.","Áno, treba to."]],
 ["Los niños entran a las ocho al cole. Podrían ducharse ellos primero, a las siete.","Deti idú do školy na ôsmu. Mohli by sa osprchovať prví, o siedmej."],
 [["preg","¿Y el desayuno? ¿Lo preparo mientras se duchan?","A raňajky? Mám ich pripraviť, kým sa sprchujú?"],["si","Perfecto. Yo me ducho después, a las ocho y cuarto.","Výborne. Ja sa osprchujem potom, o osem pätnásť."],["duda","A las siete los niños están dormidos como troncos.","O siedmej deti spia ako zabité."],["ofre","Si quieres, los despierto yo, que madrugo mucho.","Ak chceš, zobudím ich ja, aj tak vstávam skoro."],["hum","Me parece bien, siempre que dejen algo de agua caliente.","Súhlasím, pokiaľ nechajú trochu teplej vody."],["lim","Bien, pero necesito el baño libre un rato a las nueve.","Dobre, ale o deviatej potrebujem chvíľu voľnú kúpeľňu."]],
 ["¡Gracias, mamá! Si preparas tú el desayuno, me salvas la mañana.","Ďakujem, mami! Ak urobíš raňajky ty, zachrániš mi ráno."],
 [["preg","¿Qué desayunan los niños? ¿Cereales o tostadas?","Čo deti raňajkujú? Cereálie alebo hrianky?"],["si","Hecho. Tostadas con tomate para todos.","Platí. Hrianky s paradajkami pre všetkých."],["cari","Para eso están las abuelas. Me encanta hacerlo.","Na to sú babky. Rada to robím."],["hum","Hecho, pero el café me lo sirvo yo primero.","Platí, ale kávu si najprv nalejem ja."],["lim","Encantada, pero solo mientras estemos aquí, ¿eh?","Rada, ale len kým sme tu, jasné?"],["breve","Cuenta conmigo.","Môžeš so mnou rátať."]],
 ["Cereales los dos. ¡Organizadas como un reloj suizo!","Obaja cereálie. Zorganizované ako švajčiarske hodinky!"]
]);
D("home",["Un vecino ruidoso","Hlučný sused"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["¿Has oído al vecino de arriba esta noche? Otra vez con la música hasta las dos.","Počula si v noci suseda zhora? Zase hudba do druhej."],
 [["apoyo","Sí, y tú tienes que madrugar. Hay que hacer algo.","Áno, a ty musíš vstávať skoro. Treba niečo urobiť."],["si","Sí, no he pegado ojo en toda la noche.","Áno, celú noc som ani oka nezažmúrila."],["preg","¿Otra vez? ¿Es la tercera noche esta semana, no?","Zase? To je tento týždeň tretia noc, nie?"],["hum","Sí, aunque la canción de las doce no estaba nada mal.","Áno, aj keď tá pieseň o polnoci nebola zlá."],["duda","Algo he oído, pero no tanto como tú.","Niečo som počula, ale nie toľko ako ty."],["breve","Sí, horrible.","Áno, strašné."]],
 ["Estoy pensando en subir a decírselo. ¿Te parece buena idea?","Rozmýšľam, že pôjdem hore a poviem mu to. Je to podľa teba dobrý nápad?"],
 [["ofre","Si quieres, subo contigo.","Ak chceš, pôjdem s tebou."],["si","Sí, pero con calma. A lo mejor no se da cuenta.","Áno, ale pokojne. Možno si to neuvedomuje."],["alt","Mejor le dejamos una nota amable en el buzón.","Radšej mu nechajme milý odkaz v schránke."],["opin","Primero habla con él; si sigue igual, con el presidente de la comunidad.","Najprv sa porozprávaj s ním; ak sa nič nezmení, so správcom domu."],["duda","No sé... No quiero que haya mal ambiente en la escalera.","Neviem... Nechcem, aby bola na chodbe zlá atmosféra."],["hum","Sí, pero ponte una camisa, no vayas en pijama.","Áno, ale obleč si košeľu, nechoď v pyžame."]],
 ["Vale. Subimos juntos esta tarde. ¿Qué le decimos?","Dobre. Pôjdeme spolu poobede. Čo mu povieme?"],
 [["expl","Que nos alegra que tenga vida social, pero que entre semana necesitamos dormir.","Že sa tešíme, že má spoločenský život, ale cez týždeň potrebujeme spať."],["form","Que por favor baje la música a partir de las once.","Aby, prosím, stlmil hudbu od jedenástej."],["cari","Lo presentamos bien: somos vecinos y queremos llevarnos bien.","Podáme to pekne: sme susedia a chceme dobré vzťahy."],["preg","¿Y si le preguntamos si sabe que el sonido baja tanto?","A čo keby sme sa ho spýtali, či vie, že zvuk ide tak dolu?"],["hum","Que si pone música, que al menos sea de nuestra época.","Že ak už púšťa hudbu, nech je aspoň z našej doby."],["lim","Que lo entendemos un fin de semana, pero no a diario.","Že cez víkend to chápeme, ale nie každý deň."]],
 ["Me gusta: amables pero claros. Esta tarde subimos.","Páči sa mi to: milo, ale jasne. Poobede pôjdeme hore."]
]);
D("home",["Las plantas mientras no estamos","Kvety, keď nie sme doma"],["Tu vecina Encarna","Tvoja susedka Encarna"],[
 ["Me ha dicho tu marido que os vais dos semanas de viaje. ¿Necesitáis algo?","Manžel mi povedal, že idete na dva týždne na cesty. Potrebujete niečo?"],
 [["si","Pues sí, ¿podrías regarnos las plantas?","No áno, mohla by si nám polievať kvety?"],["grac","¡Qué amable! Justo te iba a pedir un favor.","Aká si milá! Práve som ťa chcela poprosiť o láskavosť."],["duda","No queremos molestarte, pero las plantas nos preocupan.","Nechceme ťa obťažovať, ale kvety nám robia starosti."],["preg","¿Tú vas a estar aquí en agosto?","Ty tu budeš v auguste?"],["no","Gracias, de momento creo que nos apañamos.","Ďakujem, zatiaľ si myslím, že to zvládneme."],["form","Muchas gracias por ofrecerte. Te lo agradecemos de corazón.","Veľmi pekne ďakujeme, že sa ponúkaš. Zo srdca ďakujeme."]],
 ["Claro, mujer. Déjame una llave y dime cada cuánto hay que regarlas.","Jasné. Nechaj mi kľúč a povedz mi, ako často ich treba polievať."],
 [["preg","¿Te va bien pasar por la tarde, cuando ya no da el sol?","Vyhovuje ti prísť poobede, keď už nesvieti slnko?"],["expl","Las de la terraza, cada dos días. Las de dentro, una vez por semana.","Tie na terase každý druhý deň. Tie vnútri raz týždenne."],["ofre","Te dejo una nota con todo apuntado en la cocina.","Nechám ti v kuchyni odkaz, kde bude všetko zapísané."],["hum","Riégalas cuando parezcan tristes; las conocerás enseguida.","Polievaj ich, keď budú vyzerať smutne; hneď ich spoznáš."],["lim","Solo las de la terraza; las de dentro aguantan solas.","Len tie na terase; tie vnútri vydržia samy."],["cari","Eres un tesoro, Encarna. No sé qué haríamos sin ti.","Si poklad, Encarna. Neviem, čo by sme bez teba robili."]],
 ["Por la tarde perfecto. Y no os preocupéis, que las trato como si fueran mías.","Poobede je to perfektné. A nebojte sa, budem sa o ne starať ako o svoje."],
 [["preg","¿Te mandamos fotos del viaje?","Máme ti posielať fotky z cesty?"],["grac","Gracias. A la vuelta te traemos algo bonito.","Ďakujeme. Po návrate ti prinesieme niečo pekné."],["cari","Lo sé. Por eso te lo pido a ti.","Viem. Preto ťa o to prosím."],["hum","Mejor que las tuyas no, que están más bonitas que las nuestras.","Radšej nie ako svoje, tie sú krajšie ako naše."],["ofre","Y si tú necesitas algo en septiembre, cuenta con nosotros.","A keby si v septembri potrebovala niečo ty, môžeš rátať s nami."],["breve","Mil gracias, de verdad.","Tisíckrát vďaka, naozaj."]],
 ["¡Sí, mandadme fotos! Y disfrutad mucho, que os lo merecéis.","Áno, posielajte fotky! A užite si to, zaslúžite si to."]
]);
D("plans",["¿Qué hacemos el sábado?","Čo budeme robiť v sobotu?"],["Tu hija Laura","Tvoja dcéra Laura"],[
 ["Este sábado lo tenemos libre. ¿Os apetece hacer algo todos juntos?","Túto sobotu máme voľno. Máte chuť niečo podniknúť všetci spolu?"],
 [["si","¡Claro! ¿Qué tenéis pensado?","Jasné! Čo máte v pláne?"],["alt","Podríamos ir de excursión a la sierra, si hace bueno.","Mohli by sme ísť na výlet do hôr, ak bude pekne."],["opin","A mí me apetece algo tranquilo, como un paseo y comer fuera.","Ja mám chuť na niečo pokojné, napríklad prechádzku a obed vonku."],["duda","Me apetece, pero no puedo caminar mucho últimamente.","Mám chuť, ale v poslednom čase nevládzem veľa chodiť."],["hum","Me apetece cualquier cosa que no sea madrugar.","Mám chuť na čokoľvek okrem skorého vstávania."],["preg","¿Los niños tienen algún partido o actividad?","Majú deti nejaký zápas alebo krúžok?"]],
 ["Los niños quieren ir al zoo, pero Andrés prefiere ir a la playa. ¿Tú qué prefieres?","Deti chcú ísť do zoo, ale Andrés by radšej išiel na pláž. Čo by si chcela ty?"],
 [["alt","¿Y si vamos al zoo por la mañana y a la playa por la tarde?","A čo keby sme išli ráno do zoo a poobede na pláž?"],["opin","Yo votaría por el zoo; a los niños les hace mucha ilusión.","Ja by som hlasovala za zoo; deti sa veľmi tešia."],["expl","A mí la playa me cansa mucho con este calor.","Mňa pláž v tomto teple veľmi unavuje."],["cari","Yo me apunto a lo que diga la mayoría.","Ja sa pridám k tomu, čo povie väčšina."],["hum","Yo prefiero el zoo; en la playa el que parece un león marino soy yo.","Ja radšej zoo; na pláži vyzerám ako lachtan ja."],["preg","¿Qué es más barato? Las entradas del zoo son caras.","Čo je lacnejšie? Vstupenky do zoo sú drahé."]],
 ["¡Buena idea, las dos cosas! Aunque será un día largo. ¿Aguantarás?","Dobrý nápad, oboje! Aj keď to bude dlhý deň. Vydržíš?"],
 [["preg","¿Habrá sitio para sentarse en el zoo?","Bude sa dať v zoo niekde sadnúť?"],["si","Claro que sí. Me llevo un sombrero y agua.","Jasné, že áno. Vezmem si klobúk a vodu."],["lim","Por la mañana sí; por la tarde quizá me quedo a descansar.","Ráno áno; poobede možno zostanem odpočívať."],["hum","Si hay una sombrilla y una silla, aguanto lo que sea.","Ak bude slnečník a stolička, vydržím čokoľvek."],["alt","Mejor me recogéis después del zoo y vuelvo a casa.","Radšej ma po zoo odvezte domov."],["cari","Con mis nietos aguanto hasta las diez de la noche.","So svojimi vnúčatami vydržím do desiatej večer."]],
 ["Hay bancos por todas partes. ¡Decidido! Salimos a las diez y vamos a buscaros.","Lavičky sú všade. Rozhodnuté! Vyrazíme o desiatej a prídeme po vás."]
]);
D("plans",["Ir al cine","Ísť do kina"],["Tu nieto Pablo","Tvoj vnuk Pablo"],[
 ["Abuelo, ¿te vienes conmigo al cine esta tarde? Hay una peli de aventuras.","Dedo, pôjdeš so mnou dnes poobede do kina? Dávajú dobrodružný film."],
 [["preg","¿De qué va la película?","O čom je ten film?"],["si","¡Me encantaría! ¿A qué hora es?","Veľmi rád! O koľkej je?"],["duda","¿No es de esas con muchas explosiones? Me duelen los oídos.","Nie je to jeden z tých s množstvom výbuchov? Bolia ma z toho uši."],["hum","¿Yo? ¿Al cine con un adolescente? ¿Qué dirán tus amigos?","Ja? Do kina s tínedžerom? Čo povedia tvoji kamaráti?"],["cari","Que me invites tú me hace muy feliz.","Veľmi ma teší, že ma pozývaš."],["alt","Hoy no puedo, pero ¿qué tal mañana?","Dnes nemôžem, ale čo zajtra?"]],
 ["Va de unos exploradores en la selva. Hay sesión a las cinco y a las siete y media.","Je o prieskumníkoch v džungli. Hrajú o piatej a o pol ôsmej."],
 [["si","Mejor a las cinco, que luego cenamos tranquilos.","Radšej o piatej, potom sa v pokoji navečeriame."],["alt","A las siete y media, que antes tengo que ir al banco.","O pol ôsmej, predtým musím ísť do banky."],["preg","¿Es en versión original o doblada?","Je to v pôvodnom znení alebo dabované?"],["hum","¡Selva! Lo más salvaje que he visto yo es tu habitación.","Džungľa! Najdivokejšie, čo som videl, je tvoja izba."],["cuenta","Cuando era joven, iba al cine todos los domingos.","Keď som bol mladý, chodil som do kina každú nedeľu."],["breve","A las cinco. Perfecto.","O piatej. Výborne."]],
 ["A las cinco, entonces. Yo compro las entradas por internet. ¿Y las palomitas quién las paga?","Tak o piatej. Lístky kúpim cez internet. A kto zaplatí popcorn?"],
 [["hum","Tú las entradas y yo las palomitas, pero las grandes.","Ty lístky a ja popcorn, ale veľký."],["si","Las palomitas las pago yo, faltaría más.","Popcorn platím ja, to je samozrejmé."],["ofre","Lo pago todo yo. Para algo soy tu abuelo.","Zaplatím všetko ja. Na niečo som predsa tvoj dedko."],["lim","Palomitas sí, pero nada de refrescos, que luego no duermes.","Popcorn áno, ale žiadne limonády, potom nespíš."],["preg","¿Cuánto cuestan las entradas? Te doy el dinero.","Koľko stoja lístky? Dám ti peniaze."],["cari","Lo que quieras, campeón. Hoy es nuestro día.","Čokoľvek chceš, šampión. Dnes je náš deň."]],
 ["¡Genial! Paso a buscarte a las cuatro y media.","Super! Prídem po teba o pol piatej."]
]);
D("plans",["Un plan que cambia","Plán, ktorý sa mení"],["Tu amiga Maribel","Tvoja kamarátka Maribel"],[
 ["Oye, al final ha anunciado lluvia para mañana. ¿Seguimos con la excursión al lago?","Počuj, nakoniec na zajtra hlásia dážď. Ideme aj tak na výlet k jazeru?"],
 [["preg","¿A qué hora dicen que empieza a llover?","O koľkej vraj začne pršať?"],["duda","Con lluvia no sé... El camino se pone muy resbaladizo.","V daždi neviem... Chodník je potom veľmi šmykľavý."],["alt","Mejor lo dejamos para el domingo, que dan sol.","Radšej to presuňme na nedeľu, hlásia slnko."],["si","Yo voy igual. Con un buen chubasquero, no pasa nada.","Ja idem aj tak. S dobrou pláštenkou sa nič nedeje."],["hum","Bueno, el lago ya está mojado, poco más nos podemos mojar.","No, jazero je už mokré, viac sa už nezmočíme."],["opin","Yo prefiero no arriesgarme. No tenemos veinte años.","Ja by som radšej neriskovala. Nemáme dvadsať."]],
 ["Dicen que a partir de mediodía. Podríamos ir temprano y volver antes de comer.","Vraj od obeda. Mohli by sme ísť skoro a vrátiť sa pred obedom."],
 [["alt","O hacemos un plan de lluvia: museo y café.","Alebo urobíme plán do dažďa: múzeum a kávu."],["si","Buena idea. Quedamos a las ocho, entonces.","Dobrý nápad. Tak sa stretneme o ôsmej."],["duda","Es un poco justo, pero podemos intentarlo.","Je to trochu natesno, ale môžeme to skúsiť."],["hum","¿A las ocho? Para eso necesito dos cafés.","O ôsmej? Na to potrebujem dve kávy."],["ofre","Yo conduzco, así vamos más rápido.","Ja budem šoférovať, tak to bude rýchlejšie."],["preg","¿Y si nos pilla la lluvia a mitad de camino?","A čo ak nás dážď zastihne v polovici cesty?"]],
 ["Me gusta lo del museo como plan B. Si a las siete llueve, vamos al museo.","Páči sa mi múzeum ako plán B. Ak bude o siedmej pršať, ideme do múzea."],
 [["hum","Trato hecho. Yo rezo por la lluvia, que me apetece el museo.","Platí. Budem sa modliť za dážď, mám chuť na múzeum."],["si","Perfecto. Te escribo a las siete y decidimos.","Výborne. O siedmej ti napíšem a rozhodneme."],["cari","Lo importante es pasar el día juntas, sea donde sea.","Dôležité je stráviť deň spolu, nech je to kdekoľvek."],["expl","En el museo hay una exposición de fotografía que quería ver.","V múzeu je výstava fotografií, ktorú som chcela vidieť."],["preg","¿Llevo bocadillos para cualquiera de los dos planes?","Mám zobrať sendviče pre ktorýkoľvek plán?"],["breve","Hecho. Hasta mañana.","Platí. Do zajtra."]],
 ["¡Ja, ja! Pues mira, a lo mejor me contagias. Hasta mañana.","Ha-ha! Možno ma nakazíš. Do zajtra."]
]);
D("plans",["Las vacaciones de verano","Letná dovolenka"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["Estamos pensando en alquilar una casa en la costa en agosto. ¿Os venís?","Rozmýšľame, že si v auguste prenajmeme dom pri mori. Pôjdete s nami?"],
 [["si","¡Nos encantaría! ¿Dónde estáis mirando?","Veľmi radi! Kde sa pozeráte?"],["preg","¿Cuántos días serían? Tenemos médico a mediados de agosto.","Koľko dní by to bolo? V polovici augusta máme lekára."],["duda","Nos apetece, pero agosto en la costa es muy caluroso para nosotros.","Máme chuť, ale august pri mori je pre nás veľmi horúci."],["cari","Pasar unos días con vosotros sería un regalo.","Stráviť s vami pár dní by bol darček."],["alt","¿Y si venimos solo una semana, para no estar encima?","A čo keby sme prišli len na týždeň, aby sme vám neprekážali?"],["ofre","Nos apuntamos, y pagamos nuestra parte, claro.","Pridáme sa a zaplatíme svoju časť, samozrejme."]],
 ["En Asturias, que no hace tanto calor. Serían dos semanas, pero podéis venir los días que queráis.","V Astúrii, tam nie je také teplo. Boli by to dva týždne, ale môžete prísť na koľko dní chcete."],
 [["preg","¿La casa tiene habitación en la planta baja? Por las escaleras.","Má dom izbu na prízemí? Kvôli schodom."],["si","¡Asturias! Entonces sí, nos venimos la primera semana.","Astúria! Tak potom áno, prídeme na prvý týždeň."],["cuenta","Siempre he querido conocer Asturias. Dicen que es verde como Eslovaquia.","Vždy som chcela spoznať Astúriu. Vraj je zelená ako Slovensko."],["hum","¿Asturias? Allí al menos no me derretiré.","Astúria? Tam sa aspoň neroztopím."],["ofre","Si queréis salir alguna noche solos, nos quedamos con los niños.","Ak budete chcieť ísť niektorý večer von sami, zostaneme s deťmi."],["expl","Una semana nos parece perfecto; más tiempo nos cansaría.","Týždeň nám úplne vyhovuje; dlhšie by nás unavilo."]],
 ["Sí, hay un dormitorio abajo, no te preocupes. Y oye... ¿os quedaríais con los niños alguna noche?","Áno, dole je spálňa, nebojte sa. A počujte... postrážili by ste deti niektorý večer?"],
 [["si","Claro. Las noches que queráis.","Jasné. Ktorékoľvek večery chcete."],["lim","Encantados, pero una o dos noches, que también queremos descansar.","Radi, ale jeden-dva večery, aj my si chceme oddýchnuť."],["hum","Sí, pero cenamos patatas fritas y nos acostamos tarde.","Áno, ale budeme večerať hranolky a pôjdeme spať neskoro."],["cari","Con mucho gusto. Os merecéis un rato para vosotros.","S radosťou. Zaslúžite si chvíľu pre seba."],["preg","¿A qué hora se acuestan ahora los niños?","O koľkej teraz deti chodia spať?"],["breve","Por supuesto.","Samozrejme."]],
 ["¡Gracias! Os mando fotos de la casa esta noche y reservamos.","Ďakujem! Večer vám pošlem fotky domu a rezervujeme."]
]);
D("plans",["No me apetece salir","Nemám chuť ísť von"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["Los Martínez nos han invitado a cenar esta noche. ¿Vamos?","Martínezovci nás pozvali dnes večer na večeru. Pôjdeme?"],
 [["no","Hoy no me apetece nada. ¿Te importa si lo dejamos para otro día?","Dnes nemám vôbec chuť. Vadilo by ti, keby sme to presunuli?"],["duda","Uf, estoy muy cansada. ¿Es muy importante para ti?","Uf, som veľmi unavená. Je to pre teba veľmi dôležité?"],["si","Vale, pero volvemos pronto, ¿eh?","Dobre, ale vrátime sa skoro, áno?"],["alt","¿Y si les proponemos que vengan ellos el domingo a comer?","A čo keby sme im navrhli, nech prídu oni v nedeľu na obed?"],["expl","Me duele un poco la cabeza desde esta mañana.","Od rána ma trochu bolí hlava."],["hum","¿Esta noche? Si yo a las diez ya estoy en pijama.","Dnes večer? Veď ja som o desiatej už v pyžame."]],
 ["No pasa nada. Pero me sabe mal decirles que no otra vez; ya les dijimos que no el mes pasado.","Nič sa nedeje. Ale je mi ľúto odmietnuť ich znova; už minulý mesiac sme im povedali nie."],
 [["preg","¿Y si los invitamos nosotros la semana que viene?","A čo keby sme ich pozvali my budúci týždeň?"],["opin","Tienes razón. Entonces vamos, pero un rato corto.","Máš pravdu. Tak pôjdeme, ale na kratšie."],["alt","Ve tú solo, y yo me quedo descansando. No me importa.","Choď sám a ja zostanem odpočívať. Nevadí mi to."],["ofre","Llámalos tú y explícales que no estoy bien. Lo entenderán.","Zavolaj im ty a vysvetli, že mi nie je dobre. Pochopia."],["lim","Lo entiendo, pero hoy necesito quedarme en casa.","Chápem, ale dnes potrebujem zostať doma."],["cari","Lo siento, cariño. Sé que te apetecía mucho.","Prepáč, zlatko. Viem, že si sa veľmi tešil."]],
 ["Vale, les llamo y los invito a comer el domingo. Así no quedamos mal. ¿Te parece?","Dobre, zavolám im a pozvem ich v nedeľu na obed. Tak nebudeme vyzerať zle. Čo povieš?"],
 [["cari","Sí. Y esta noche vemos una peli en el sofá, ¿vale?","Áno. A dnes večer si pozrieme film na gauči, dobre?"],["si","Me parece perfecto. Y hago la tarta de manzana que les gusta.","Výborne. A upečiem jablkový koláč, čo im chutí."],["grac","Gracias por entenderme. Eres un cielo.","Ďakujem, že ma chápeš. Si zlatý."],["hum","Perfecto. El domingo, maquillada y con energía, te lo prometo.","Výborne. V nedeľu budem nalíčená a plná energie, sľubujem."],["ofre","Si quieres, los llamo yo para disculparme.","Ak chceš, zavolám im ja a ospravedlním sa."],["breve","Me parece bien.","Súhlasím."]],
 ["Hecho. Y la peli la elijo yo, que hoy me lo he ganado.","Platí. A film vyberiem ja, dnes som si to zaslúžil."]
]);
D("errands",["Recoger un paquete","Vyzdvihnúť balík"],["Tu hija Laura, por mensaje","Tvoja dcéra Laura, správou"],[
 ["Mamá, ¿me podrías hacer un favor? Me llega un paquete a correos y yo trabajo hasta las ocho.","Mami, mohla by si mi urobiť láskavosť? Na poštu mi príde balík a ja pracujem do ôsmej."],
 [["preg","¿Qué oficina de correos es? ¿La de la plaza?","Ktorá pošta je to? Tá na námestí?"],["si","Claro, hija. ¿Qué tengo que llevar?","Jasné, dcérka. Čo si mám zobrať?"],["duda","Hoy tengo médico, pero mañana por la mañana sí puedo.","Dnes mám lekára, ale zajtra ráno môžem."],["cari","Para eso estamos. Dime qué necesitas.","Na to sme tu. Povedz, čo potrebuješ."],["hum","¿Pesa mucho? Que mis brazos ya no son lo que eran.","Je ťažký? Moje ruky už nie sú, čo bývali."],["breve","Sí, dime.","Áno, hovor."]],
 ["La de la plaza. Necesitas el código que te mando ahora y tu DNI. No pesa casi nada.","Tá na námestí. Potrebuješ kód, ktorý ti teraz pošlem, a svoj občiansky. Takmer nič neváži."],
 [["preg","¿Con mi documento sirve, aunque el paquete esté a tu nombre?","Bude stačiť môj doklad, aj keď je balík na tvoje meno?"],["si","Perfecto. Voy esta tarde, a las cinco.","Výborne. Pôjdem dnes poobede o piatej."],["expl","Mi documento es extranjero; ¿crees que me lo aceptarán?","Mám zahraničný doklad; myslíš, že ho prijmú?"],["ofre","Si quieres, te lo llevo luego a casa.","Ak chceš, potom ti ho zanesiem domov."],["hum","Vale. ¿No será un regalo para mí, por casualidad?","Dobre. Nie je to náhodou darček pre mňa?"],["breve","Vale, mándamelo.","Dobre, pošli mi ho."]],
 ["Creo que necesitas también una autorización firmada. Te la mando en foto. ¡Mil gracias!","Myslím, že potrebuješ aj podpísané splnomocnenie. Pošlem ti ho na fotke. Tisíckrát vďaka!"],
 [["preg","¿La imprimo o vale con enseñarla en el móvil?","Mám ho vytlačiť, alebo stačí ukázať v mobile?"],["si","Perfecto. Te escribo cuando lo tenga.","Výborne. Napíšem ti, keď ho budem mať."],["cari","De nada, cariño. Y descansa un poco esta noche.","Niet za čo, zlatko. A večer si trochu oddýchni."],["hum","Vale. Si no me lo dan, monto un escándalo.","Dobre. Ak mi ho nedajú, urobím škandál."],["ofre","Y si quieres, de paso te compro el pan.","A ak chceš, cestou ti kúpim chlieb."],["breve","Recibido.","Prijaté."]],
 ["Mejor impresa, por si acaso. ¡Y otra vez gracias, mamá!","Radšej vytlačenú, pre istotu. A ešte raz vďaka, mami!"]
]);
D("errands",["Pedir prestado el coche","Požičať si auto"],["Tu nieto Pablo, de dieciocho años","Tvoj osemnásťročný vnuk Pablo"],[
 ["Abuelo, ¿me dejarías el coche el viernes? Quiero llevar a unos amigos a un concierto.","Dedo, požičal by si mi v piatok auto? Chcem vziať kamarátov na koncert."],
 [["duda","Hmm... ¿Desde cuándo tienes el carné?","Hmm... Odkedy máš vodičák?"],["preg","¿Dónde es el concierto? ¿Hay que ir por autopista?","Kde je ten koncert? Treba ísť po diaľnici?"],["lim","Te lo dejo, pero con condiciones.","Požičiam ti ho, ale s podmienkami."],["no","Lo siento, pero el viernes lo necesito yo.","Prepáč, ale v piatok ho potrebujem ja."],["si","Claro, si conduces con cuidado.","Jasné, ak budeš jazdiť opatrne."],["hum","¿Mi coche? ¿El que es más viejo que tú?","Moje auto? To, čo je staršie ako ty?"]],
 ["Tengo el carné desde hace cuatro meses. El concierto es en la ciudad, a veinte minutos. Y no bebo, lo prometo.","Vodičák mám štyri mesiace. Koncert je v meste, dvadsať minút odtiaľto. A nebudem piť, sľubujem."],
 [["preg","¿Cuántos amigos vais a ir en el coche?","Koľko kamarátov pôjde v aute?"],["si","Bien. Entonces te lo dejo, pero me avisas al llegar.","Dobre. Tak ti ho požičiam, ale daj mi vedieť, keď prídeš."],["lim","Vale, pero tienes que estar de vuelta antes de la una.","Dobre, ale musíš byť späť pred jednou."],["expl","Fíjate en el freno de mano, que a veces se queda enganchado.","Daj pozor na ručnú brzdu, niekedy sa zasekne."],["cari","Me fío de ti. Eres muy responsable.","Verím ti. Si veľmi zodpovedný."],["hum","Y si vuelves con un rasguño, me lo pagas en abrazos.","A ak sa vrátiš so škrabancom, zaplatíš mi objatiami."]],
 ["Seremos cuatro. Y te devuelvo el coche con el depósito lleno, ¿vale?","Budeme štyria. A auto ti vrátim s plnou nádržou, dobre?"],
 [["si","Trato hecho. Las llaves están en la entrada.","Platí. Kľúče sú v predsieni."],["grac","Muy bien pensado. Gracias por ofrecerlo.","Dobre vymyslené. Vďaka, že si to ponúkol."],["hum","Lleno, ¿eh? No a medias como tu padre a tu edad.","Plnou, jasné? Nie polovičnou, ako tvoj otec v tvojom veku."],["lim","Y nada de música a todo volumen, que los vecinos protestan.","A žiadna hudba naplno, susedia sa sťažujú."],["cari","Disfruta mucho del concierto, campeón.","Užite si koncert, šampión."],["breve","Perfecto.","Výborne."]],
 ["¡Gracias, abuelo! Eres el mejor. Te mando un mensaje en cuanto llegue a casa.","Ďakujem, dedo! Si najlepší. Pošlem ti správu, hneď ako prídem domov."]
]);
D("errands",["Ayuda con el banco","Pomoc s bankou"],["Tu yerno Andrés","Tvoj zať Andrés"],[
 ["Me ha dicho Laura que tienes un problema con la aplicación del banco. ¿Te echo una mano?","Laura mi povedala, že máš problém s bankovou aplikáciou. Pomôžem ti?"],
 [["expl","Me pide un código que me llega por mensaje, pero el mensaje no llega.","Pýta odo mňa kód, čo mi príde správou, ale správa neprichádza."],["si","¡Sí, por favor! No consigo entrar desde ayer.","Áno, prosím! Od včera sa neviem prihlásiť."],["grac","Te lo agradecería muchísimo. Me estoy volviendo loca.","Veľmi by som to ocenila. Už z toho šaliem."],["duda","No quiero molestarte, que estás muy ocupado.","Nechcem ťa obťažovať, máš veľa práce."],["hum","Sí. Creo que la aplicación me odia.","Áno. Myslím, že ma tá aplikácia nenávidí."],["preg","¿Tú entiendes de estas cosas?","Ty sa v tom vyznáš?"]],
 ["Ya veo. A ver, ¿el número de teléfono que tiene el banco es el tuyo de ahora?","Aha. Pozrime sa, je číslo, ktoré má banka, tvoje súčasné?"],
 [["expl","Creo que tienen el eslovaco, el antiguo.","Myslím, že majú to slovenské, staré."],["duda","Pues no lo sé. Cambié de número el año pasado.","To neviem. Minulý rok som zmenila číslo."],["preg","¿Cómo puedo saber qué número tienen?","Ako zistím, aké číslo majú?"],["hum","¡Ahí está el problema! Los mensajes se van a Bratislava.","Tak tu je ten problém! Správy idú do Bratislavy."],["si","Sí, sí, es el mismo de siempre.","Áno, áno, je to to isté ako vždy."],["breve","Ni idea.","Netuším."]],
 ["Seguramente es eso. Habrá que ir a la oficina a cambiarlo. ¿Quieres que te acompañe mañana?","Asi je to tým. Bude treba ísť do pobočky a zmeniť ho. Chceš, aby som ťa zajtra odprevadil?"],
 [["hum","Sí. Tú hablas con el banco y yo pongo cara de entender.","Áno. Ty budeš hovoriť s bankou a ja budem robiť, že rozumiem."],["si","Sí, por favor. Con el idioma me lío un poco en el banco.","Áno, prosím. V banke sa s jazykom trochu zamotám."],["grac","Eres un sol. Muchísimas gracias.","Si zlatý. Veľmi pekne ďakujem."],["no","Gracias, ya voy yo sola. Ahora sé qué tengo que pedir.","Ďakujem, pôjdem sama. Teraz už viem, čo mám žiadať."],["preg","¿Qué documentos tengo que llevar?","Aké doklady mám zobrať?"],["ofre","Si me acompañas, luego te invito a un café.","Ak ma odprevadíš, potom ťa pozvem na kávu."]],
 ["Ja, ja. Trato hecho. Lleva el DNI y el móvil nuevo. Paso a buscarte a las diez.","Ha-ha. Platí. Zober si občiansky a nový mobil. Prídem po teba o desiatej."]
]);
D("errands",["Cuidar al perro","Postarať sa o psa"],["Tu hermana Rosa","Tvoja sestra Rosa"],[
 ["¿Podrías quedarte con Toby el fin de semana? Me voy a una boda a Valencia.","Mohla by si si cez víkend nechať Tobyho? Idem na svadbu do Valencie."],
 [["preg","¿Qué tengo que saber? ¿Cuántas veces sale al día?","Čo musím vedieť? Koľkokrát denne chodí von?"],["si","Claro, me encanta Toby. ¿Cuándo me lo traes?","Jasné, Tobyho zbožňujem. Kedy mi ho prinesieš?"],["duda","No sé... Mi piso es pequeño y Toby es muy grande.","Neviem... Môj byt je malý a Toby je veľmi veľký."],["no","Este fin de semana no puedo; vienen mis nietos.","Tento víkend nemôžem; prídu vnúčatá."],["hum","Sí, pero si se come mis zapatillas, me compras otras.","Áno, ale ak mi zje papuče, kúpiš mi nové."],["lim","Puedo sacarlo a pasear, pero que duerma en tu casa.","Môžem ho venčiť, ale nech spí u teba."]],
 ["Sale tres veces: mañana, mediodía y noche. Come solo pienso, nada de comida de casa.","Chodí von trikrát: ráno, na obed a večer. Je len granule, žiadne jedlo z domu."],
 [["preg","¿Se lleva bien con otros perros? En mi calle hay muchos.","Znesie sa s inými psami? Na mojej ulici je ich veľa."],["si","Entendido. Tres paseos y pienso.","Rozumiem. Tri prechádzky a granule."],["hum","¿Nada? ¿Ni un trocito de jamón? Pobre animal.","Nič? Ani kúsok šunky? Chudák zviera."],["expl","El de la noche lo saco temprano, que de noche no me gusta salir.","Večer ho vyvenčím skoro, v noci nerada chodím von."],["ofre","Si quieres, te mando fotos para que estés tranquila.","Ak chceš, pošlem ti fotky, aby si bola pokojná."],["breve","De acuerdo.","Dobre."]],
 ["Con otros perros es un poco celoso; mejor llévalo con correa. ¡Lo voy a echar de menos!","S inými psami je trochu žiarlivý; radšej ho veď na vôdzke. Bude mi chýbať!"],
 [["preg","¿Me dejas también su manta? Así duerme mejor.","Necháš mi aj jeho deku? Lepšie bude spať."],["si","Sin problema. Te mando una foto cada día.","Žiadny problém. Každý deň ti pošlem fotku."],["cari","Lo cuidaré como si fuera mío. Disfruta de la boda.","Postarám sa oňho ako o vlastného. Uži si svadbu."],["hum","Tranquila, que nos vamos a llevar de maravilla.","Neboj, budeme si skvele rozumieť."],["grac","Gracias a ti por confiar en mí.","Vďaka tebe, že mi dôveruješ."],["breve","Prometido.","Sľubujem."]],
 ["Sí, te traigo su manta y su juguete favorito. ¡Eres la mejor hermana!","Áno, prinesiem ti jeho deku a obľúbenú hračku. Si najlepšia sestra!"]
]);
D("errands",["Un favor que no puedes hacer","Láskavosť, ktorú nemôžeš urobiť"],["Tu vecino Ramón","Tvoj sused Ramón"],[
 ["Buenos días. Perdona que te moleste, ¿podrías llevarme mañana al aeropuerto a las seis de la mañana?","Dobré ráno. Prepáč, že obťažujem, mohla by si ma zajtra o šiestej ráno odviezť na letisko?"],
 [["no","Lo siento mucho, Ramón, pero a esa hora no conduzco.","Veľmi ma to mrzí, Ramón, ale v takú hodinu nešoférujem."],["duda","Uf, a las seis... Déjame pensarlo y te digo esta tarde.","Uf, o šiestej... Nechaj ma porozmýšľať a poobede ti dám vedieť."],["alt","Yo no puedo, pero hay un autobús que sale a las cinco y media.","Ja nemôžem, ale o pol šiestej odchádza autobus."],["preg","¿No hay nadie más que pueda llevarte?","Nemá ťa kto iný odviezť?"],["form","Me encantaría ayudarte, pero mañana me es imposible.","Rada by som ti pomohla, ale zajtra to naozaj nejde."],["si","Bueno, por esta vez, sí. Pero me debes un café.","No dobre, tento raz áno. Ale dlhuješ mi kávu."]],
 ["Lo entiendo, no te preocupes. Es que el taxi a esa hora es carísimo.","Chápem, nerob si starosti. Len taxík v takú hodinu je strašne drahý."],
 [["alt","Mi hijo trabaja cerca del aeropuerto. Le pregunto si puede.","Môj syn pracuje pri letisku. Spýtam sa ho, či môže."],["ofre","¿Has mirado el autobús del aeropuerto? Te busco el horario.","Pozrel si sa na letiskový autobus? Vyhľadám ti cestovný poriadok."],["apoyo","Ya, es verdad. Qué faena.","No, to je pravda. To je nepríjemné."],["expl","Hay aplicaciones para compartir coche; a veces es más barato.","Sú aplikácie na spolujazdu; niekedy je to lacnejšie."],["disc","Siento no poder ayudarte esta vez.","Mrzí ma, že ti tentoraz nemôžem pomôcť."],["hum","Lo que cuesta el taxi a esa hora, cuesta el sueño que pierdo yo.","Čo stojí taxík v takú hodinu, toľko stojí spánok, o ktorý prídem ja."]],
 ["¡Lo de tu hijo sería genial! Pero solo si no le complica la vida.","To s tvojím synom by bolo skvelé! Ale len ak mu to neskomplikuje život."],
 [["preg","¿A qué hora sale tu vuelo exactamente?","O koľkej presne ti letí lietadlo?"],["si","Le llamo ahora mismo y te digo algo.","Hneď mu zavolám a dám ti vedieť."],["lim","Le pregunto, pero no te prometo nada.","Spýtam sa ho, ale nič ti nesľubujem."],["cari","Para un buen vecino, lo intentamos.","Pre dobrého suseda to skúsime."],["hum","Le llamo. Si dice que no, el café me lo debes igual.","Zavolám mu. Ak povie nie, kávu mi dlhuješ aj tak."],["breve","Ahora te digo.","Hneď ti poviem."]],
 ["El vuelo sale a las ocho. ¡Mil gracias, de verdad, aunque al final no pueda!","Letím o ôsmej. Tisíckrát vďaka, naozaj, aj keby to nakoniec nevyšlo!"]
]);
D("news",["Una buena noticia","Dobrá správa"],["Tu nieta Lucía, por videollamada","Tvoja vnučka Lucía, cez videohovor"],[
 ["¡Abuela! Tengo una noticia. ¡Me han dado el trabajo de la editorial!","Babi! Mám novinku. Dostala som tú prácu vo vydavateľstve!"],
 [["preg","¡Qué bien! ¿Cuándo empiezas?","To je skvelé! Kedy začínaš?"],["cari","¡Ay, qué alegría! ¡Enhorabuena, mi niña!","Jaj, aká radosť! Blahoželám, dievčatko moje!"],["hum","¿Lo ves? Ya te dije que eras la mejor.","Vidíš? Veď som ti hovorila, že si najlepšia."],["anim","Te lo has ganado con mucho esfuerzo.","Zaslúžila si si to veľkou námahou."],["form","Muchísimas felicidades. Es una gran noticia.","Srdečne blahoželám. Je to skvelá správa."],["colo","¡Toma ya! ¡Qué crack!","No toto! Ty si ale borec!"]],
 ["¡Gracias! Empiezo el lunes. Estoy contentísima, pero también un poco nerviosa.","Ďakujem! Začínam v pondelok. Som šťastná, ale aj trochu nervózna."],
 [["preg","¿Qué te pone más nerviosa?","Čo ťa najviac znervózňuje?"],["apoyo","Es normal estar nerviosa. Eso significa que te importa.","Je normálne byť nervózna. Znamená to, že ti na tom záleží."],["cuenta","Yo el primer día de trabajo no pude ni desayunar de los nervios.","Ja som prvý pracovný deň od nervov ani nevládala raňajkovať."],["anim","Vas a estar genial. Sé tú misma.","Budeš skvelá. Buď sama sebou."],["hum","Nerviosa estaré yo hasta que me llames el lunes por la noche.","Nervózna budem ja, kým mi v pondelok večer nezavoláš."],["cari","Ojalá pudiera estar ahí para darte un abrazo.","Kiežby som tam mohla byť a objať ťa."]],
 ["No conocer a nadie y no saber cómo funciona todo. Pero bueno, ya aprenderé.","To, že nikoho nepoznám a neviem, ako všetko funguje. Ale veď sa to naučím."],
 [["hum","Lleva galletas el primer día. Con galletas, todo el mundo te quiere.","Prvý deň prines sušienky. So sušienkami ťa má každý rád."],["anim","Claro que sí. Pregunta todo lo que necesites; nadie nace sabiendo.","Jasné, že áno. Pýtaj sa na všetko, čo potrebuješ; nikto sa nenarodil múdry."],["opin","Los primeros días observa mucho y escucha. Luego todo es más fácil.","Prvé dni veľa pozoruj a počúvaj. Potom je všetko ľahšie."],["cuenta","Yo hice mi mejor amiga el primer día de trabajo.","Ja som si prvý pracovný deň našla najlepšiu kamarátku."],["cari","Estoy muy orgullosa de ti, de verdad.","Som na teba naozaj veľmi hrdá."],["preg","¿Quieres que lo celebremos el fin de semana?","Chceš, aby sme to cez víkend oslávili?"]],
 ["¡Lo de las galletas me lo apunto! Gracias, abuela, eres la mejor.","Tie sušienky si zapíšem! Ďakujem, babka, si najlepšia."]
]);
D("news",["Lo que me han contado","Čo mi povedali"],["Tu cuñada Mercedes","Tvoja švagriná Mercedes"],[
 ["¿Te has enterado? Dicen que los del tercero se divorcian.","Počula si? Vraj sa tí z tretieho rozvádzajú."],
 [["preg","¿Quién lo dice? ¿Te lo han contado ellos?","Kto to hovorí? Povedali ti to oni?"],["duda","No sé... A lo mejor es solo un rumor.","Neviem... Možno je to len klebeta."],["lim","Prefiero no hablar de eso hasta saberlo por ellos.","Radšej o tom nebudem hovoriť, kým to nebudem vedieť od nich."],["apoyo","Vaya, qué pena. Parecían una pareja muy unida.","Ach, to je škoda. Vyzerali ako veľmi súdržný pár."],["hum","En esta escalera se sabe todo antes que en el telediario.","V tomto vchode sa všetko vie skôr ako v správach."],["breve","¿De verdad? No sabía nada.","Naozaj? Nič som nevedela."]],
 ["Me lo ha dicho la portera, que los oyó discutir. Pero no lo sé seguro.","Povedala mi to domovníčka, počula ich hádať sa. Ale isto to neviem."],
 [["lim","Entonces mejor no lo repetimos; si no es verdad, les haría daño.","Tak to radšej neopakujme; ak to nie je pravda, ublížilo by im to."],["opin","Pues discutir no significa divorciarse. Todas las parejas discuten.","No hádka ešte neznamená rozvod. Všetky páry sa hádajú."],["cuenta","Pedro y yo discutimos ayer por el mando de la tele y seguimos juntos.","S Pedrom sme sa včera hádali o ovládač od telky a sme stále spolu."],["preg","¿Y tú cómo los ves cuando te los cruzas?","A ako ich vidíš ty, keď ich stretneš?"],["apoyo","Si es verdad, espero que estén bien, sobre todo los niños.","Ak je to pravda, dúfam, že sú v poriadku, hlavne deti."],["hum","La portera debería trabajar en la radio.","Domovníčka by mala pracovať v rádiu."]],
 ["Tienes razón. Mejor no decir nada. Si de verdad pasa algo, ya nos enteraremos.","Máš pravdu. Radšej nič nehovoriť. Ak sa naozaj niečo deje, dozvieme sa."],
 [["alt","Cambiando de tema, ¿qué tal tu nieto con el piano?","Aby sme zmenili tému, ako sa darí tvojmu vnukovi s klavírom?"],["si","Eso es. Y si necesitan algo, que sepan que pueden contar con nosotras.","Presne tak. A ak budú niečo potrebovať, nech vedia, že sa na nás môžu spoľahnúť."],["cari","Me gusta que lo veas así. Las dos los apreciamos.","Páči sa mi, že to tak vidíš. Obe ich máme radi."],["hum","Y a la portera le pedimos que nos cuente algo bueno, para variar.","A domovníčku poprosíme, nech nám pre zmenu povie niečo dobré."],["opin","Es lo más respetuoso. Cada familia tiene sus cosas.","Je to najúctivejšie. Každá rodina má svoje veci."],["breve","Exacto.","Presne."]],
 ["Ja, ja. ¡Mi nieto con el piano va de maravilla! Ahora te cuento.","Ha-ha. Vnukovi to s klavírom ide skvele! Hneď ti porozprávam."]
]);
D("news",["Ponerse al día por teléfono","Porozprávať si novinky po telefóne"],["Tu prima Carmen, desde Sevilla","Tvoja sesternica Carmen zo Sevilly"],[
 ["¡Hola! ¡Cuánto tiempo! ¿Qué es de tu vida?","Ahoj! Koľko času ubehlo! Čo nového?"],
 [["preg","Bien, ¿y tú? ¿Qué tal por Sevilla?","Dobre, a ty? Ako je v Seville?"],["cuenta","Pues bien, liada con los nietos y con el huerto.","Ale dobre, zamestnaná s vnúčatami a so záhradou."],["cari","¡Qué alegría oírte! Te echaba de menos.","Aká radosť ťa počuť! Chýbala si mi."],["disc","Perdona que no te haya llamado antes, ha sido un mes de locos.","Prepáč, že som ti nezavolala skôr, bol to šialený mesiac."],["hum","Pues aquí, haciéndome mayor, pero con estilo.","Ale tu, starnem, ale so štýlom."],["breve","Muy bien, ¿y tú?","Veľmi dobre, a ty?"]],
 ["Aquí con un calor horroroso, pero bien. Mi hija se casa en octubre, ¿te lo había dicho?","Tu je strašné teplo, ale dobre. Dcéra sa v októbri vydáva, hovorila som ti?"],
 [["preg","¡No sabía nada! ¿Con el chico de Cádiz?","Nič som nevedela! S tým chlapcom z Cádizu?"],["cari","¡No me digas! ¡Qué ilusión! Dale la enhorabuena de mi parte.","Neprezraď! Aká radosť! Zablahoželaj jej odo mňa."],["hum","¿En octubre? Así al menos no os derretiréis en la boda.","V októbri? Aspoň sa na svadbe neroztopíte."],["form","¡Muchas felicidades! Es una noticia estupenda.","Srdečne blahoželám! To je skvelá správa."],["colo","¡Anda ya! ¡Qué fuerte! Cuéntamelo todo.","No toto! To je teda vec! Povedz mi všetko."],["cuenta","Qué bonito. Mi nieta también tiene novio nuevo.","Aké pekné. Aj moja vnučka má nového priateľa."]],
 ["Sí, con el de Cádiz. Y por supuesto estáis invitados. ¿Vendréis?","Áno, s tým z Cádizu. A samozrejme ste pozvaní. Prídete?"],
 [["preg","¿Qué día exactamente? Así lo apunto ya.","Ktorý deň presne? Hneď si to zapíšem."],["si","¡Claro que iremos! No nos lo perdemos por nada.","Jasné, že prídeme! Za nič na svete si to nenecháme ujsť."],["duda","Nos encantaría. Tengo que mirar si coincide con el viaje a Eslovaquia.","Veľmi radi. Musím sa pozrieť, či sa to nekryje s cestou na Slovensko."],["grac","Muchas gracias por invitarnos. Nos hace mucha ilusión.","Veľmi pekne ďakujeme za pozvanie. Veľmi nás to teší."],["hum","Iremos, y pienso bailar más que la novia.","Prídeme a plánujem tancovať viac ako nevesta."],["cari","Ver a tu hija vestida de novia... me emociono solo de pensarlo.","Vidieť tvoju dcéru vo svadobných šatách... dojíma ma už len predstava."]],
 ["¡El dieciocho de octubre! Te mando la invitación por correo. ¡Qué ganas de veros!","Osemnásteho októbra! Pozvánku ti pošlem poštou. Teším sa, keď vás uvidím!"]
]);
D("news",["Una mala noticia","Zlá správa"],["Tu amigo Manuel","Tvoj kamarát Manuel"],[
 ["Te llamo porque tengo una mala noticia. Han cerrado la librería de don Ernesto.","Volám ti, lebo mám zlú správu. Zavreli kníhkupectvo pána Ernesta."],
 [["preg","¿Cómo? ¿Por qué? ¿Qué ha pasado?","Čože? Prečo? Čo sa stalo?"],["apoyo","¡Qué pena! Era la mejor librería del barrio.","To je škoda! Bolo to najlepšie kníhkupectvo vo štvrti."],["recu","No me lo puedo creer. Allí compraba los libros a mis hijos.","Neverím. Tam som kupovala knihy deťom."],["duda","¿Estás seguro? Pasé por allí la semana pasada.","Si si istý? Minulý týždeň som tade prechádzala."],["cari","Pobre don Ernesto. ¿Cómo está él?","Chudák pán Ernesto. Ako sa má?"],["breve","¡Vaya! No sabía nada.","Ach jaj! Nič som nevedela."]],
 ["Le subieron mucho el alquiler y no podía pagarlo. Él está triste, pero tranquilo.","Veľmi mu zvýšili nájom a nemohol ho platiť. Je smutný, ale pokojný."],
 [["preg","¿Qué va a hacer ahora? ¿Se jubila?","Čo bude robiť teraz? Pôjde na dôchodok?"],["opin","Es una lástima. Los alquileres están acabando con las tiendas pequeñas.","Je to škoda. Nájmy ničia malé obchody."],["ofre","Podríamos ir a verle y llevarle algo.","Mohli by sme ho ísť navštíviť a niečo mu priniesť."],["apoyo","Me alegra que esté tranquilo. Ha trabajado muchísimo.","Teší ma, že je pokojný. Strašne veľa pracoval."],["recu","Recuerdo que siempre me guardaba las novedades de novela negra.","Pamätám si, že mi vždy odkladal novinky detektívok."],["hum","Ahora, ¿a quién le voy a pedir recomendaciones? ¿A internet?","A koho teraz budem žiadať o odporúčania? Internet?"]],
 ["Dice que quiere organizar una despedida el sábado y regalar libros. ¿Vamos juntos?","Vraj chce v sobotu urobiť rozlúčku a rozdávať knihy. Pôjdeme spolu?"],
 [["preg","¿A qué hora es? ¿Llevamos algo de comer?","O koľkej? Prinesieme niečo na jedenie?"],["si","Claro que sí. Tenemos que estar allí.","Jasné, že áno. Musíme tam byť."],["cari","Sí, y le llevo una tarjeta firmada por todos los vecinos.","Áno, a donesiem mu pohľadnicu s podpismi všetkých susedov."],["alt","El sábado estoy fuera, pero el viernes paso a despedirme.","V sobotu ma nebude, ale v piatok sa zastavím rozlúčiť."],["hum","Sí, y me llevo una bolsa grande para los libros.","Áno, a vezmem si veľkú tašku na knihy."],["breve","Cuenta conmigo.","Rátaj so mnou."]],
 ["A las doce. Él dice que no hace falta llevar nada, pero un poco de vino no sobrará.","O dvanástej. Hovorí, že netreba nič nosiť, ale trochu vína nezaškodí."]
]);
D("news",["El chisme del pueblo","Dedinské klebety"],["Tu hermana Rosa","Tvoja sestra Rosa"],[
 ["¿A que no sabes quién se ha comprado una moto? ¡El tío Paco, con setenta y cinco años!","Nevieš, kto si kúpil motorku? Strýko Paco, v sedemdesiatich piatich!"],
 [["preg","¿En serio? ¿Y la tía qué dice?","Naozaj? A čo na to teta?"],["hum","¿El tío Paco? ¡Si no sabe ni montar en bici!","Strýko Paco? Veď nevie ani na bicykli!"],["opin","Pues me parece estupendo. Nunca es tarde para cumplir un sueño.","Mne sa to zdá skvelé. Nikdy nie je neskoro splniť si sen."],["duda","Uf, me da un poco de miedo, con lo despistado que es.","Uf, trochu sa bojím, veď je taký roztržitý."],["colo","¡Anda ya! ¡Qué crack el tío Paco!","No toto! Strýko Paco je borec!"],["breve","¡No me lo creo!","Neverím!"]],
 ["La tía está horrorizada, pero dice que él está feliz como un niño. Ya ha ido hasta el pueblo de al lado.","Teta je zdesená, ale hovorí, že je šťastný ako dieťa. Už bol až v susednej dedine."],
 [["recu","De joven ya quería una moto, ¿te acuerdas?","Už ako mladý chcel motorku, pamätáš sa?"],["cari","Me alegro por él. Después de todo lo que ha pasado, se lo merece.","Teším sa za neho. Po tom všetkom, čo prežil, si to zaslúži."],["opin","Mientras lleve casco y vaya despacio, que disfrute.","Kým nosí prilbu a ide pomaly, nech si to užije."],["hum","Hasta el pueblo de al lado... ¡Dentro de nada lo vemos en París!","Až do susednej dediny... O chvíľu ho uvidíme v Paríži!"],["preg","¿Y ha sacado el carné de moto, o va así a lo loco?","A má vodičák na motorku, alebo jazdí len tak naslepo?"],["apoyo","Pobre tía. Tendrá el corazón en un puño.","Chudák teta. Musí mať srdce v hrdle."]],
 ["¡Claro que me acuerdo! La de don Julián, que nos dejaba montar detrás. ¡Qué tiempos!","Jasné, že si pamätám! Tú od pána Juliána, čo nás nechával sedieť vzadu. To boli časy!"],
 [["preg","¿Te acuerdas de cómo se llamaba aquella moto?","Pamätáš si, ako sa tá motorka volala?"],["recu","¡Y nos caímos en el charco de la plaza! Mamá se puso furiosa.","A spadli sme do mláky na námestí! Mama zúrila."],["hum","A lo mejor el tío Paco nos da una vuelta a nosotras también.","Možno nás strýko Paco tiež povozí."],["cari","Qué bonito recordar esas cosas contigo.","Aké pekné spomínať na tieto veci s tebou."],["opin","Se ve que en esta familia las motos nos tiran mucho.","Zdá sa, že v tejto rodine máme slabosť pre motorky."],["breve","¡Qué tiempos aquellos!","To boli časy!"]],
 ["¡La Montesa roja! Oye, este verano vamos al pueblo y le pedimos una vuelta al tío.","Červená Montesa! Počuj, toto leto pôjdeme na dedinu a poprosíme strýka, aby nás povozil."]
]);
D("wellbeing",["¿Cómo has dormido?","Ako si spala?"],["Tu hija Laura, en el desayuno","Tvoja dcéra Laura pri raňajkách"],[
 ["Buenos días, mamá. ¿Qué tal has dormido? Te noto cansada.","Dobré ráno, mami. Ako si spala? Vyzeráš unavená."],
 [["expl","La verdad es que mal. Me he despertado varias veces.","Pravdupovediac zle. Niekoľkokrát som sa zobudila."],["si","Bien, bien, no te preocupes.","Dobre, dobre, nerob si starosti."],["hum","He dormido como un tronco... un tronco con insomnio.","Spala som ako zabitá... len trochu nespavo."],["cuenta","Me cuesta dormir fuera de mi cama.","Ťažko sa mi spí mimo mojej postele."],["preg","¿Se me nota mucho? Qué desastre.","Až tak to na mne vidno? To je katastrofa."],["breve","Regular.","Tak-tak."]],
 ["¿Te molesta algo? ¿El colchón, el ruido de la calle...?","Ruší ťa niečo? Matrac, hluk z ulice...?"],
 [["si","El colchón es un poco blando para mi espalda.","Matrac je na môj chrbát trochu mäkký."],["expl","El ruido de las motos. Aquí la gente se acuesta muy tarde.","Hluk motoriek. Ľudia tu chodia spať veľmi neskoro."],["duda","No sé, creo que son los nervios del viaje.","Neviem, myslím, že sú to nervy z cesty."],["lim","Nada grave, pero esta noche me acostaré antes.","Nič vážne, ale dnes večer pôjdem spať skôr."],["hum","El ruido no es el problema; el problema es tu marido roncando.","Problém nie je hluk; problém je tvoj manžel, čo chrápe."],["cari","Nada, de verdad. Estoy feliz de estar aquí con vosotros.","Nič, naozaj. Som šťastná, že som tu s vami."]],
 ["Ay, perdona. Esta noche te dejo unos tapones y te pongo una almohada más dura.","Joj, prepáč. Dnes večer ti nechám štupľe do uší a dám ti tvrdší vankúš."],
 [["preg","¿Tienes también una infusión de tila?","Máš aj lipový čaj?"],["grac","Gracias, hija. Así seguro que duermo mejor.","Ďakujem, dcérka. Tak určite budem spať lepšie."],["no","No hace falta, de verdad. Ya me acostumbraré.","Netreba, naozaj. Zvyknem si."],["cari","No te preocupes tanto por mí. Estoy bien.","Netráp sa tak kvôli mne. Som v poriadku."],["hum","Con tapones y almohada dura voy a dormir como una reina.","So štupľami a tvrdým vankúšom budem spať ako kráľovná."],["breve","Perfecto, gracias.","Výborne, ďakujem."]],
 ["Tengo tila y manzanilla. Esta noche te la preparo yo. Ahora, desayuna tranquila.","Mám lipu aj harmanček. Dnes večer ti ho urobím ja. Teraz v pokoji raňajkuj."]
]);
D("wellbeing",["Después del médico","Po návšteve lekára"],["Tu hijo Javier, por teléfono","Tvoj syn Javier, telefonicky"],[
 ["Papá, ¿qué te ha dicho el médico? Estaba preocupado.","Oci, čo ti povedal lekár? Robil som si starosti."],
 [["expl","Que tengo la tensión un poco alta, pero nada grave.","Že mám trochu vyšší tlak, ale nič vážne."],["si","Todo bien, hijo. Puedes estar tranquilo.","Všetko v poriadku, synček. Môžeš byť pokojný."],["duda","Me ha mandado hacer unas pruebas más. Ya veremos.","Poslal ma na ďalšie vyšetrenia. Uvidíme."],["hum","Que estoy hecho un chaval. Bueno, casi.","Že som ako mladík. No, takmer."],["grac","Gracias por llamar. Me alegra que te preocupes.","Vďaka, že si zavolal. Teší ma, že sa staráš."],["breve","Nada importante.","Nič dôležité."]],
 ["¿Y te ha mandado alguna medicación? ¿Tienes que cambiar algo?","A predpísal ti nejaké lieky? Musíš niečo zmeniť?"],
 [["cuenta","Quiere que camine media hora al día.","Chce, aby som chodil pol hodiny denne."],["expl","Una pastilla por la mañana, y menos sal en las comidas.","Jednu tabletku ráno a menej soli v jedle."],["hum","Menos sal y menos jamón. Es el peor día de mi vida.","Menej soli a menej šunky. Najhorší deň môjho života."],["opin","Me parece bien. Ya me tocaba cuidarme un poco más.","Súhlasím. Už bol čas, aby som sa o seba viac staral."],["duda","Pastillas no, de momento. Primero quiere ver cómo evoluciono.","Zatiaľ žiadne tabletky. Najprv chce vidieť, ako sa to bude vyvíjať."],["preg","¿Tú sabes si estas pastillas dan sueño?","Nevieš, či tieto tabletky uspávajú?"]],
 ["Lo de caminar me parece muy bien. Si quieres, el domingo salimos juntos.","To s chodením je veľmi dobré. Ak chceš, v nedeľu pôjdeme spolu."],
 [["hum","Vale, pero a mi ritmo, no al tuyo de maratoniano.","Dobre, ale mojím tempom, nie tvojím maratónskym."],["si","¡Me encantaría! Así me motivo.","Veľmi rád! Aspoň budem mať motiváciu."],["cari","Caminar contigo es el mejor tratamiento.","Chodiť s tebou je najlepšia liečba."],["alt","Mejor el sábado, que el domingo viene tu hermana.","Radšej v sobotu, v nedeľu príde tvoja sestra."],["grac","Gracias, hijo. Me hace mucha ilusión.","Ďakujem, synček. Veľmi sa teším."],["breve","Hecho.","Platí."]],
 ["¡A tu ritmo, prometido! Y después nos tomamos un café... sin azúcar.","Tvojím tempom, sľubujem! A potom si dáme kávu... bez cukru."]
]);
D("wellbeing",["Un día triste","Smutný deň"],["Tu nieta Lucía","Tvoja vnučka Lucía"],[
 ["Abuela, ¿estás bien? Te noto un poco apagada hoy.","Babi, si v poriadku? Dnes sa mi zdáš trochu skleslá."],
 [["expl","Hoy hace un año que murió tu abuelo. Lo echo mucho de menos.","Dnes je to rok, čo zomrel tvoj dedko. Veľmi mi chýba."],["si","Estoy bien, cariño. Solo un poco cansada.","Som v poriadku, zlatko. Len trochu unavená."],["duda","No sé, me he levantado con el ánimo bajo.","Neviem, zobudila som sa so skleslou náladou."],["grac","Gracias por darte cuenta. Eres muy atenta.","Ďakujem, že si si to všimla. Si veľmi pozorná."],["cuenta","Un poco triste. Hay días así.","Trochu smutná. Sú také dni."],["breve","Regular, hija.","Tak-tak, dievča."]],
 ["Ay, abuela, no me acordaba de la fecha. ¿Quieres que hablemos de él, o prefieres distraerte?","Jaj, babi, nespomenula som si na dátum. Chceš sa o ňom porozprávať, alebo sa radšej rozptýliť?"],
 [["preg","¿Tú te acuerdas de él? Eras muy pequeña.","Pamätáš si naňho? Bola si veľmi malá."],["recu","Me gustaría hablar de él. Me hace bien recordarlo.","Chcela by som sa o ňom porozprávať. Pomáha mi spomínať naňho."],["alt","Mejor distraerme un poco. ¿Damos un paseo?","Radšej sa trochu rozptýliť. Pôjdeme sa prejsť?"],["cari","Las dos cosas. Contigo cualquier cosa me sienta bien.","Oboje. S tebou mi dobre padne čokoľvek."],["duda","No lo sé. Quizá solo necesito compañía.","Neviem. Možno potrebujem len spoločnosť."],["grac","Gracias por preguntarme. No todo el mundo lo hace.","Ďakujem, že sa pýtaš. Nie každý to robí."]],
 ["Me acuerdo de cuando me enseñó a pescar en el río. Se reía tanto cuando se me escapaban los peces.","Pamätám si, ako ma učil chytať ryby v rieke. Tak sa smial, keď mi ryby unikali."],
 [["preg","¿Quieres ver las fotos de aquel verano? Las tengo en el armario.","Chceš vidieť fotky z toho leta? Mám ich v skrini."],["recu","¡Sí! Volvía a casa contándolo como si hubieras pescado una ballena.","Áno! Vracal sa domov a rozprával o tom, akoby si chytila veľrybu."],["cari","Te quería muchísimo. Eras su ojito derecho.","Veľmi ťa mal rád. Bola si jeho miláčik."],["hum","Él tampoco pescaba nada, pero no se lo digas a nadie.","Ani on nič nechytil, ale nikomu to nehovor."],["grac","Gracias por contarme eso. Me has alegrado el día.","Ďakujem, že si mi to povedala. Zlepšila si mi deň."],["apoyo","Él estaría muy orgulloso de la mujer en la que te has convertido.","Bol by veľmi hrdý na ženu, akou si sa stala."]],
 ["¡Sí, saca las fotos! Y preparo un té para las dos.","Áno, vytiahni fotky! A ja urobím čaj pre nás obe."]
]);
D("wellbeing",["Me duele la espalda","Bolí ma chrbát"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["¡Ay! Me he agachado a coger una cosa y me ha dado un tirón en la espalda.","Au! Zohol som sa po niečo a seklo mi v chrbte."],
 [["preg","¿Dónde te duele exactamente? ¿Puedes moverte?","Kde presne ťa to bolí? Môžeš sa hýbať?"],["ofre","Siéntate, que te traigo la crema y una manta caliente.","Sadni si, prinesiem ti masť a teplú deku."],["apoyo","¡Ay, pobre! No hagas movimientos bruscos.","Joj, chudák! Nerob prudké pohyby."],["hum","Te lo tengo dicho: a nuestra edad, las cosas se cogen con la vista.","Hovorím ti to stále: v našom veku sa veci zdvíhajú očami."],["duda","¿Quieres que llamemos al médico?","Chceš, aby sme zavolali lekára?"],["breve","¡Cuidado! Despacio.","Opatrne! Pomaly."]],
 ["Aquí abajo, en los riñones. Puedo moverme, pero me duele mucho al sentarme.","Tu dole, v krížoch. Hýbať sa môžem, ale pri sadaní ma to veľmi bolí."],
 [["preg","¿Te tomas un ibuprofeno?","Dáš si ibuprofén?"],["expl","Túmbate en la cama, boca arriba, con una almohada debajo de las rodillas.","Ľahni si na posteľ na chrbát s vankúšom pod kolenami."],["ofre","Te doy un masaje suave con la crema de árnica.","Jemne ťa namasírujem arnikovou masťou."],["opin","Si mañana sigues igual, vamos al fisioterapeuta.","Ak budeš zajtra rovnaký, pôjdeme k fyzioterapeutovi."],["cari","No te preocupes, hoy me encargo yo de todo.","Nerob si starosti, dnes sa o všetko postarám ja."],["hum","Pues hoy te toca ser el paciente y a mí la enfermera.","Tak dnes si ty pacient a ja zdravotná sestra."]],
 ["Me tomo un ibuprofeno y me tumbo. Pero esta tarde íbamos a ir al mercado...","Dám si ibuprofén a ľahnem si. Ale poobede sme chceli ísť na trh..."],
 [["alt","Lo dejamos para mañana. El mercado no se va a ninguna parte.","Necháme to na zajtra. Trh nikam neutečie."],["si","No pasa nada, voy yo sola. Tú descansa.","Nič sa nedeje, pôjdem sama. Ty odpočívaj."],["ofre","Le pido a Laura que me acompañe, no te preocupes.","Poprosím Lauru, aby išla so mnou, nerob si starosti."],["lim","Hoy lo único que vas a hacer es descansar.","Dnes budeš robiť jedine to, že budeš odpočívať."],["hum","El mercado sobrevivirá sin ti. Tu espalda, no sé.","Trh to bez teba prežije. Tvoj chrbát, neviem."],["cari","Lo importante es que te pongas bien.","Dôležité je, aby si sa uzdravil."]],
 ["Tienes razón. Gracias, cariño. Tráeme el libro, que al menos leo un rato.","Máš pravdu. Ďakujem, zlatko. Prines mi knihu, aspoň si chvíľu prečítam."]
]);
D("wellbeing",["Me siento solo","Cítim sa osamelo"],["Tu vecino Ramón, en el ascensor","Tvoj sused Ramón vo výťahu"],[
 ["Hola. Perdona la cara, es que desde que mis hijos se mudaron, la casa se me cae encima.","Ahoj. Prepáč ten výraz, ale odkedy sa deti odsťahovali, dom mi padá na hlavu."],
 [["preg","¿Hace mucho que se fueron?","Je to dávno, čo odišli?"],["apoyo","Te entiendo perfectamente. A mí me pasó lo mismo.","Úplne ťa chápem. Mne sa stalo to isté."],["cari","Lo siento mucho, Ramón. Debe de ser muy duro.","Veľmi ma to mrzí, Ramón. Musí to byť veľmi ťažké."],["ofre","¿Por qué no subes a tomar un café esta tarde?","Prečo by si poobede neprišiel hore na kávu?"],["cuenta","Cuando yo llegué a España, también me sentía muy sola.","Keď som prišla do Španielska, aj ja som sa cítila veľmi osamelo."],["breve","Vaya, lo siento.","Ach, to ma mrzí."]],
 ["Un mes. Me llaman a menudo, pero los días se hacen muy largos.","Mesiac. Často mi volajú, ale dni sú veľmi dlhé."],
 [["ofre","Pedro sale a caminar cada mañana. Seguro que le gusta tener compañía.","Pedro chodí každé ráno na prechádzku. Určite by bol rád za spoločnosť."],["opin","Quizá te vendría bien apuntarte a alguna actividad en el centro de mayores.","Možno by ti prospelo prihlásiť sa na nejakú aktivitu v centre pre seniorov."],["cuenta","Yo voy los martes a un club de lectura. Si quieres, te vienes.","Ja chodím v utorky do čitateľského klubu. Ak chceš, poď so mnou."],["apoyo","Es normal. Hay que darse tiempo para acostumbrarse.","To je normálne. Treba si dať čas, aby si si zvykol."],["preg","¿Qué te gustaba hacer antes, cuando tenías tiempo?","Čo si rád robil predtým, keď si mal čas?"],["cari","Los primeros meses son los peores. Luego mejora, ya verás.","Prvé mesiace sú najhoršie. Potom sa to zlepší, uvidíš."]],
 ["Lo de caminar con Pedro me gustaría. Antes andaba mucho por el monte.","Chodiť s Pedrom by som chcel. Kedysi som veľa chodil po horách."],
 [["si","Pues mañana a las ocho le esperas en el portal. Se lo digo yo.","Tak zajtra o ôsmej naňho počkaj pred domom. Poviem mu to."],["cari","Le encantará. Y a lo mejor algún día vamos todos al monte.","Bude nadšený. A možno raz pôjdeme všetci do hôr."],["hum","Perfecto, pero te aviso: habla más de lo que camina.","Výborne, ale upozorňujem ťa: viac rozpráva, ako chodí."],["ofre","Y el café de esta tarde sigue en pie, ¿eh?","A tá poobedňajšia káva stále platí, jasné?"],["preg","¿Qué montes conoces por aquí? Pedro siempre busca rutas nuevas.","Aké hory tu poznáš? Pedro vždy hľadá nové trasy."],["breve","Hecho, se lo digo.","Platí, poviem mu."]],
 ["Gracias, de verdad. Solo por esta conversación ya me siento mejor.","Naozaj ďakujem. Len vďaka tomuto rozhovoru sa už cítim lepšie."]
]);
D("support",["Un examen suspendido","Neúspešná skúška"],["Tu nieto Pablo","Tvoj vnuk Pablo"],[
 ["He suspendido matemáticas. Mis padres se van a enfadar muchísimo.","Neurobil som matematiku. Rodičia sa budú strašne hnevať."],
 [["apoyo","Vaya, lo siento. ¿Cómo te sientes tú?","Ach, to ma mrzí. Ako sa cítiš ty?"],["preg","¿Qué ha pasado? ¿Era muy difícil?","Čo sa stalo? Bola veľmi ťažká?"],["cari","Ven aquí. Un examen no dice quién eres.","Poď sem. Jedna skúška nehovorí, kto si."],["cuenta","Yo suspendí física dos veces, y aquí estoy.","Ja som dvakrát neurobil fyziku, a pozri, som tu."],["anim","Tranquilo, hay tiempo para recuperarlo.","Pokojne, je čas to napraviť."],["breve","Vaya... Cuéntame.","Ach... Porozprávaj."]],
 ["Me siento fatal. Estudié, pero en el examen me quedé en blanco.","Cítim sa hrozne. Učil som sa, ale na skúške som úplne zabudol."],
 [["cari","Lo importante es que estudiaste. Eso tus padres lo saben.","Dôležité je, že si sa učil. To tvoji rodičia vedia."],["apoyo","Eso le pasa a mucha gente. Son los nervios, no que no sepas.","To sa stáva veľa ľuďom. Sú to nervy, nie to, že nevieš."],["preg","¿Te pasa a menudo eso de quedarte en blanco?","Stáva sa ti často, že úplne zabudneš?"],["ofre","Si quieres, repasamos juntos antes de la recuperación.","Ak chceš, pred opravkou to spolu zopakujeme."],["opin","Quizá te ayude hacer exámenes de práctica en casa, con reloj.","Možno ti pomôže robiť doma cvičné testy s hodinkami."],["hum","A mí me pasaba siempre con las fechas de historia.","Mne sa to vždy stávalo s dátumami z dejepisu."]],
 ["¿Me ayudarías a contárselo a mis padres? No sé cómo decírselo.","Pomohol by si mi povedať to rodičom? Neviem, ako im to povedať."],
 [["opin","Creo que es mejor que se lo digas tú, pero yo estaré a tu lado.","Myslím, že je lepšie, keď im to povieš ty, ale ja budem pri tebe."],["si","Claro. Se lo contamos juntos esta noche.","Jasné. Povieme im to spolu dnes večer."],["expl","Empieza diciendo que estudiaste y explica lo de los nervios.","Začni tým, že si sa učil, a vysvetli to s nervami."],["cari","Tus padres te quieren. Se enfadarán un poco, pero te ayudarán.","Rodičia ťa ľúbia. Trochu sa nahnevajú, ale pomôžu ti."],["ofre","Y les cuento que vamos a estudiar juntos los martes.","A poviem im, že sa budeme spolu učiť v utorky."],["breve","Por supuesto.","Samozrejme."]],
 ["Gracias, abuelo. Contigo al lado parece menos terrible.","Ďakujem, dedo. S tebou po boku to nevyzerá až také strašné."]
]);
D("support",["Un problema en el trabajo","Problém v práci"],["Tu hija Laura","Tvoja dcéra Laura"],[
 ["Mamá, ¿tienes un momento? Necesito desahogarme. Mi jefe me ha dicho cosas muy feas delante de todos.","Mami, máš chvíľu? Potrebujem sa vyrozprávať. Šéf mi pred všetkými povedal veľmi škaredé veci."],
 [["preg","¿Qué te ha dicho?","Čo ti povedal?"],["cari","Claro, hija. Cuéntamelo todo, te escucho.","Jasné, dcérka. Povedz mi všetko, počúvam."],["apoyo","¡Qué injusto! Delante de todos, además.","Aké nespravodlivé! A navyše pred všetkými."],["ofre","Siéntate. Te preparo un té y me lo cuentas con calma.","Sadni si. Urobím ti čaj a v pokoji mi to povieš."],["duda","Uy... ¿Ha pasado algo grave?","Joj... Stalo sa niečo vážne?"],["breve","Claro, dime.","Jasné, hovor."]],
 ["Que mi informe era un desastre y que no sé hacer mi trabajo. Y no es verdad; hubo un error de otro departamento.","Že moja správa bola katastrofa a že neviem robiť svoju prácu. A nie je to pravda; chybu urobilo iné oddelenie."],
 [["preg","¿Quieres un consejo, o prefieres que solo te escuche?","Chceš radu, alebo chceš, aby som len počúvala?"],["apoyo","Normal que estés dolida. Nadie debería hablarte así.","Je normálne, že ťa to bolí. Nikto by ti nemal takto hovoriť."],["preg","¿Tú qué le contestaste en ese momento?","Čo si mu v tej chvíli odpovedala?"],["opin","Creo que deberías hablar con él a solas y explicarle lo que pasó.","Myslím, že by si sa s ním mala porozprávať osamote a vysvetliť mu, čo sa stalo."],["cari","Yo sé lo trabajadora que eres. No dejes que eso te haga dudar.","Viem, aká si pracovitá. Nedovoľ, aby ťa to prinútilo pochybovať."],["hum","Si quieres, voy y le digo cuatro cosas a ese señor.","Ak chceš, pôjdem a poviem tomu pánovi zopár slov."]],
 ["Ahora mismo solo necesitaba contarlo. Pero sí, creo que mañana hablaré con él.","Teraz som to len potrebovala povedať. Ale áno, myslím, že zajtra sa s ním porozprávam."],
 [["ofre","Si quieres, esta noche ensayamos lo que le vas a decir.","Ak chceš, večer si nacvičíme, čo mu povieš."],["anim","Me parece muy valiente. Lleva los datos que demuestran el error.","Je to od teba odvážne. Zober si údaje, ktoré tú chybu dokazujú."],["cari","Haz lo que te haga sentir mejor. Yo estoy aquí para lo que necesites.","Urob, čo ti pomôže cítiť sa lepšie. Som tu pre všetko, čo potrebuješ."],["opin","Habla con calma, sin reproches. Así te escuchará mejor.","Hovor pokojne, bez výčitiek. Tak ťa bude lepšie počúvať."],["grac","Gracias por confiar en mí para contármelo.","Ďakujem, že si sa mi zdôverila."],["breve","Muy bien. Ánimo.","Dobre. Veľa síl."]],
 ["Gracias, mamá. Ya me siento más tranquila. ¿Ensayamos después de cenar?","Ďakujem, mami. Už som pokojnejšia. Nacvičíme to po večeri?"]
]);
D("support",["Una ruptura","Rozchod"],["Tu nieta Lucía","Tvoja vnučka Lucía"],[
 ["Abuela... He dejado a Marcos. Bueno, en realidad me ha dejado él.","Babi... Rozišla som sa s Marcosom. No, v skutočnosti sa so mnou rozišiel on."],
 [["preg","¿Cuándo ha sido? ¿Cómo estás?","Kedy sa to stalo? Ako sa cítiš?"],["cari","Ay, mi niña. Ven aquí, dame un abrazo.","Joj, dievčatko moje. Poď sem, objím ma."],["apoyo","Lo siento mucho, cariño. Tiene que doler.","Veľmi ma to mrzí, zlatko. Musí to bolieť."],["duda","Vaya... No me lo esperaba. Parecíais tan bien.","Ach... To som nečakala. Vyzerali ste tak dobre."],["ofre","¿Quieres quedarte a dormir aquí esta noche?","Chceš tu dnes prespať?"],["breve","Ay, cariño...","Joj, zlatko..."]],
 ["Ayer. Dice que necesita estar solo. Yo no entiendo nada, pensaba que estábamos bien.","Včera. Vraj potrebuje byť sám. Ja ničomu nerozumiem, myslela som, že nám je dobre."],
 [["cuenta","A mí también me dejaron una vez, antes de conocer a tu abuelo.","Aj mňa raz nechali, predtým ako som spoznala tvojho dedka."],["apoyo","Es normal no entender nada ahora. Date tiempo.","Je normálne, že teraz ničomu nerozumieš. Daj si čas."],["cari","Llora todo lo que necesites. Aquí no tienes que hacerte la fuerte.","Plač, koľko potrebuješ. Tu nemusíš byť silná."],["preg","¿Has podido hablar con tus amigas?","Mohla si sa porozprávať s kamarátkami?"],["opin","A veces la otra persona tiene sus razones, aunque ahora duela.","Niekedy má ten druhý svoje dôvody, aj keď to teraz bolí."],["lim","No hace falta que lo entiendas hoy. Hoy solo descansa.","Dnes to nemusíš pochopiť. Dnes si len oddýchni."]],
 ["¿De verdad te dejaron? Cuéntamelo, que necesito pensar en otra cosa.","Naozaj ťa nechali? Povedz mi to, potrebujem myslieť na niečo iné."],
 [["cari","Te lo cuento con un chocolate caliente, ¿vale?","Poviem ti to pri horúcej čokoláde, dobre?"],["recu","Sí. Se llamaba Jozef y se fue a estudiar a Praga. Lloré un mes entero.","Áno. Volal sa Jozef a odišiel študovať do Prahy. Plakala som celý mesiac."],["hum","Sí, y gracias a eso conocí a tu abuelo. Así que mira.","Áno, a vďaka tomu som spoznala tvojho dedka. Tak vidíš."],["cuenta","Sí. Y aprendí que el corazón se cura, aunque no lo parezca.","Áno. A naučila som sa, že srdce sa zahojí, aj keď to tak nevyzerá."],["si","Claro. Siéntate, que es una historia larga.","Jasné. Sadni si, je to dlhý príbeh."],["breve","Te lo cuento todo.","Poviem ti všetko."]],
 ["Sí, por favor. Chocolate y tu historia. Gracias, abuela.","Áno, prosím. Čokoláda a tvoj príbeh. Ďakujem, babi."]
]);
D("support",["Una decisión difícil","Ťažké rozhodnutie"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["Papá, me han ofrecido un trabajo en Londres. Es una gran oportunidad, pero no sé qué hacer.","Oci, ponúkli mi prácu v Londýne. Je to veľká príležitosť, ale neviem, čo robiť."],
 [["preg","¿Qué piensa Sofía?","Čo si myslí Sofía?"],["preg","¿Qué es lo que más te preocupa?","Čo ťa najviac trápi?"],["anim","¡Qué orgullo! Eso significa que valoran tu trabajo.","Aká hrdosť! Znamená to, že si cenia tvoju prácu."],["cari","Sea lo que sea, te apoyaremos.","Nech sa rozhodneš akokoľvek, podporíme ťa."],["opin","Es una decisión importante. Tómate tu tiempo.","Je to dôležité rozhodnutie. Daj si čas."],["cuenta","Yo también tuve que decidir si venir a España. Te entiendo.","Aj ja som sa musel rozhodnúť, či prísť do Španielska. Chápem ťa."]],
 ["Sofía dice que la decisión es mía. Me preocupan los niños: cambiar de colegio, de idioma...","Sofía hovorí, že je to moje rozhodnutie. Trápia ma deti: zmeniť školu, jazyk..."],
 [["preg","¿Es para siempre o por unos años?","Je to navždy, alebo na pár rokov?"],["cuenta","Los niños se adaptan mejor de lo que creemos. Tú lo hiciste.","Deti sa prispôsobia lepšie, ako si myslíme. Ty si to zvládol."],["opin","Habla con ellos. Quizá les haga más ilusión de lo que piensas.","Porozprávaj sa s nimi. Možno sa budú tešiť viac, ako si myslíš."],["apoyo","Es normal tener miedo. Es un cambio muy grande.","Je normálne báť sa. Je to veľká zmena."],["duda","Te confieso que a mí me daría pena teneros tan lejos.","Priznám sa, že by mi bolo ľúto mať vás tak ďaleko."],["expl","Hablar inglés sería un regalo para ellos en el futuro.","Hovoriť po anglicky by pre nich v budúcnosti bol dar."]],
 ["Serían tres años. ¿Y a vosotros no os daría pena?","Boli by to tri roky. A vám by nebolo ľúto?"],
 [["cari","Claro que sí, pero tu felicidad es más importante.","Jasné, že áno, ale tvoje šťastie je dôležitejšie."],["hum","Pena sí, pero tendríamos una excusa para conocer Londres.","Ľúto áno, ale mali by sme výhovorku, prečo spoznať Londýn."],["opin","Tres años pasan rápido, y hay aviones y videollamadas.","Tri roky prejdú rýchlo a sú lietadlá aj videohovory."],["lim","No decidas pensando en nosotros. Decide pensando en tu familia.","Nerozhoduj sa podľa nás. Rozhoduj sa podľa svojej rodiny."],["duda","Un poco, no te voy a mentir. Pero lo superaríamos.","Trochu, nebudem ti klamať. Ale prekonali by sme to."],["grac","Gracias por pensar en nosotros. Eso dice mucho de ti.","Ďakujem, že myslíš na nás. To o tebe veľa hovorí."]],
 ["Gracias, papá. Lo hablaré con los niños este fin de semana. Me ayuda mucho saber que me apoyáis.","Ďakujem, oci. Cez víkend sa o tom porozprávam s deťmi. Veľmi mi pomáha vedieť, že ma podporujete."]
]);
D("support",["Nervios antes de una operación","Nervy pred operáciou"],["Tu hermana Rosa","Tvoja sestra Rosa"],[
 ["Mañana me operan de la rodilla y estoy muerta de miedo. Ya sé que es una tontería.","Zajtra ma operujú koleno a strašne sa bojím. Viem, že je to hlúposť."],
 [["preg","¿Qué es lo que más miedo te da?","Čoho sa bojíš najviac?"],["apoyo","No es ninguna tontería. Es normal tener miedo.","Vôbec to nie je hlúposť. Je normálne báť sa."],["cari","Estaré contigo todo el tiempo, no estás sola.","Budem s tebou celý čas, nie si sama."],["cuenta","Yo me operé de la cadera hace dos años y salió todo bien.","Mňa pred dvoma rokmi operovali bedro a všetko dopadlo dobre."],["anim","Te va a ir muy bien. El doctor es de los mejores.","Dopadne to veľmi dobre. Ten lekár patrí k najlepším."],["breve","Te entiendo perfectamente.","Úplne ťa chápem."]],
 ["La anestesia. Me da miedo no despertarme, aunque sé que es muy raro.","Narkóza. Bojím sa, že sa nezobudím, aj keď viem, že sa to stáva veľmi zriedka."],
 [["preg","¿Quieres que esta noche me quede a dormir contigo?","Chceš, aby som dnes u teba prespala?"],["expl","Pregúntale mañana al anestesista; te explicará todo y te quedarás más tranquila.","Zajtra sa spýtaj anestéziológa; všetko ti vysvetlí a budeš pokojnejšia."],["cuenta","Yo tenía el mismo miedo. Me dormí y me desperté sin enterarme de nada.","Ja som mala rovnaký strach. Zaspala som a zobudila sa bez toho, aby som o niečom vedela."],["apoyo","Es un miedo muy común. No te avergüences.","Je to veľmi bežný strach. Nehanbi sa zaň."],["hum","Te despertarás, y lo primero que verás será mi cara. Eso sí da miedo.","Zobudíš sa a prvé, čo uvidíš, bude moja tvár. Tak to je strašidelné."],["cari","Te estaré esperando cuando abras los ojos.","Budem na teba čakať, keď otvoríš oči."]],
 ["¿Te quedarías esta noche? Así no doy vueltas en la cama sola.","Zostala by si dnes večer? Aspoň sa nebudem v posteli prehadzovať sama."],
 [["cari","Por supuesto. Como cuando éramos pequeñas.","Samozrejme. Ako keď sme boli malé."],["si","Claro. Llevo mi pijama y vemos una película tonta.","Jasné. Vezmem si pyžamo a pozrieme si nejaký hlúpy film."],["ofre","Y mañana te llevo yo al hospital en coche.","A zajtra ťa do nemocnice odveziem ja."],["hum","Sí, pero si roncas, me voy al sofá.","Áno, ale ak budeš chrápať, idem na gauč."],["preg","¿Necesitas que te lleve algo? ¿Cena, algo para el hospital?","Potrebuješ, aby som niečo priniesla? Večeru, niečo do nemocnice?"],["breve","Ahora mismo voy.","Hneď idem."]],
 ["Gracias, hermana. No sé qué haría sin ti.","Ďakujem, sestrička. Neviem, čo by som bez teba robila."]
]);
D("boundaries",["Demasiadas tardes de canguro","Priveľa popoludní stráženia detí"],["Tu hija Laura","Tvoja dcéra Laura"],[
 ["Mamá, ¿podrías quedarte otra vez con los niños el jueves y el viernes por la tarde?","Mami, mohla by si zase vo štvrtok a v piatok poobede postrážiť deti?"],
 [["lim","Esta semana ya me he quedado tres tardes. Necesito descansar un poco.","Tento týždeň som už bola s nimi tri popoludnia. Potrebujem si trochu oddýchnuť."],["alt","El jueves sí, pero el viernes tengo mis planes.","Vo štvrtok áno, ale v piatok mám svoje plány."],["duda","Uf... Déjame pensarlo, que estoy un poco cansada.","Uf... Nechaj ma porozmýšľať, som trochu unavená."],["si","Bueno, esta vez sí. Pero tenemos que hablar de esto.","No dobre, tentoraz áno. Ale musíme sa o tom porozprávať."],["cari","Sabes que adoro a los niños, pero esta semana no puedo más.","Vieš, že deti zbožňujem, ale tento týždeň už nevládzem."],["preg","¿Pasa algo en el trabajo? Últimamente me lo pides mucho.","Deje sa niečo v práci? V poslednom čase ma o to žiadaš často."]],
 ["Perdona, no me había dado cuenta de que eran tantas tardes. Es que tenemos mucho lío en la oficina.","Prepáč, neuvedomila som si, že je toho toľko. Máme v kancelárii veľa práce."],
 [["ofre","Podemos hacer un calendario juntas, así lo sabemos con tiempo.","Môžeme spolu urobiť rozvrh, aby sme to vedeli vopred."],["apoyo","Lo entiendo, hija. No te lo digo como reproche.","Chápem, dcérka. Nehovorím ti to ako výčitku."],["alt","¿Y si buscamos a alguien que os ayude uno o dos días por semana?","A čo keby sme našli niekoho, kto vám pomôže deň-dva v týždni?"],["lim","Me encanta ayudar, pero dos tardes por semana es lo que puedo.","Rada pomáham, ale dve popoludnia v týždni je to, čo zvládnem."],["expl","A mi edad, cuidar a dos niños toda la tarde me deja agotada.","V mojom veku ma celé popoludnie s dvoma deťmi úplne vyčerpá."],["cari","Me alegra que lo hablemos. Así no se acumula.","Teší ma, že sa o tom rozprávame. Aspoň sa to nenahromadí."]],
 ["Lo del calendario me parece muy buena idea. ¿Qué días te vendrían mejor?","Rozvrh je veľmi dobrý nápad. Ktoré dni by ti vyhovovali najviac?"],
 [["expl","Los martes y los jueves. Los viernes prefiero tenerlos libres.","Utorky a štvrtky. Piatky chcem mať radšej voľné."],["si","Lunes y miércoles. Y si alguna vez hay una urgencia, me llamas.","Pondelky a stredy. A keby bolo niekedy niečo súrne, zavolaj mi."],["hum","Los días que tengan menos deberes de matemáticas.","Dni, keď majú najmenej úloh z matematiky."],["cari","Cualquiera, menos los viernes, que son mis tardes de pintura.","Hocijaké okrem piatkov, to sú moje popoludnia s maľovaním."],["preg","¿A ti cuáles te vienen mejor? Lo hacemos juntas.","Ktoré vyhovujú tebe? Urobíme to spolu."],["grac","Gracias por escucharme, hija. Así será más fácil para todos.","Ďakujem, že si ma vypočula, dcérka. Tak to bude pre všetkých ľahšie."]],
 ["Martes y jueves, entonces. Y el viernes lo organizo yo con Andrés. Gracias por decírmelo, mamá.","Tak utorky a štvrtky. A piatok si zariadim s Andrésom. Ďakujem, že si mi to povedala, mami."]
]);
D("boundaries",["Consejos que no he pedido","Rady, o ktoré som nežiadala"],["Tu consuegra Carmen","Tvoja svatka Carmen"],[
 ["Yo que tú no le dejaría al niño tanto rato con la tablet. No es bueno.","Ja by som na tvojom mieste nenechávala chlapca tak dlho pri tablete. Nie je to dobré."],
 [["form","Te agradezco el consejo, pero lo tengo controlado.","Ďakujem za radu, ale mám to pod kontrolou."],["lim","Gracias, Carmen, pero eso lo deciden sus padres.","Ďakujem, Carmen, ale o tom rozhodujú jeho rodičia."],["apoyo","Puede que tengas razón, pero solo ha sido un rato.","Možno máš pravdu, ale bola to len chvíľa."],["expl","Me han pedido que le deje media hora mientras cocino.","Požiadali ma, aby som ho nechala pol hodiny, kým varím."],["hum","Tranquila, que la tablet tiene más años que él.","Pokojne, ten tablet je starší ako on."],["preg","¿Tú cuánto tiempo les dejas a tus nietos?","Koľko času nechávaš ty svojim vnúčatám?"]],
 ["Bueno, yo solo lo digo por su bien. Mis nietos no tocan una pantalla hasta los diez años.","No, hovorím to len pre jeho dobro. Moje vnúčatá sa obrazovky nedotknú až do desiatich rokov."],
 [["lim","Me parece muy bien para tus nietos. Aquí seguimos lo que dicen sus padres.","Pre tvoje vnúčatá je to v poriadku. Tu sa riadime tým, čo povedia rodičia."],["cari","Sé que lo dices con cariño. Cada familia lo hace a su manera.","Viem, že to myslíš dobre. Každá rodina to robí po svojom."],["opin","Hay muchas opiniones sobre eso. No hay una única forma correcta.","Na to je veľa názorov. Neexistuje jediný správny spôsob."],["alt","Si quieres, lo hablamos con Laura y Andrés cuando vuelvan.","Ak chceš, porozprávame sa o tom s Laurou a Andrésom, keď sa vrátia."],["hum","Admiro tu disciplina. Yo no consigo ni dejar el chocolate.","Obdivujem tvoju disciplínu. Ja nedokážem ani prestať jesť čokoládu."],["breve","Entiendo.","Rozumiem."]],
 ["Tienes razón, no es asunto mío. Perdona si te he molestado.","Máš pravdu, nie je to moja vec. Prepáč, ak som ťa urazila."],
 [["alt","Ya está olvidado. ¿Le enseñamos juntas a jugar a las cartas?","Už je to zabudnuté. Naučíme ho spolu hrať karty?"],["cari","No me has molestado. Me alegra que te preocupes por él.","Neurazila si ma. Teší ma, že ti na ňom záleží."],["grac","Gracias por entenderlo. Las dos queremos lo mejor para él.","Ďakujem za pochopenie. Obe chceme pre neho to najlepšie."],["hum","Nada, mujer. Entre abuelas nos entendemos.","Ale kdeže. Babky si predsa rozumejú."],["si","No pasa nada. ¿Tomamos un café?","Nič sa nedeje. Dáme si kávu?"],["breve","Tranquila, no pasa nada.","Pokojne, nič sa nedeje."]],
 ["¡Me encanta la idea de las cartas! Así se despega de la tablet sin que nadie le riña.","Karty sú skvelý nápad! Odlepí sa od tabletu bez toho, aby ho niekto karhal."]
]);
D("boundaries",["Prestar dinero","Požičať peniaze"],["Tu sobrino Diego","Tvoj synovec Diego"],[
 ["Tía, ¿me podrías prestar quinientos euros? Te los devuelvo en dos meses.","Teta, mohla by si mi požičať päťsto eur? Vrátim ti ich o dva mesiace."],
 [["preg","¿Para qué los necesitas, si se puede saber?","Na čo ich potrebuješ, ak sa môžem spýtať?"],["lim","Lo siento, Diego, pero no presto dinero. Es una norma que tengo.","Prepáč, Diego, ale peniaze nepožičiavam. Je to moje pravidlo."],["duda","Es mucho dinero... Tengo que hablarlo con tu tío.","To je veľa peňazí... Musím sa o tom porozprávať so strýkom."],["alt","Quinientos no puedo, pero doscientos sí.","Päťsto nemôžem, ale dvesto áno."],["cari","¿Estás bien? ¿Ha pasado algo?","Si v poriadku? Stalo sa niečo?"],["form","Necesito pensarlo. Te contesto mañana.","Potrebujem o tom porozmýšľať. Odpoviem ti zajtra."]],
 ["Se me ha roto el ordenador y lo necesito para el trabajo. No quiero pedírselo a mis padres.","Pokazil sa mi počítač a potrebujem ho do práce. Nechcem o to žiadať rodičov."],
 [["ofre","Tengo un portátil viejo que no uso. Te lo puedo prestar mientras tanto.","Mám starý notebook, ktorý nepoužívam. Môžem ti ho zatiaľ požičať."],["preg","¿Por qué no quieres pedírselo a ellos?","Prečo ich o to nechceš žiadať?"],["alt","¿Y si lo llevamos a arreglar? A lo mejor sale más barato.","A čo keby sme ho dali opraviť? Možno to vyjde lacnejšie."],["lim","Te ayudo, pero me tienes que devolver el dinero en la fecha que digamos.","Pomôžem ti, ale peniaze mi musíš vrátiť v dátume, na ktorom sa dohodneme."],["apoyo","Entiendo. Para el trabajo es imprescindible.","Chápem. Do práce je to nevyhnutné."],["si","Vale. Si es para el trabajo, te los presto.","Dobre. Ak je to do práce, požičiam ti ich."]],
 ["Lo del portátil sería genial mientras ahorro. ¿De verdad no lo usas?","Ten notebook by bol super, kým si našetrím. Naozaj ho nepoužívaš?"],
 [["lim","No lo uso, pero cuídamelo y devuélvemelo cuando tengas el tuyo.","Nepoužívam ho, ale staraj sa oň a vráť mi ho, keď budeš mať svoj."],["si","De verdad. Está en el armario muerto de risa. Llévatelo.","Naozaj. Leží v skrini a nudí sa. Zober si ho."],["hum","No, desde que mi nieto me puso los juegos, no lo toco.","Nie, odkedy mi naň vnuk nainštaloval hry, nechytám sa ho."],["cari","Para ti, lo que haga falta. Pero ahorra, ¿eh?","Pre teba čokoľvek. Ale šetri, jasné?"],["expl","Es un poco lento, pero para escribir y el correo funciona bien.","Je trochu pomalý, ale na písanie a e-maily funguje dobre."],["breve","Te lo preparo.","Pripravím ti ho."]],
 ["¡Mil gracias, tía! Prefiero eso a pedir dinero. Me siento mucho mejor así.","Tisíckrát vďaka, teta! Radšej toto ako žiadať peniaze. Takto sa cítim oveľa lepšie."]
]);
D("boundaries",["Llamadas a todas horas","Telefonáty v každú hodinu"],["Tu hermano Luis","Tvoj brat Luis"],[
 ["¿Te pillo bien? Te llamaba para contarte lo del jardín.","Vyrušujem? Volal som ti, aby som ti povedal o záhrade."],
 [["lim","Luis, son las once de la noche. Ya estaba en la cama.","Luis, je jedenásť večer. Už som bola v posteli."],["alt","Ahora no puedo, ¿te llamo mañana por la mañana?","Teraz nemôžem, zavolám ti zajtra ráno?"],["duda","Bueno... cinco minutos, que es tarde.","No... päť minút, je neskoro."],["preg","¿Ha pasado algo grave?","Stalo sa niečo vážne?"],["hum","¿Lo del jardín a estas horas? ¿Te han crecido calabazas gigantes?","Záhrada v takúto hodinu? Narástli ti obrie tekvice?"],["breve","Es un poco tarde, Luis.","Je trochu neskoro, Luis."]],
 ["Ay, perdona. No me había fijado en la hora. Es que por la noche me siento solo y me apetece hablar.","Joj, prepáč. Nevšimol som si, koľko je hodín. V noci sa cítim sám a mám chuť sa porozprávať."],
 [["alt","¿Y si nos llamamos cada día a las siete? Y el domingo vente a comer con nosotros.","A čo keby sme si volali každý deň o siedmej? A v nedeľu príď k nám na obed."],["cari","Lo entiendo, Luis. A mí también me gusta hablar contigo.","Chápem, Luis. Aj ja sa s tebou rada rozprávam."],["lim","Me encanta hablar contigo, pero después de las diez necesito descansar.","Rada sa s tebou rozprávam, ale po desiatej potrebujem odpočívať."],["apoyo","Siento que te sientas solo. ¿Quieres venir a comer el domingo?","Mrzí ma, že sa cítiš sám. Chceš prísť v nedeľu na obed?"],["preg","¿Te pasa a menudo eso de sentirte solo por la noche?","Stáva sa ti často, že sa v noci cítiš sám?"],["ofre","Si quieres, te enseño a hacer videollamadas con los nietos.","Ak chceš, naučím ťa robiť videohovory s vnúčatami."]],
 ["Lo de las siete me parece bien. Y lo del domingo también, si no es molestia.","Siedma hodina mi vyhovuje. A nedeľa tiež, ak to nie je problém."],
 [["expl","Y mañana a las siete me cuentas lo del jardín con calma.","A zajtra o siedmej mi v pokoji porozprávaš o záhrade."],["si","Ninguna molestia. Te esperamos a las dos.","Žiadny problém. Čakáme ťa o druhej."],["cari","Nunca eres una molestia. Eres mi hermano.","Nikdy nie si na obtiaž. Si môj brat."],["hum","Molestia es que me llames a medianoche. El domingo es un placer.","Na obtiaž je, keď mi voláš o polnoci. Nedeľa je radosť."],["grac","Gracias por entenderlo, Luis. Te quiero mucho.","Ďakujem, že to chápeš, Luis. Mám ťa veľmi rada."],["breve","Perfecto. Buenas noches.","Výborne. Dobrú noc."]],
 ["Mañana a las siete te lo cuento todo. Buenas noches, hermana.","Zajtra o siedmej ti všetko porozprávam. Dobrú noc, sestrička."]
]);
D("boundaries",["No quiero hablar de eso","Nechcem o tom hovoriť"],["Tu cuñada Mercedes","Tvoja švagriná Mercedes"],[
 ["Oye, ¿y cuánto os costó el piso nuevo de Laura? Dicen que en ese barrio es carísimo.","Počuj, a koľko vás stál nový byt Laury? Vraj je v tej štvrti strašne drahý."],
 [["breve","Eso es privado, Mercedes.","To je súkromné, Mercedes."],["lim","Prefiero no hablar de dinero, si no te importa.","Radšej by som nehovorila o peniazoch, ak ti to nevadí."],["form","Eso es cosa de Laura y Andrés. Pregúntales a ellos.","To je vec Laury a Andrésa. Spýtaj sa ich."],["hum","Más de lo que cuesta un café, eso seguro.","Viac ako káva, to je isté."],["duda","No sé exactamente; no me metí en esos detalles.","Neviem presne; do tých detailov som sa nemiešala."],["alt","Lo importante es que están muy contentos allí.","Dôležité je, že sú tam veľmi spokojní."]],
 ["Mujer, solo era curiosidad. Como sois familia, pensé que me lo dirías.","Ale veď len zo zvedavosti. Keďže sme rodina, myslela som, že mi to povieš."],
 [["alt","Si quieres, te enseño las fotos del piso. Eso sí te lo puedo contar.","Ak chceš, ukážem ti fotky bytu. To ti povedať môžem."],["cari","Lo sé, y no me molesta que preguntes. Pero eso no me toca contarlo a mí.","Viem a nevadí mi, že sa pýtaš. Ale nie je na mne, aby som to hovorila."],["lim","Precisamente por ser familia, prefiero respetar su intimidad.","Práve preto, že sme rodina, chcem rešpektovať ich súkromie."],["opin","Hay temas que cada uno prefiere guardarse.","Sú témy, ktoré si každý radšej nechá pre seba."],["hum","Te digo una cosa: la terraza es enorme. Lo demás, secreto de Estado.","Poviem ti jedno: terasa je obrovská. Ostatné je štátne tajomstvo."],["breve","Lo entiendo, pero no.","Chápem, ale nie."]],
 ["Vale, vale. Tienes razón. Enséñame las fotos, anda.","Dobre, dobre. Máš pravdu. Ukáž mi tie fotky."],
 [["si","Mira, este es el salón. ¿A que es bonito?","Pozri, toto je obývačka. Pekná, však?"],["grac","Gracias por entenderlo. Mira, aquí está la cocina.","Ďakujem za pochopenie. Pozri, tu je kuchyňa."],["cari","Te van a encantar. Laura lo ha decorado todo ella.","Budú sa ti páčiť. Laura všetko zariadila sama."],["hum","Prepárate, que tengo ochenta y siete fotos.","Priprav sa, mám osemdesiatsedem fotiek."],["expl","Esta es la habitación de los niños. Está pintada de azul.","Toto je detská izba. Je natretá namodro."],["breve","Mira.","Pozri."]],
 ["¡Qué preciosidad! Y qué luz tiene. Me alegro mucho por ellos.","Nádhera! A koľko má svetla. Veľmi sa za nich teším."]
]);
D("disagreements",["¿Tele o paseo?","Telka alebo prechádzka?"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["Esta tarde hay partido. Yo me quedo en casa viéndolo, ¿vale?","Dnes poobede je zápas. Zostanem doma a pozriem si ho, dobre?"],
 [["preg","¿A qué hora empieza?","O koľkej sa začína?"],["duda","¿Otra vez? Habíamos quedado en dar un paseo.","Zase? Dohodli sme sa, že pôjdeme na prechádzku."],["opin","Me parece fatal. Llevamos toda la semana en casa.","To sa mi vôbec nepáči. Celý týždeň sme doma."],["alt","¿Y si damos el paseo antes del partido?","A čo keby sme sa prešli pred zápasom?"],["si","Vale, pero mañana paseamos sin excusas.","Dobre, ale zajtra sa ideme prejsť bez výhovoriek."],["hum","Claro, y yo me caso con el vecino.","Jasné, a ja sa vydám za suseda."]],
 ["Empieza a las seis. Si salimos ahora, no llego. Es la final, de verdad.","Začína sa o šiestej. Ak pôjdeme teraz, nestihnem to. Je to finále, naozaj."],
 [["lim","Vale, pero me siento un poco sola cuando pasa esto.","Dobre, ale trochu sa cítim sama, keď sa toto stane."],["opin","Siempre es una final. La semana pasada también lo era.","Vždy je to finále. Minulý týždeň tiež."],["alt","Vamos ahora, una hora corta, y volvemos a las cinco y media.","Poďme hneď, na kratšiu hodinku, a vrátime sa o pol šiestej."],["apoyo","Bueno, si es la final, lo entiendo.","No, ak je to finále, chápem."],["hum","¿Y si te grabo el partido y lo ves después?","A čo keby som ti zápas nahrala a pozrel by si si ho potom?"],["preg","¿No lo puedes escuchar en la radio mientras caminamos?","Nemôžeš ho počúvať v rádiu, kým sa budeme prechádzať?"]],
 ["Tienes razón, últimamente te dejo un poco sola. Vamos ahora una hora y vuelvo para el partido. ¿Hecho?","Máš pravdu, v poslednom čase ťa nechávam trochu samu. Poďme hneď na hodinu a na zápas sa vrátim. Platí?"],
 [["alt","Hecho, y el domingo elijo yo el plan.","Platí, a v nedeľu vyberám program ja."],["si","Hecho. Coge la chaqueta, que refresca.","Platí. Vezmi si bundu, ochladilo sa."],["grac","Gracias por escucharme. Eso es lo que necesitaba.","Ďakujem, že si ma vypočul. Presne to som potrebovala."],["cari","Hecho. Y luego te preparo algo de picar para el partido.","Platí. A potom ti k zápasu pripravím niečo na zahryznutie."],["hum","Hecho. Y si tu equipo pierde, la culpa es mía, ya lo sé.","Platí. A ak tvoj tím prehrá, je to moja vina, ja viem."],["breve","¡Vamos!","Poďme!"]],
 ["Ja, ja. Trato hecho. Y el domingo, lo que tú digas.","Ha-ha. Platí. A v nedeľu, čo povieš ty."]
]);
D("disagreements",["Un malentendido","Nedorozumenie"],["Tu nuera Sofía","Tvoja nevesta Sofía"],[
 ["Oye, ayer me sentó un poco mal lo que dijiste de la comida. Parecía que no te gustaba.","Počuj, včera ma trochu zamrzelo, čo si povedala o jedle. Vyzeralo to, akoby ti nechutilo."],
 [["preg","¿Qué dije exactamente? No me acuerdo.","Čo som presne povedala? Nepamätám si."],["disc","¡Ay, perdona! No era mi intención, de verdad.","Joj, prepáč! Naozaj to nebol môj úmysel."],["expl","Solo dije que estaba un poco salada. Me gustó mucho.","Povedala som len, že je trochu slaná. Veľmi mi chutilo."],["grac","Gracias por decírmelo. Prefiero saberlo.","Ďakujem, že si mi to povedala. Radšej to viem."],["cari","Lo siento si te hice sentir mal. Cocinas muy bien.","Prepáč, ak som ti ublížila. Varíš veľmi dobre."],["duda","Vaya, no me di cuenta. ¿Lo notaron los demás?","Ach, neuvedomila som si to. Všimli si to aj ostatní?"]],
 ["Dijiste que en tu casa se hacía «de otra manera». Me pareció una crítica.","Povedala si, že u vás doma sa to robí „inak“. Znelo to ako kritika."],
 [["expl","Ah, entiendo. Lo decía porque me recordó a mi madre, no para criticar.","Aha, chápem. Hovorila som to, lebo mi to pripomenulo mamu, nie aby som kritizovala."],["disc","Tienes razón, sonó fatal. A veces mi español me juega malas pasadas.","Máš pravdu, znelo to hrozne. Moja španielčina mi niekedy zahrá zlý vtip."],["cuenta","En mi país, decir eso es casi un elogio. Pero aquí entiendo que suene raro.","U nás je to takmer pochvala. Ale chápem, že tu to znie čudne."],["cari","Para mí es un regalo que cocines para nosotros.","Pre mňa je darom, že pre nás varíš."],["preg","¿Te habría gustado que te lo dijera de otra forma?","Bola by si radšej, keby som ti to povedala inak?"],["opin","Me alegro de que lo hablemos. Así no se queda dentro.","Teším sa, že sa o tom rozprávame. Aspoň to nezostane v nás."]],
 ["Ah, vale. Pensé que no te gustaba cómo cocino. Me quedo mucho más tranquila.","Aha, dobre. Myslela som, že sa ti nepáči, ako varím. Som oveľa pokojnejšia."],
 [["ofre","La próxima vez cocinamos juntas y nos reímos de mis frases raras.","Nabudúce budeme variť spolu a zasmejeme sa na mojich zvláštnych vetách."],["cari","Al contrario. Me encanta. Y me encantaría que me enseñaras tu receta.","Naopak. Zbožňujem to. A rada by som, keby si ma naučila svoj recept."],["grac","Gracias por hablarlo conmigo en vez de quedártelo.","Ďakujem, že si sa so mnou porozprávala, namiesto aby si si to nechala pre seba."],["hum","Si no me gustara, no habría repetido tres veces.","Keby mi nechutilo, nedala by som si trikrát."],["disc","Otra vez perdón. Intentaré explicarme mejor.","Ešte raz prepáč. Pokúsim sa vyjadrovať lepšie."],["breve","Me alegro.","Teším sa."]],
 ["¡Trato hecho! Cocinamos juntas el sábado. Y gracias por explicármelo.","Platí! V sobotu varíme spolu. A vďaka, že si mi to vysvetlila."]
]);
D("disagreements",["¿Dónde pasamos la Navidad?","Kde strávime Vianoce?"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["Este año queremos pasar la Nochebuena con la familia de Sofía. ¿Os parece bien?","Tento rok chceme stráviť Štedrý večer so Sofiinou rodinou. Je to pre vás v poriadku?"],
 [["alt","¿Y si este año hacemos una cena con las dos familias?","A čo keby sme tento rok urobili večeru s oboma rodinami?"],["duda","Bueno... nos da un poco de pena, la verdad.","No... pravdupovediac je nám to trochu ľúto."],["si","Claro, es justo. El año pasado estuvisteis con nosotros.","Jasné, je to spravodlivé. Minulý rok ste boli s nami."],["preg","¿Y el día de Navidad? ¿Lo pasaríais con nosotros?","A prvý sviatok vianočný? Strávili by ste ho s nami?"],["opin","A mí me gustaría que estuviéramos todos juntos.","Ja by som bola rada, keby sme boli všetci spolu."],["cari","Lo entiendo. Lo importante es que estéis bien.","Chápem. Dôležité je, aby ste boli v poriadku."]],
 ["Lo de las dos familias juntas... no sé, la casa de los padres de Sofía es pequeña.","Obe rodiny spolu... neviem, dom Sofiiných rodičov je malý."],
 [["ofre","Podemos hacerla en nuestra casa. Hay sitio de sobra.","Môžeme to urobiť u nás. Miesta je dosť."],["si","Entonces Nochebuena con ellos y Navidad con nosotros. Me parece justo.","Tak Štedrý večer s nimi a Vianoce s nami. Zdá sa mi to spravodlivé."],["lim","Bueno, pero el año que viene la Nochebuena es nuestra.","Dobre, ale budúci rok je Štedrý večer náš."],["preg","¿Qué piensa Sofía? No quiero que se sienta presionada.","Čo si myslí Sofía? Nechcem, aby sa cítila pod tlakom."],["apoyo","No pasa nada. Ya encontraremos una solución.","Nič sa nedeje. Nájdeme riešenie."],["hum","Pequeña, pero seguro que cabemos si no comemos mucho.","Malý, ale určite sa zmestíme, ak nebudeme veľa jesť."]],
 ["Sofía dice que le encantaría una cena con las dos familias en vuestra casa. ¿De verdad no es mucho lío?","Sofía hovorí, že by bola veľmi rada za večeru s oboma rodinami u vás. Naozaj to nie je veľa starostí?"],
 [["si","¡Qué va! Será la mejor Nochebuena en años.","Ale kdeže! Bude to najlepší Štedrý večer za roky."],["lim","Un poco sí, así que cada familia trae un plato.","Trochu áno, tak nech každá rodina prinesie jedno jedlo."],["cari","Me hace muchísima ilusión. Gracias por proponerlo.","Strašne sa teším. Vďaka, že ste to navrhli."],["ofre","Yo hago la kapustnica y los padres de Sofía, el cordero.","Ja urobím kapustnicu a Sofiini rodičia jahňacie."],["hum","Lío sí, pero de los buenos.","Starosti áno, ale tie dobré."],["breve","Para nada. Venid todos.","Vôbec nie. Príďte všetci."]],
 ["¡Genial! Se lo digo a Sofía ahora mismo. ¡Va a ser una Navidad muy especial!","Super! Hneď to poviem Sofii. Budú to veľmi zvláštne Vianoce!"]
]);
D("disagreements",["Opiniones políticas en la mesa","Politické názory pri stole"],["Tu cuñado Antonio","Tvoj švagor Antonio"],[
 ["Lo que hay que hacer es bajar todos los impuestos. Así se arregla todo, te lo digo yo.","Treba znížiť všetky dane. Tak sa všetko vyrieši, to ti hovorím ja."],
 [["opin","Yo no lo veo tan claro. Con los impuestos se pagan los hospitales.","Ja to tak jasne nevidím. Z daní sa platia nemocnice."],["preg","¿Todos? ¿Y entonces cómo se pagarían las pensiones?","Všetky? A ako by sa potom platili dôchodky?"],["lim","Antonio, ¿y si dejamos la política para otro día? Estamos de celebración.","Antonio, čo keby sme politiku nechali na inokedy? Oslavujeme."],["hum","Si bajan los impuestos del chocolate, yo te voto.","Ak znížia dane na čokoládu, budem za teba hlasovať."],["duda","Puede ser, pero es un tema complicado.","Možno, ale je to zložitá téma."],["breve","Bueno, hay opiniones para todo.","No, názory sú rôzne."]],
 ["¡Venga ya! Tú siempre defiendes lo mismo. No sé cómo puedes pensar así.","No tak! Ty vždy obhajuješ to isté. Neviem, ako môžeš takto rozmýšľať."],
 [["alt","Mira, cambiemos de tema. ¿Cómo va tu huerto?","Pozri, zmeňme tému. Ako sa darí tvojej záhradke?"],["lim","Antonio, podemos no estar de acuerdo, pero sin levantar la voz.","Antonio, nemusíme súhlasiť, ale bez zvyšovania hlasu."],["expl","Pienso así por mi experiencia. Cuando enfermó Pedro, la sanidad pública nos salvó.","Rozmýšľam tak kvôli svojej skúsenosti. Keď Pedro ochorel, verejné zdravotníctvo nás zachránilo."],["cari","Te quiero mucho, aunque votes fatal.","Mám ťa veľmi rada, aj keď voliš hrozne."],["opin","Respeto tu opinión. Te pido que respetes la mía.","Rešpektujem tvoj názor. Prosím, rešpektuj aj ty môj."],["hum","¡Y yo no sé cómo puedes ponerle piña a la pizza!","A ja neviem, ako môžeš dávať ananás na pizzu!"]],
 ["Ja, ja. Vale, tienes razón, me he calentado. Lo del huerto va de maravilla, por cierto.","Ha-ha. Dobre, máš pravdu, rozohnil som sa. Mimochodom, záhradke sa darí skvele."],
 [["si","Me alegro. ¿Me guardarás unos tomates?","Teším sa. Odložíš mi zopár paradajok?"],["grac","Gracias, Antonio. Me gusta que podamos hablar así.","Ďakujem, Antonio. Páči sa mi, že sa takto môžeme rozprávať."],["preg","¿Ah, sí? ¿Qué has plantado este año?","Naozaj? Čo si tento rok zasadil?"],["cari","No pasa nada. Los dos somos un poco cabezotas.","Nič sa nedeje. Obaja sme trochu tvrdohlaví."],["hum","Eso sí que es un tema en el que estamos de acuerdo: tus tomates son los mejores.","Tak toto je téma, v ktorej sa zhodneme: tvoje paradajky sú najlepšie."],["breve","¡Me alegro!","Teším sa!"]],
 ["¡Los mejores de toda la comarca! Te llevo una caja la semana que viene.","Najlepšie v celom kraji! Budúci týždeň ti prinesiem debničku."]
]);
D("disagreements",["Pedir perdón","Ospravedlniť sa"],["Tu nieto Pablo","Tvoj vnuk Pablo"],[
 ["Abuela... ¿sigues enfadada por lo de ayer?","Babi... ešte sa hneváš kvôli včerajšku?"],
 [["expl","Un poco. Me dolió que me hablaras de esa manera.","Trochu. Bolelo ma, že si so mnou takto hovoril."],["cari","Ya no, cariño. Pero me gustaría que lo habláramos.","Už nie, zlatko. Ale rada by som sa o tom porozprávala."],["preg","¿Tú qué crees? ¿Cómo te sentirías tú?","Čo myslíš ty? Ako by si sa cítil ty?"],["lim","Sí, porque no me gusta que me griten.","Áno, lebo nemám rada, keď na mňa niekto kričí."],["si","No, ya se me ha pasado. ¿Y a ti?","Nie, už ma to prešlo. A teba?"],["breve","Un poquito.","Trošku."]],
 ["Lo siento. Estaba de mal humor por el examen y lo pagué contigo. No te lo merecías.","Prepáč. Mal som zlú náladu kvôli skúške a vybil som si to na tebe. Nezaslúžila si si to."],
 [["apoyo","¿Cómo te fue el examen al final?","A ako ti nakoniec dopadla skúška?"],["grac","Gracias por pedir perdón. Eso es de valientes.","Ďakujem, že si sa ospravedlnil. To je odvážne."],["cari","Te perdono. Todos tenemos días malos.","Odpúšťam ti. Každý má zlé dni."],["opin","Entiendo que estuvieras nervioso, pero la próxima vez dímelo sin gritar.","Chápem, že si bol nervózny, ale nabudúce mi to povedz bez kriku."],["cuenta","Yo también pagaba mis enfados con mi madre. Luego me arrepentía.","Aj ja som si hnev vybíjala na mame. Potom som to ľutovala."],["hum","Disculpas aceptadas. Pero me debes una partida de cartas.","Ospravedlnenie prijaté. Ale dlhuješ mi partiu kariet."]],
 ["Me fue regular. Pero eso no es excusa. ¿Me das un abrazo?","Dopadla tak-tak. Ale to nie je ospravedlnenie. Objímeš ma?"],
 [["cari","Claro que sí. Ven aquí.","Jasné, že áno. Poď sem."],["si","Por supuesto. Y ahora cuéntame lo del examen.","Samozrejme. A teraz mi povedz o tej skúške."],["hum","Un abrazo y una merienda. Así se cierran los enfados en esta casa.","Objatie a olovrant. Tak sa v tomto dome končia hnevy."],["anim","Y el próximo examen, a por todas. Yo te ayudo.","A na ďalšej skúške daj zo seba všetko. Pomôžem ti."],["grac","Gracias a ti. Me ha gustado mucho que vinieras a hablar.","Vďaka tebe. Veľmi sa mi páčilo, že si prišiel porozprávať sa."],["breve","Ven, tonto.","Poď sem, hlupáčik."]],
 ["Gracias, abuela. Eres la mejor. ¿Me ayudas con mates el martes?","Ďakujem, babi. Si najlepšia. Pomôžeš mi v utorok s matikou?"]
]);
D("memories",["Cuando eras pequeño","Keď si bol malý"],["Tu nieta Lucía","Tvoja vnučka Lucía"],[
 ["Abuelo, ¿cómo era tu vida cuando tenías mi edad?","Dedo, aký bol tvoj život, keď si mal toľko rokov ako ja?"],
 [["recu","Muy distinta. Con veinte años ya trabajaba en una fábrica.","Veľmi iný. V dvadsiatich som už pracoval v továrni."],["preg","¿Qué quieres saber? ¿Del trabajo, de los amigos...?","Čo chceš vedieť? O práci, o kamarátoch...?"],["hum","En blanco y negro, como las fotos.","Čiernobiely, ako fotky."],["cuenta","Vivía en un pueblo pequeño de Eslovaquia, entre montañas.","Býval som v malej dedinke na Slovensku medzi horami."],["cari","¡Qué bonito que me preguntes eso! Siéntate.","Aké pekné, že sa ma na to pýtaš! Sadni si."],["breve","Uf, otra época.","Uf, iná doba."]],
 ["¿Y qué hacíais para divertiros? No había móviles ni internet.","A čo ste robili pre zábavu? Neboli mobily ani internet."],
 [["recu","Los domingos había baile en la plaza. Allí conocí a tu abuela.","V nedeľu bola tancovačka na námestí. Tam som spoznal tvoju babku."],["cuenta","Íbamos en bici al río y nos bañábamos hasta que anochecía.","Chodili sme na bicykli k rieke a kúpali sme sa až do tmy."],["hum","Nos aburríamos muchísimo. Por eso inventábamos tonterías.","Strašne sme sa nudili. Preto sme vymýšľali hlúposti."],["expl","Leíamos mucho y escuchábamos la radio en familia.","Veľa sme čítali a s rodinou sme počúvali rádio."],["preg","¿Qué crees tú que hacíamos?","Čo myslíš, čo sme robili?"],["opin","Teníamos menos cosas, pero más tiempo para estar juntos.","Mali sme menej vecí, ale viac času byť spolu."]],
 ["¿Conociste a la abuela en un baile? ¡Cuéntamelo todo!","Spoznal si babku na tancovačke? Povedz mi všetko!"],
 [["preg","¿Quieres ver la foto de aquel día? Tengo una.","Chceš vidieť fotku z toho dňa? Mám jednu."],["recu","Llevaba un vestido rojo. No me atreví a sacarla a bailar hasta la tercera canción.","Mala červené šaty. Až pri tretej piesni som sa odvážil vyzvať ju do tanca."],["hum","Le pisé los pies tres veces, y aun así se casó conmigo.","Trikrát som jej stúpil na nohy, a aj tak si ma vzala."],["cari","Fue la mejor noche de mi vida. Desde entonces no nos separamos.","Bola to najkrajšia noc môjho života. Odvtedy sme sa nerozdelili."],["cuenta","Ella no quería bailar conmigo; su amiga la convenció.","Nechcela so mnou tancovať; presvedčila ju kamarátka."],["breve","Fue amor a primera vista.","Bola to láska na prvý pohľad."]],
 ["¡Ay, qué bonito! Sí, enséñame la foto, por favor.","Jaj, aké pekné! Áno, ukáž mi fotku, prosím."]
]);
D("memories",["La casa del pueblo","Dom na dedine"],["Tu hermana Rosa","Tvoja sestra Rosa"],[
 ["He pasado por delante de la casa del pueblo. La han pintado de amarillo. ¡Casi no la reconozco!","Prechádzala som okolo domu na dedine. Natreli ho nažlto. Takmer som ho nespoznala!"],
 [["preg","¿Y el huerto? ¿Sigue estando el nogal?","A záhrada? Stojí ešte orech?"],["recu","¿De amarillo? ¡Si siempre fue blanca con las ventanas verdes!","Nažlto? Veď vždy bol biely so zelenými oknami!"],["hum","Mamá se levantaría de la tumba si lo viera.","Mama by sa obrátila v hrobe, keby to videla."],["cari","Qué nostalgia me da pensar en esa casa.","Akú nostalgiu cítim, keď myslím na ten dom."],["opin","Bueno, es de otra familia ahora. Que la disfruten.","No, teraz je iná rodina. Nech sa im v ňom dobre býva."],["breve","¡No me digas!","Nehovor!"]],
 ["El nogal sigue ahí, enorme. Y el banco de piedra de la entrada, también.","Orech tam stále je, obrovský. A kamenná lavička pri vchode tiež."],
 [["cuenta","En ese banco me dio mi primer beso Jozef, ¿te acuerdas?","Na tej lavičke ma prvýkrát pobozkal Jozef, pamätáš?"],["recu","¡El banco! Allí se sentaba papá a fumar en pipa cada tarde.","Lavička! Tam si otec každé poobedie sadal fajčiť fajku."],["cari","Me alegra que algo siga igual.","Teší ma, že niečo zostalo rovnaké."],["preg","¿Hiciste alguna foto? Me encantaría verla.","Urobila si fotku? Rada by som ju videla."],["hum","¿Y las nueces? ¿Te llevaste alguna, como cuando éramos niñas?","A orechy? Vzala si si nejaké, ako keď sme boli malé?"],["breve","¡Qué recuerdos!","To sú spomienky!"]],
 ["¡Claro que me acuerdo de Jozef! Tú tenías quince años y estabas roja como un tomate.","Jasné, že si pamätám Jozefa! Mala si pätnásť a bola si červená ako paradajka."],
 [["alt","Oye, ¿y si este verano vamos juntas al pueblo?","Počuj, a čo keby sme toto leto išli spolu na dedinu?"],["hum","Y tú se lo contaste a toda la familia en la cena. ¡Nunca te lo perdoné!","A ty si to povedala celej rodine pri večeri. Nikdy som ti to neodpustila!"],["recu","Y mamá nos castigó a las dos sin postre una semana.","A mama nás obe potrestala týždňom bez dezertu."],["cari","Qué suerte tenemos de poder recordarlo juntas.","Aké máme šťastie, že si na to môžeme spomínať spolu."],["preg","¿Sabes qué fue de Jozef?","Vieš, čo sa stalo s Jozefom?"],["breve","¡Qué vergüenza pasé!","Ako som sa hanbila!"]],
 ["¡Vamos este verano! Nos sentamos en el banco, aunque la casa sea amarilla.","Poďme toto leto! Sadneme si na lavičku, aj keď je dom žltý."]
]);
D("memories",["Las recetas de la abuela","Recepty starej mamy"],["Tu nuera Sofía","Tvoja nevesta Sofía"],[
 ["¿Qué plato te recuerda más a tu infancia?","Ktoré jedlo ti najviac pripomína detstvo?"],
 [["recu","Los «pirohy» de mi abuela. Los hacía cada domingo.","Pirohy od mojej starej mamy. Robila ich každú nedeľu."],["preg","¡Qué pregunta tan bonita! ¿Y a ti?","Aká pekná otázka! A tebe?"],["cuenta","La sopa de setas que hacía mi madre en otoño.","Hubová polievka, ktorú robievala mama na jeseň."],["hum","El pan con manteca y azúcar. ¡Los médicos de hoy se desmayarían!","Chlieb s masťou a cukrom. Dnešní lekári by omdleli!"],["duda","Uf, son tantos... Déjame pensar.","Uf, je ich toľko... Nechaj ma porozmýšľať."],["breve","Las tortitas de patata.","Zemiakové placky."]],
 ["¿Pirohy? ¿Qué son? Nunca los he probado.","Pirohy? Čo je to? Nikdy som ich neochutnala."],
 [["ofre","Un día te los preparo. Son un poco laboriosos, pero valen la pena.","Raz ti ich pripravím. Je s nimi trochu roboty, ale oplatí sa to."],["expl","Son como empanadillas de masa cocida, rellenas de patata y queso.","Sú ako taštičky z vareného cesta, plnené zemiakmi a syrom."],["recu","Mi abuela los hacía en una mesa enorme, y yo le robaba la masa.","Stará mama ich robila na obrovskom stole a ja som jej kradla cesto."],["hum","Son la razón por la que ningún eslovaco pasa frío en invierno.","Sú dôvodom, prečo žiadny Slovák v zime nemrzne."],["cuenta","También se hacen dulces, con mermelada de ciruela.","Robia sa aj sladké, so slivkovým lekvárom."],["preg","¿En España hay algo parecido?","Je v Španielsku niečo podobné?"]],
 ["¡Me encantaría aprender a hacerlos! ¿Tienes la receta de tu abuela?","Rada by som sa ich naučila robiť! Máš recept od starej mamy?"],
 [["recu","Nunca la escribió. La llevo aquí, en la memoria de las manos.","Nikdy ho nenapísala. Nosím ho tu, v pamäti rúk."],["si","Sí, la copié en un cuaderno. Te la traduzco.","Áno, odpísala som si ho do zošita. Preložím ti ho."],["ofre","Mejor te la enseño cocinando. Así se aprende de verdad.","Radšej ťa ho naučím pri varení. Tak sa to človek naozaj naučí."],["cari","Me hace mucha ilusión que quieras aprenderla.","Veľmi ma teší, že sa ho chceš naučiť."],["hum","Tengo la receta, pero sin cantidades: «un poco de esto, un poco de aquello».","Recept mám, ale bez množstiev: „trochu toho, trochu tamtoho“."],["breve","La tengo. Te la paso.","Mám ho. Dám ti ho."]],
 ["¡Pues cocinamos juntas un domingo y así la escribimos entre las dos!","Tak niektorú nedeľu uvaríme spolu a spíšeme ho obe!"]
]);
D("memories",["Llegar a España","Príchod do Španielska"],["Tu nieto Hugo, para un trabajo del colegio","Tvoj vnuk Hugo, do školskej úlohy"],[
 ["Abuela, tengo que hacer un trabajo sobre la familia. ¿Por qué viniste a vivir a España?","Babi, mám urobiť úlohu o rodine. Prečo si prišla žiť do Španielska?"],
 [["expl","Porque tu madre vivía aquí y queríamos estar cerca de vosotros.","Pretože tvoja mama tu žila a chceli sme byť blízko vás."],["recu","Vinimos por primera vez de vacaciones y nos enamoramos del país.","Prvýkrát sme sem prišli na dovolenku a zamilovali sme sa do tejto krajiny."],["cari","Por ti, por tu hermana y por tu madre. Por estar juntos.","Kvôli tebe, tvojej sestre a mame. Aby sme boli spolu."],["hum","Por el sol. ¿Has visto los inviernos de Eslovaquia?","Kvôli slnku. Videl si slovenské zimy?"],["preg","¿Qué te han dicho tus padres?","Čo ti povedali rodičia?"],["breve","Por amor a la familia.","Z lásky k rodine."]],
 ["¿Y fue difícil? ¿Hablabas español cuando llegaste?","A bolo to ťažké? Hovorila si po španielsky, keď si prišla?"],
 [["preg","¿Tú crees que hablo bien ahora?","Myslíš, že teraz hovorím dobre?"],["recu","Casi nada. Solo sabía decir «hola», «gracias» y «un café, por favor».","Skoro vôbec. Vedela som povedať len „ahoj“, „ďakujem“ a „kávu, prosím“."],["cuenta","Fue difícil. El primer año lloraba a menudo porque no entendía a nadie.","Bolo to ťažké. Prvý rok som často plakala, lebo som nikomu nerozumela."],["hum","Hablaba como un turista perdido. Pedía «pescado» y me traían «pecado».","Hovorila som ako stratený turista. Pýtala som „pescado“ a doniesli mi „pecado“."],["expl","Fui a clases dos veces por semana, y todavía sigo aprendiendo.","Chodila som na hodiny dvakrát týždenne a stále sa učím."],["opin","Fue difícil, pero mereció la pena.","Bolo to ťažké, ale stálo to za to."]],
 ["¡Hablas genial! ¿Qué es lo que más te gusta de vivir aquí?","Hovoríš super! Čo sa ti na živote tu páči najviac?"],
 [["cuenta","La luz, la gente en la calle y las conversaciones en los bares.","Svetlo, ľudia na ulici a rozhovory v baroch."],["cari","Teneros cerca. Ver cómo crecéis cada semana.","Mať vás blízko. Vidieť, ako každý týždeň rastiete."],["hum","Que aquí cenar a las diez es normal. ¡En Eslovaquia ya estaríamos dormidos!","Že tu je normálne večerať o desiatej. Na Slovensku by sme už spali!"],["opin","Que la gente es muy abierta y te ayuda aunque no te conozca.","Že ľudia sú veľmi otvorení a pomôžu ti, aj keď ťa nepoznajú."],["grac","Gracias por preguntarme. Nadie me lo había preguntado así.","Ďakujem, že sa pýtaš. Nikto sa ma na to takto nespýtal."],["breve","Vosotros.","Vy."]],
 ["¡Me lo apunto todo! Y pongo que mi abuela habla dos idiomas. Eso mola mucho.","Všetko si zapíšem! A napíšem, že moja babka hovorí dvoma jazykmi. To je super."]
]);
D("memories",["Una foto antigua","Stará fotka"],["Tu hija Laura","Tvoja dcéra Laura"],[
 ["Mira lo que he encontrado ordenando: una foto tuya de joven en la playa. ¿Dónde es?","Pozri, čo som našla pri upratovaní: tvoja fotka z mladosti na pláži. Kde to je?"],
 [["recu","¡Ay, qué foto! Es en Bulgaria, en el mar Negro. Tenía veintidós años.","Joj, aká fotka! To je v Bulharsku pri Čiernom mori. Mala som dvadsaťdva."],["hum","¡Qué guapa estaba! ¿Qué ha pasado desde entonces?","Aká som bola pekná! Čo sa odvtedy stalo?"],["preg","¿Dónde la has encontrado? La buscaba hace años.","Kde si ju našla? Roky som ju hľadala."],["cari","Fue mi primer viaje al mar. Qué feliz era.","Bola to moja prvá cesta k moru. Aká som bola šťastná."],["duda","Creo que es en Bulgaria, pero no estoy segura.","Myslím, že je to v Bulharsku, ale nie som si istá."],["breve","¡En el mar Negro!","Pri Čiernom mori!"]],
 ["¿Y quién es la chica que está a tu lado?","A kto je to dievča vedľa teba?"],
 [["cuenta","Zuzana. Hace treinta años que no sé nada de ella.","Zuzana. Už tridsať rokov o nej nič neviem."],["recu","Es Zuzana, mi mejor amiga del instituto. Fuimos juntas en tren.","To je Zuzana, moja najlepšia kamarátka zo strednej. Išli sme spolu vlakom."],["hum","Es Zuzana. Ella siempre salía mejor que yo en las fotos.","To je Zuzana. Ona vždy na fotkách vyzerala lepšie ako ja."],["cari","Mi amiga Zuzana. La quise como a una hermana.","Moja kamarátka Zuzana. Mala som ju rada ako sestru."],["duda","Creo que se llamaba Zuzana... o Zdenka. ¡Qué memoria!","Myslím, že sa volala Zuzana... alebo Zdenka. Aká pamäť!"],["breve","Mi amiga Zuzana.","Moja kamarátka Zuzana."]],
 ["¿Y si la buscamos en internet? A lo mejor la encontramos.","A čo keby sme ju hľadali na internete? Možno ju nájdeme."],
 [["si","¡Sí! Me encantaría saber qué fue de ella.","Áno! Veľmi rada by som vedela, čo sa s ňou stalo."],["duda","No sé... ¿Y si no se acuerda de mí?","Neviem... A čo ak si na mňa nespomenie?"],["preg","¿Se puede buscar a alguien así, solo con el nombre?","Dá sa niekto takto hľadať, len podľa mena?"],["cari","Qué buena idea, hija. Me harías muy feliz.","Aký dobrý nápad, dcérka. Veľmi by si ma potešila."],["hum","Vale, pero si la encontramos, no le enseñes esta foto, que salgo con ese bañador.","Dobre, ale ak ju nájdeme, neukazuj jej túto fotku, som tam v tých plavkách."],["expl","Su apellido de soltera era Kováčová. Era de Žilina.","Za slobodna sa volala Kováčová. Bola zo Žiliny."]],
 ["¡Vamos a intentarlo! Trae el portátil y una taza de té, que esto puede ser largo.","Skúsime to! Prines notebook a šálku čaju, môže to trvať dlho."]
]);
D("interests",["El libro que estoy leyendo","Kniha, ktorú čítam"],["Tu yerno Andrés","Tvoj zať Andrés"],[
 ["¿Qué estás leyendo? Te veo muy enganchada a ese libro.","Čo čítaš? Vidím, že ťa tá kniha veľmi chytila."],
 [["expl","Es una novela de Almudena Grandes, sobre la posguerra.","Je to román od Almudeny Grandes o povojnovom období."],["si","¡Sí! No puedo dejarlo. Llevo tres noches leyendo hasta tarde.","Áno! Nemôžem ho odložiť. Tri noci čítam dlho do noci."],["preg","¿Tú la has leído? Es de una escritora española.","Čítal si ju? Je od španielskej spisovateľky."],["hum","Estoy enganchadísima. Si no contesto al teléfono, ya sabéis por qué.","Úplne ma chytila. Ak nebudem dvíhať telefón, viete prečo."],["duda","Me gusta, aunque a veces me cuesta un poco el español.","Páči sa mi, aj keď so španielčinou mám niekedy trochu problém."],["breve","Una novela buenísima.","Výborný román."]],
 ["¿Y de qué va? Siempre busco libros nuevos.","A o čom je? Vždy hľadám nové knihy."],
 [["preg","No te cuento mucho, que no quiero estropeártela. ¿Te la presto?","Nepoviem ti veľa, nechcem ti ju pokaziť. Požičiam ti ju?"],["expl","De una familia que intenta sobrevivir después de la guerra. Es muy humana.","O rodine, ktorá sa po vojne snaží prežiť. Je veľmi ľudská."],["opin","Me ha ayudado a entender muchas cosas de la historia de España.","Pomohla mi pochopiť veľa vecí zo španielskych dejín."],["cuenta","Me recuerda a lo que contaba mi abuela de la guerra en Eslovaquia.","Pripomína mi to, čo rozprávala stará mama o vojne na Slovensku."],["hum","Va de gente que sufre mucho, pero con frases preciosas.","Je o ľuďoch, ktorí veľa trpia, ale s krásnymi vetami."],["breve","De familia y de memoria.","O rodine a pamäti."]],
 ["¡Me encantaría que me la prestaras! ¿Y luego la comentamos juntos?","Bol by som rád, keby si mi ju požičala! A potom by sme sa o nej porozprávali?"],
 [["si","¡Claro! Te la dejo cuando la termine, la semana que viene.","Jasné! Požičiam ti ju, keď ju dočítam, budúci týždeň."],["cari","Me encantaría tener alguien con quien comentar libros.","Veľmi rada by som mala niekoho, s kým sa môžem rozprávať o knihách."],["alt","Mejor te compro una, que yo subrayo todo.","Radšej ti jednu kúpim, ja si všetko podčiarkujem."],["hum","Sí, pero si lloras en el capítulo doce, no es culpa mía.","Áno, ale ak budeš plakať pri dvanástej kapitole, nie je to moja vina."],["preg","¿Y tú qué estás leyendo ahora?","A čo teraz čítaš ty?"],["breve","Trato hecho.","Platí."]],
 ["Trato hecho. Hacemos un club de lectura de dos. ¡O de tres, si se apunta Laura!","Platí. Urobíme čitateľský klub pre dvoch. Alebo troch, ak sa pridá Laura!"]
]);
D("interests",["Una afición nueva","Nový koníček"],["Tu nieta Lucía","Tvoja vnučka Lucía"],[
 ["Abuela, me he apuntado a clases de cerámica. ¿Tú has hecho cerámica alguna vez?","Babi, prihlásila som sa na kurz keramiky. Robila si niekedy keramiku?"],
 [["preg","¡Qué bien! ¿Y qué estás haciendo?","To je super! A čo robíš?"],["si","¡Sí! De joven hice un curso. Todavía tengo un jarrón que hice yo.","Áno! Ako mladá som absolvovala kurz. Stále mám vázu, čo som urobila."],["no","Nunca, pero siempre me ha llamado la atención.","Nikdy, ale vždy ma to lákalo."],["hum","Solo hice churros de plastilina con tu madre.","Robila som len hadíky z plastelíny s tvojou mamou."],["anim","Me parece estupendo. Es muy relajante, dicen.","To je skvelé. Vraj je to veľmi upokojujúce."],["breve","¡Qué interesante!","Aké zaujímavé!"]],
 ["Estoy haciendo un cuenco. Me sale torcido, pero me encanta. Es como meditar.","Robím misku. Ide mi nakrivo, ale páči sa mi to. Je to ako meditácia."],
 [["hum","Torcido o recto, quiero el primero para mí.","Krivá alebo rovná, tú prvú chcem ja."],["anim","Los cuencos torcidos tienen más personalidad.","Krivé misky majú viac osobnosti."],["cuenta","Mi primer jarrón parecía una patata. Y lo guardo con orgullo.","Moja prvá váza vyzerala ako zemiak. A hrdo si ju opatrujem."],["preg","¿Usas torno o lo haces a mano?","Používaš hrnčiarsky kruh, alebo to robíš ručne?"],["opin","Hacer algo con las manos es muy sano para la cabeza.","Robiť niečo rukami je pre hlavu veľmi zdravé."],["cari","Me alegra verte tan contenta con algo nuevo.","Teší ma, že ťa niečo nové tak teší."]],
 ["¡Te lo regalo! Oye, ¿te vendrías un día a una clase conmigo?","Darujem ti ju! Počuj, prišla by si niekedy so mnou na hodinu?"],
 [["si","¡Me encantaría! Dime qué día y allí estaré.","Veľmi rada! Povedz, ktorý deň, a budem tam."],["duda","Me apetece, pero no sé si mis manos tienen ya fuerza para eso.","Mám chuť, ale neviem, či moje ruky na to ešte majú silu."],["hum","Vale, pero si mancho a alguien de barro, no me conoces.","Dobre, ale ak niekoho zašpiním hlinou, nepoznáš ma."],["cari","Hacer algo contigo es el mejor plan del mundo.","Robiť niečo s tebou je najlepší plán na svete."],["preg","¿Tengo que llevar algo? ¿Delantal, ropa vieja?","Musím si niečo zobrať? Zásteru, staré oblečenie?"],["breve","¡Claro que sí!","Jasné, že áno!"]],
 ["¡Genial! El jueves a las seis. Trae ropa vieja, que se mancha todo.","Super! Vo štvrtok o šiestej. Zober si staré oblečenie, všetko sa zašpiní."]
]);
D("interests",["Hablar de una película","Rozhovor o filme"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["¿Visteis anoche la película de la tele? ¿Qué os pareció?","Videli ste včera ten film v telke? Čo poviete?"],
 [["preg","Sí. ¿Tú entendiste por qué se fue el padre?","Áno. Pochopil si, prečo otec odišiel?"],["opin","Me gustó mucho, aunque el final me pareció un poco triste.","Veľmi sa mi páčil, hoci koniec sa mi zdal trochu smutný."],["no","No me gustó nada. Muy lenta.","Vôbec sa mi nepáčil. Veľmi pomalý."],["duda","Me quedé dormida a la mitad, la verdad.","Pravdupovediac, v polovici som zaspala."],["hum","Tu padre la vio; yo vi a tu padre roncando.","Tvoj otec ho videl; ja som videla tvojho otca chrápať."],["breve","Preciosa.","Nádherný."]],
 ["Yo creo que el padre se fue porque se sentía culpable, no porque no los quisiera.","Ja si myslím, že otec odišiel, lebo sa cítil vinný, nie preto, že by ich nemal rád."],
 [["preg","¿Culpable de qué? No me quedó claro.","Vinný z čoho? Nebolo mi to jasné."],["si","Eso mismo pensé yo. Por eso volvió al final.","Presne to som si myslela aj ja. Preto sa na konci vrátil."],["opin","Yo lo vi de otra manera. Creo que tenía miedo.","Ja som to videla inak. Myslím, že sa bál."],["cuenta","Me recordó a mi tío, que también se fue y volvió años después.","Pripomenulo mi to môjho strýka, ktorý tiež odišiel a vrátil sa po rokoch."],["duda","Puede ser. No lo había pensado así.","Možno. Takto som o tom nerozmýšľala."],["hum","Culpable o no, podría haber avisado.","Vinný či nie, mohol dať vedieť."]],
 ["Por el accidente del hermano. ¿Te acuerdas de la escena del lago?","Kvôli nehode brata. Pamätáš si scénu pri jazere?"],
 [["hum","¡Ah, el lago! Ahí fue cuando me dormí.","Ach, jazero! Tam som zaspala."],["si","¡Ah, claro! Ahora lo entiendo todo.","Ach, jasné! Teraz tomu všetkému rozumiem."],["duda","Esa parte me la perdí, estaba en la cocina.","Tú časť som zmeškala, bola som v kuchyni."],["opin","Entonces es una película sobre el perdón, más que sobre el abandono.","Tak je to film skôr o odpustení než o opustení."],["alt","¿La vemos otra vez juntos el fin de semana?","Pozrieme si ho znova spolu cez víkend?"],["cari","Me encanta hablar de películas contigo. Lo ves todo.","Rada sa s tebou rozprávam o filmoch. Všetko vidíš."]],
 ["Ja, ja. ¡Pues la vemos juntos el sábado, y esta vez con café!","Ha-ha. Tak si ho pozrieme spolu v sobotu, a tentoraz s kávou!"]
]);
D("interests",["El huerto","Záhradka"],["Tu vecino Ramón","Tvoj sused Ramón"],[
 ["¡Qué tomates más bonitos tienes en la terraza! ¿Cuál es el secreto?","Aké pekné paradajky máš na terase! Aké je tajomstvo?"],
 [["preg","¿Tú también tienes plantas? No sabía que te gustaban.","Aj ty máš rastliny? Nevedela som, že ich máš rád."],["expl","Mucho sol, agua por la tarde y hablarles un poco cada día.","Veľa slnka, voda poobede a trochu sa s nimi každý deň porozprávať."],["hum","El secreto es que les hablo en eslovaco. No entienden nada y crecen de los nervios.","Tajomstvo je, že sa s nimi rozprávam po slovensky. Ničomu nerozumejú a rastú od nervov."],["cuenta","Las semillas me las trajo mi hermana de Eslovaquia.","Semienka mi priniesla sestra zo Slovenska."],["grac","¡Gracias! Me hace mucha ilusión que lo digas.","Ďakujem! Veľmi ma teší, že to hovoríš."],["breve","Paciencia y mucho sol.","Trpezlivosť a veľa slnka."]],
 ["Yo intento plantar cosas, pero se me mueren todas. Creo que tengo mala mano.","Ja sa snažím niečo pestovať, ale všetko mi uschne. Myslím, že nemám šťastnú ruku."],
 [["opin","Empieza con algo fácil, como hierbas aromáticas.","Začni niečím ľahkým, napríklad bylinkami."],["ofre","Si quieres, un día te enseño lo que hago yo.","Ak chceš, raz ti ukážem, čo robím ja."],["preg","¿Qué plantas tienes? ¿Dónde las pones?","Aké rastliny máš? Kam ich dávaš?"],["apoyo","No es mala mano, es que hay que aprender. A mí también se me morían.","Nie je to zlá ruka, treba sa to naučiť. Aj mne uschýnali."],["hum","¿Las riegas o las ahogas? Esa es la cuestión.","Polievaš ich, alebo ich topíš? To je otázka."],["cari","Seguro que con un poco de ayuda te salen preciosas.","Určite sa ti s trochou pomoci podaria nádherné."]],
 ["Lo de las hierbas aromáticas me gusta. ¿Me ayudarías a elegirlas?","Bylinky sa mi páčia. Pomohla by si mi ich vybrať?"],
 [["si","¡Claro! El sábado vamos juntos al vivero.","Jasné! V sobotu pôjdeme spolu do záhradníctva."],["ofre","Te doy unos esquejes de mi menta y de mi albahaca.","Dám ti odrezky z mojej mäty a bazalky."],["expl","Romero, tomillo y perejil. Son muy fáciles y huelen de maravilla.","Rozmarín, tymian a petržlen. Sú veľmi ľahké a krásne voňajú."],["hum","Sí, pero te advierto: me pongo muy pesada con las plantas.","Áno, ale upozorňujem ťa: s rastlinami som veľmi otravná."],["cari","Me encanta tener un compañero de huerto.","Som rada, že mám parťáka do záhradky."],["breve","¡Con mucho gusto!","S veľkou radosťou!"]],
 ["¡Gracias! Y si me salen bien, te invito a una tortilla con perejil de mi terraza.","Ďakujem! A ak sa mi podaria, pozvem ťa na omeletu s petržlenom z mojej terasy."]
]);
D("interests",["Aprender algo nuevo","Naučiť sa niečo nové"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["Estoy pensando en aprender a tocar la guitarra. ¿Te parece una locura a mi edad?","Rozmýšľam, že sa naučím hrať na gitare. Zdá sa ti to v mojom veku šialené?"],
 [["preg","¿Y eso? ¿De dónde te ha venido la idea?","A to prečo? Odkiaľ ti prišiel ten nápad?"],["anim","¡Para nada! Nunca es tarde para aprender.","Vôbec nie! Na učenie nie je nikdy neskoro."],["hum","Un poco, pero las mejores ideas siempre son un poco locas.","Trochu, ale najlepšie nápady sú vždy trochu šialené."],["duda","Me parece bien, aunque tus dedos ya no son tan ágiles.","Súhlasím, aj keď tvoje prsty už nie sú také obratné."],["cari","Me encanta verte con ganas de cosas nuevas.","Rada ťa vidím, keď máš chuť na nové veci."],["breve","¡Me parece genial!","To je skvelé!"]],
 ["De joven siempre quise tocar, pero nunca tuve tiempo. Ahora sí lo tengo.","Ako mladý som vždy chcel hrať, ale nikdy som nemal čas. Teraz ho mám."],
 [["preg","¿Y qué te gustaría tocar? ¿Flamenco, canciones antiguas...?","A čo by si chcel hrať? Flamenco, staré piesne...?"],["si","Pues es el momento perfecto. ¿Buscamos una academia?","Tak je to ideálna chvíľa. Pohľadáme hudobnú školu?"],["ofre","Mi amiga Maribel da clases. Le pregunto si tiene hueco.","Moja kamarátka Maribel dáva hodiny. Spýtam sa jej, či má voľno."],["opin","Hay muchos vídeos en internet para empezar desde casa.","Na internete je veľa videí, aby si mohol začať doma."],["hum","Vale, pero practica cuando yo esté en el mercado.","Dobre, ale cvič, keď budem na trhu."],["cari","Me hace ilusión que por fin cumplas ese sueño.","Teší ma, že si konečne splníš ten sen."]],
 ["Canciones antiguas, de las que bailábamos de jóvenes. Y la primera, para ti.","Staré piesne, na ktoré sme tancovali ako mladí. A prvú pre teba."],
 [["anim","Entonces empieza mañana mismo, que quiero mi canción pronto.","Tak začni hneď zajtra, chcem svoju pieseň čoskoro."],["cari","Me has emocionado. Ya tengo ganas de oírla.","Dojal si ma. Už sa teším, keď ju budem počuť."],["hum","Vale, pero que no sea la del baile en el que me pisaste.","Dobre, ale nech to nie je tá z tancovačky, kde si mi stúpil na nohu."],["recu","¿La de aquel verano en el lago? ¡Qué tiempos!","Tú z toho leta pri jazere? To boli časy!"],["si","Trato hecho. Y yo te acompaño cantando.","Platí. A ja ťa budem sprevádzať spevom."],["breve","¡Qué bonito!","Aké pekné!"]],
 ["Ja, ja. Prometido. Mañana mismo busco la guitarra en el trastero.","Ha-ha. Sľubujem. Hneď zajtra pohľadám gitaru v komore."]
]);
D("outings",["Un paseo por el parque","Prechádzka po parku"],["Tu nieto Hugo","Tvoj vnuk Hugo"],[
 ["Abuelo, ¿vamos al parque? Quiero enseñarte cómo monto en bici sin ruedas.","Dedo, pôjdeme do parku? Chcem ti ukázať, ako jazdím na bicykli bez pomocných kolies."],
 [["preg","¿Sin ruedas? ¿Desde cuándo?","Bez kolies? Odkedy?"],["si","¡Claro! Coge el casco y vamos.","Jasné! Zober si prilbu a ideme."],["hum","¿Sin ruedas? ¿Y yo tengo que correr detrás de ti?","Bez kolies? A ja musím bežať za tebou?"],["alt","Ahora hace mucho calor. ¿Vamos a las seis?","Teraz je veľké teplo. Pôjdeme o šiestej?"],["cari","¡Qué orgulloso estoy de ti! Vamos ahora mismo.","Aký som na teba hrdý! Ideme hneď."],["breve","¡Vamos!","Ideme!"]],
 ["¡Desde el domingo! Papá me soltó y no me caí. Bueno, solo una vez.","Od nedele! Ocko ma pustil a nespadol som. No, len raz."],
 [["preg","¿Te hiciste daño cuando te caíste?","Udrel si sa, keď si spadol?"],["anim","¡Eso es de campeones! Caerse es parte de aprender.","To je na šampióna! Padať je súčasť učenia."],["cuenta","Yo aprendí con una bici vieja de mi hermano, y me caí mil veces.","Ja som sa učil na starom bratovom bicykli a spadol som tisíckrát."],["hum","Solo una vez. Yo me caí ayer del sofá, así que me ganas.","Len raz. Ja som včera spadol z gauča, takže si lepší ako ja."],["cari","Qué valiente eres. Tengo muchas ganas de verte.","Aký si statočný. Strašne sa teším, keď ťa uvidím."],["breve","¡Bravo!","Bravo!"]],
 ["Un poco en la rodilla. ¿Me compras un helado después, si lo hago bien?","Trochu na kolene. Kúpiš mi potom zmrzlinu, ak sa mi to podarí?"],
 [["preg","¿De qué sabor lo quieres?","Akú príchuť chceš?"],["si","Trato hecho. Si das una vuelta entera al lago, helado.","Platí. Ak obídeš celé jazero, bude zmrzlina."],["hum","Lo haces bien o mal, helado igual. Pero no se lo digas a mamá.","Či to urobíš dobre alebo zle, zmrzlina bude tak či tak. Ale nehovor to mamine."],["lim","Helado sí, pero pequeño, que luego no cenas.","Zmrzlina áno, ale malá, inak potom nebudeš večerať."],["cari","Para mi campeón, helado de dos bolas.","Pre môjho šampióna zmrzlina s dvoma guľkami."],["breve","¡Hecho!","Platí!"]],
 ["¡De chocolate y fresa! Venga, abuelo, ¡que te echo una carrera hasta la puerta!","Čokoládovú a jahodovú! No tak, dedo, pretekajme sa k dverám!"]
]);
D("outings",["Ir a un museo","Ísť do múzea"],["Tu hija Laura","Tvoja dcéra Laura"],[
 ["El domingo la entrada al Prado es gratis por la tarde. ¿Te apetece ir?","V nedeľu poobede je vstup do Prada zadarmo. Máš chuť ísť?"],
 [["preg","¿No habrá muchísima gente si es gratis?","Nebude tam strašne veľa ľudí, keď je to zadarmo?"],["si","¡Me encantaría! Hace años que no voy.","Veľmi rada! Roky som tam nebola."],["duda","Me apetece, pero me canso mucho de estar de pie.","Mám chuť, ale veľmi sa unavím, keď dlho stojím."],["alt","Prefiero pagar e ir un día entre semana, con menos gente.","Radšej zaplatím a pôjdem cez týždeň, keď je menej ľudí."],["cari","Contigo, a donde sea.","S tebou kamkoľvek."],["breve","¡Sí, vamos!","Áno, poďme!"]],
 ["Habrá gente, sí. Pero podemos ir directamente a ver dos o tres salas, sin intentar verlo todo.","Ľudí bude veľa, áno. Ale môžeme ísť rovno pozrieť dve-tri sály a nesnažiť sa vidieť všetko."],
 [["opin","Yo quiero ver a Velázquez y las pinturas negras de Goya. Y luego, chocolate con churros.","Ja chcem vidieť Velázqueza a Goyove čierne maľby. A potom čokoládu s churros."],["si","Me parece perfecto. Así no acabamos agotadas.","To je výborné. Aspoň nebudeme úplne vyčerpané."],["preg","¿Qué salas te gustaría ver a ti?","Ktoré sály by si chcela vidieť ty?"],["cuenta","La última vez me impresionaron mucho las pinturas negras de Goya.","Minule ma veľmi zasiahli čierne maľby od Goyu."],["ofre","Llevo mi silla plegable, por si hay que esperar.","Vezmem si skladaciu stoličku, keby bolo treba čakať."],["hum","Perfecto. Y luego un chocolate con churros, que también es cultura.","Výborne. A potom čokoláda s churros, aj to je kultúra."]],
 ["Velázquez y Goya, entonces. Y después, chocolate con churros, ¡claro que sí!","Tak Velázquez a Goya. A potom čokoláda s churros, jasné, že áno!"],
 [["si","Perfecto. ¿Quedamos a las cuatro en la puerta de Goya? Los churros los pago yo.","Výborne. Stretneme sa o štvrtej pri Goyových dverách? Churros platím ja."],["cari","Qué ilusión. Gracias por pensar en mí.","Aká radosť. Vďaka, že si na mňa myslela."],["preg","¿Vamos en metro o en autobús?","Pôjdeme metrom alebo autobusom?"],["hum","Me pongo mis zapatos cómodos, los de abuela.","Obujem si pohodlné topánky, tie babkovské."],["ofre","Los churros los pago yo, que tú pagas siempre.","Churros platím ja, ty platíš vždy."],["breve","¡Hecho!","Platí!"]],
 ["A las cuatro en la puerta de Goya. ¡Y los churros los pagas tú, que no se diga!","O štvrtej pri Goyových dverách. A churros platíš ty, nech sa nepovie!"]
]);
D("outings",["El mercadillo","Bleší trh"],["Tu amiga Maribel","Tvoja kamarátka Maribel"],[
 ["¿Te vienes el domingo al Rastro? Quiero buscar una lámpara antigua.","Pôjdeš v nedeľu so mnou na Rastro? Chcem nájsť starú lampu."],
 [["preg","¿Qué tipo de lámpara buscas?","Akú lampu hľadáš?"],["si","¡Me encanta el Rastro! ¿A qué hora vamos?","Rastro zbožňujem! O koľkej pôjdeme?"],["duda","Uf, siempre hay muchísima gente... Pero bueno, vale.","Uf, vždy je tam strašne veľa ľudí... Ale dobre."],["hum","Vale, pero vigílame, que siempre compro cosas que no necesito.","Dobre, ale dávaj na mňa pozor, vždy kúpim veci, ktoré nepotrebujem."],["alt","El domingo no puedo. ¿Y el sábado a un mercado de antigüedades?","V nedeľu nemôžem. A čo v sobotu na trh so starožitnosťami?"],["breve","¡Claro!","Jasné!"]],
 ["Una de esas de bronce, con pantalla de cristal. Y conviene ir temprano, a las nueve.","Jednu z tých bronzových so skleneným tienidlom. A oplatí sa ísť skoro, o deviatej."],
 [["ofre","Yo sé regatear muy bien. Déjame a mí el precio.","Ja viem veľmi dobre zjednávať. Cenu nechaj na mňa."],["si","A las nueve, perfecto. Te recojo en tu portal.","O deviatej, výborne. Vyzdvihnem ťa pred vchodom."],["hum","¿A las nueve un domingo? Por una lámpara... vale, por ti.","O deviatej v nedeľu? Kvôli lampe... dobre, kvôli tebe."],["preg","¿Cuánto quieres gastarte, más o menos?","Koľko asi chceš minúť?"],["cuenta","Una vez encontré allí un reloj de cuco igual que el de mi abuela.","Raz som tam našla kukučkové hodiny presne ako mala moja stará mama."],["opin","Mejor llevar dinero en efectivo y una bolsa grande.","Lepšie zobrať hotovosť a veľkú tašku."]],
 ["¡Lo de regatear me viene genial, que yo soy fatal! ¿Y después desayunamos por allí?","To so zjednávaním sa mi hodí, ja som v tom hrozná! A potom sa tam niekde naraňajkujeme?"],
 [["preg","¿Vamos en metro? Aparcar allí es imposible.","Pôjdeme metrom? Zaparkovať tam je nemožné."],["si","Por supuesto. Conozco un bar con unas tostadas buenísimas.","Samozrejme. Poznám bar s výbornými hriankami."],["hum","Primero la lámpara, después el desayuno. Hay que ganárselo.","Najprv lampa, potom raňajky. Treba si ich zaslúžiť."],["alt","Mejor desayunamos antes, que con hambre regateo peor.","Radšej sa naraňajkujme predtým, s hladom zjednávam horšie."],["cari","Un domingo contigo, lámpara y desayuno: plan perfecto.","Nedeľa s tebou, lampa a raňajky: dokonalý plán."],["breve","¡Hecho!","Platí!"]],
 ["En metro, sin duda. ¡Hasta el domingo, compañera de regateos!","Metrom, bezpochyby. Do nedele, parťáčka na zjednávanie!"]
]);
D("outings",["Una tarde de lluvia","Daždivé popoludnie"],["Tu nieta Lucía","Tvoja vnučka Lucía"],[
 ["Iba a llevarte a dar una vuelta, pero está diluviando. ¿Qué hacemos?","Chcela som ťa vziať na prechádzku, ale leje ako z krhly. Čo budeme robiť?"],
 [["ofre","Te enseño a hacer las galletas de mi abuela.","Naučím ťa piecť sušienky mojej starej mamy."],["alt","¿Y si jugamos a las cartas y hacemos chocolate caliente?","A čo keby sme hrali karty a urobili horúcu čokoládu?"],["preg","¿Te apetece ver una película juntas?","Máš chuť pozrieť si spolu film?"],["hum","Bailar bajo la lluvia, como en las películas. Es broma.","Tancovať v daždi ako vo filmoch. Žartujem."],["cari","Lo que sea, pero contigo. Eso es lo importante.","Čokoľvek, ale s tebou. To je dôležité."],["duda","No sé... ¿Tú qué prefieres?","Neviem... Čo by si chcela ty?"]],
 ["¡Lo de las galletas me encanta! Pero ¿tienes todo lo que hace falta?","Tie sušienky sú super nápad! Ale máš všetko, čo treba?"],
 [["expl","Son «medovníky», galletas de miel. Las hacíamos en Navidad.","Sú to medovníky, medové sušienky. Robievali sme ich na Vianoce."],["si","Sí: harina, mantequilla, miel y canela. Todo en el armario.","Áno: múku, maslo, med a škoricu. Všetko je v skrini."],["duda","Creo que falta la mantequilla. ¿Bajas un momento a la tienda?","Myslím, že chýba maslo. Zbehneš na chvíľu do obchodu?"],["hum","Tengo todo menos paciencia. Esa la pones tú.","Mám všetko okrem trpezlivosti. Tú dodáš ty."],["preg","¿Tienes moldes en casa, o los hacemos con un vaso?","Máš doma formičky, alebo ich urobíme pohárom?"],["breve","¡Todo listo!","Všetko je pripravené!"]],
 ["¡Medovníky! Qué nombre tan bonito. ¿Me enseñas también a decorarlas?","Medovníky! Aké pekné meno. Naučíš ma ich aj zdobiť?"],
 [["si","Claro. Con azúcar glas y clara de huevo hacemos dibujos blancos.","Jasné. Z práškového cukru a bielka urobíme biele ozdoby."],["cari","Me encanta que te interesen nuestras tradiciones.","Veľmi ma teší, že ťa zaujímajú naše tradície."],["hum","Sí, aunque las mías parecen dibujadas por un gato.","Áno, aj keď moje vyzerajú, akoby ich kreslila mačka."],["recu","Mi madre hacía estrellas, corazones y casitas. Las colgábamos en el árbol.","Moja mama robila hviezdičky, srdiečka a domčeky. Vešali sme ich na stromček."],["ofre","Y te llevas una caja para tus amigas.","A vezmeš si krabičku pre kamarátky."],["breve","¡Por supuesto!","Samozrejme!"]],
 ["¡Me encanta este plan! La lluvia nos ha hecho un favor, al final.","Tento plán sa mi páči! Nakoniec nám dážď urobil láskavosť."]
]);
D("outings",["Una excursión en coche","Výlet autom"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["Mañana vamos a Segovia en coche. ¿Os venís? Salimos a las nueve.","Zajtra ideme autom do Segovie. Pôjdete s nami? Vyrážame o deviatej."],
 [["duda","Me apetece, pero me mareo en las curvas. ¿Cuánto se tarda?","Mám chuť, ale v zákrutách mi býva zle. Ako dlho sa ide?"],["si","¡Sí! Nunca hemos visto el acueducto.","Áno! Ešte sme nikdy nevideli akvadukt."],["preg","¿Cuánto se tarda en coche?","Ako dlho to trvá autom?"],["alt","Nosotros vamos en tren y nos vemos allí.","My pôjdeme vlakom a stretneme sa tam."],["hum","¿A las nueve? Yo a esa hora solo sé desayunar.","O deviatej? Ja v tú hodinu viem len raňajkovať."],["cari","Qué ilusión. Gracias por invitarnos.","Aká radosť. Vďaka za pozvanie."]],
 ["Una hora y poco. Y no hay muchas curvas, tranquila. Te pongo delante.","Niečo vyše hodiny. A nie je tam veľa zákrut, neboj. Posadím ťa dopredu."],
 [["preg","¿Qué vamos a ver además del acueducto? Dicen que el cochinillo de allí es famoso.","Čo uvidíme okrem akvaduktu? Vraj je tamojšie pečené prasiatko slávne."],["grac","Gracias, hijo. Así seguro que voy bien.","Ďakujem, synček. Tak určite budem v poriadku."],["ofre","Yo preparo unos bocadillos para el camino.","Ja pripravím sendviče na cestu."],["hum","Vale, pero la música la elijo yo.","Dobre, ale hudbu vyberám ja."],["cuenta","Me han dicho que el cochinillo de allí es famoso.","Vraj je tamojšie prasiatko známe."],["si","Perfecto. A las nueve estamos listos.","Výborne. O deviatej sme pripravení."]],
 ["El alcázar y la catedral. Y sí, comeremos cochinillo, ¡he reservado mesa!","Alcázar a katedrálu. A áno, budeme jesť prasiatko, rezervoval som stôl!"],
 [["preg","¿Hay que caminar mucho? Para ponerme los zapatos adecuados.","Bude sa treba veľa chodiť? Aby som si obula správne topánky."],["si","¡Qué bien organizado! Así da gusto.","Aké dobre zorganizované! Tak je radosť."],["hum","Con cochinillo, me levanto a las seis si hace falta.","Kvôli prasiatku vstanem aj o šiestej, ak treba."],["cari","Un día en familia y en un lugar tan bonito. Perfecto.","Deň s rodinou na takom krásnom mieste. Dokonalé."],["lim","Genial, pero después de comer necesitaré descansar un rato.","Super, ale po obede si budem musieť chvíľu oddýchnuť."],["breve","¡Qué buen plan!","Aký dobrý plán!"]],
 ["Lleva zapatos cómodos, que hay cuestas. ¡Mañana a las nueve en la puerta!","Obuj si pohodlné topánky, sú tam kopce. Zajtra o deviatej pred domom!"]
]);
D("travel",["En el aeropuerto","Na letisku"],["Tu yerno Andrés","Tvoj zať Andrés"],[
 ["Ya hemos facturado. Tenemos una hora hasta el embarque. ¿Tomamos algo?","Už sme odovzdali batožinu. Do nástupu máme hodinu. Dáme si niečo?"],
 [["preg","¿Dónde está nuestra puerta? ¿Está lejos?","Kde je naša brána? Je ďaleko?"],["si","Sí, un café me vendría muy bien.","Áno, káva by mi veľmi pomohla."],["alt","Prefiero ir primero a la puerta de embarque, por si acaso.","Radšej by som išla najprv k bráne, pre istotu."],["duda","No sé... Me pongo nerviosa en los aeropuertos.","Neviem... Na letiskách som nervózna."],["hum","Sí, pero aquí el café cuesta como un billete de avión.","Áno, ale káva tu stojí ako letenka."],["breve","Vale, un café rápido.","Dobre, rýchla káva."]],
 ["Está a diez minutos andando. Tranquila, tenemos tiempo de sobra. ¿Llevas el pasaporte a mano?","Je desať minút pešo. Pokojne, času máme dosť. Máš pas poruke?"],
 [["si","Sí, aquí en el bolso, con la tarjeta de embarque.","Áno, tu v kabelke, aj s palubným lístkom."],["duda","Creo que sí... ¡Ay, no! Espera, que lo busco.","Myslím, že áno... Joj, nie! Počkaj, pohľadám ho."],["preg","¿Hace falta el pasaporte o vale con el carné?","Treba pas, alebo stačí občiansky?"],["hum","Lo llevo tan a mano que lo he revisado veinte veces.","Mám ho tak poruke, že som ho skontrolovala dvadsaťkrát."],["grac","Sí. Gracias por estar pendiente de todo.","Áno. Ďakujem, že na všetko dávaš pozor."],["breve","Sí, todo listo.","Áno, všetko pripravené."]],
 ["Perfecto. Oye, ¿te importa si me siento yo en la ventanilla? Me encanta ver el despegue.","Výborne. Počuj, vadilo by ti, keby som si sadol k oknu? Rád sledujem vzlet."],
 [["alt","Vale, pero a la vuelta me la dejas a mí.","Dobre, ale cestou späť ho prenecháš mne."],["si","Al contrario. Yo prefiero el pasillo, para estirar las piernas.","Naopak. Ja mám radšej uličku, aby som si mohla natiahnuť nohy."],["no","Uy, pues a mí también me gusta la ventanilla. ¿Nos la turnamos?","Joj, aj ja mám rada okno. Vystriedame sa?"],["hum","Toda tuya. Yo durante el despegue cierro los ojos y rezo.","Je celé tvoje. Ja počas vzletu zatváram oči a modlím sa."],["cari","Claro, cariño. Así me cuentas lo que ves.","Jasné, zlatko. Aspoň mi povieš, čo vidíš."],["breve","Claro, sin problema.","Jasné, bez problémov."]],
 ["¡Trato hecho! A la vuelta, la ventanilla es tuya. Venga, vamos a por ese café.","Platí! Cestou späť je okno tvoje. Tak poďme na tú kávu."]
]);
D("travel",["Perdidos en una ciudad nueva","Stratení v novom meste"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["Creo que nos hemos perdido. El hotel debería estar por aquí, pero no lo veo.","Myslím, že sme zablúdili. Hotel by mal byť niekde tu, ale nevidím ho."],
 [["breve","¿Preguntamos?","Spýtame sa?"],["alt","Preguntemos a alguien. Esa señora parece de aquí.","Spýtajme sa niekoho. Tá pani vyzerá, že je odtiaľto."],["preg","¿Has mirado el mapa del móvil?","Pozrel si sa na mapu v mobile?"],["hum","No nos hemos perdido; estamos conociendo la ciudad.","Nestratili sme sa; spoznávame mesto."],["duda","Uf, y está empezando a anochecer...","Uf, a začína sa stmievať..."],["apoyo","Tranquilo, no tenemos prisa. Lo encontraremos.","Pokojne, nikam sa neponáhľame. Nájdeme ho."]],
 ["Ya pregunto yo. Perdone, ¿sabe dónde está el Hotel Las Rosas? ... Dice que está en la calle de atrás.","Spýtam sa ja. Prepáčte, neviete, kde je hotel Las Rosas? ... Hovorí, že je na vedľajšej ulici."],
 [["hum","¿En la calle de atrás? Hemos dado tres vueltas a la manzana.","Na vedľajšej ulici? Trikrát sme obišli celý blok."],["grac","¡Qué amable! Dale las gracias de mi parte.","Aká milá! Poďakuj jej aj odo mňa."],["si","Perfecto. Vamos, que estoy cansada.","Výborne. Poďme, som unavená."],["opin","La próxima vez apuntamos la dirección en papel, por si falla el móvil.","Nabudúce si adresu napíšeme na papier, keby mobil zlyhal."],["cari","Menos mal que estás tú para preguntar.","Ešte šťastie, že si tu ty, aby si sa spýtal."],["breve","¡Por fin!","Konečne!"]],
 ["¡Ahí está! Bueno, al menos hemos visto tres veces la misma panadería.","Tam je! No, aspoň sme trikrát videli tú istú pekáreň."],
 [["hum","Y mañana desayunamos allí, que ya somos clientes habituales.","A zajtra sa tam naraňajkujeme, už sme stáli zákazníci."],["si","Tiene muy buena pinta. Mañana vamos.","Vyzerá veľmi dobre. Zajtra pôjdeme."],["cari","Contigo, perderse también tiene su gracia.","S tebou má aj blúdenie svoje čaro."],["opin","Así conocemos los rincones que no salen en las guías.","Tak spoznávame zákutia, ktoré nie sú v sprievodcoch."],["lim","Muy bonito, pero ahora necesito una ducha y una cama.","Veľmi pekné, ale teraz potrebujem sprchu a posteľ."],["breve","¡Qué aventura!","Aké dobrodružstvo!"]],
 ["Ja, ja. ¡Mañana desayuno en nuestra panadería! Venga, vamos a descansar.","Ha-ha. Zajtra raňajky v našej pekárni! Tak poďme odpočívať."]
]);
D("travel",["Un problema con el equipaje","Problém s batožinou"],["Tu hija Laura, en el aeropuerto","Tvoja dcéra Laura na letisku"],[
 ["Mamá, tu maleta no ha salido. Llevamos veinte minutos esperando en la cinta.","Mami, tvoj kufor nevyšiel. Už dvadsať minút čakáme pri páse."],
 [["preg","¿Y ahora qué hacemos? ¿A dónde tenemos que ir?","A čo teraz? Kam musíme ísť?"],["duda","¡Ay, no! Ahí llevo todas mis medicinas.","Joj, nie! Mám v ňom všetky lieky."],["apoyo","Bueno, tranquilas. Seguro que tiene solución.","No, pokojne. Určite sa to dá vyriešiť."],["hum","Habrá decidido quedarse de vacaciones en Bratislava.","Asi sa rozhodol zostať na dovolenke v Bratislave."],["cari","Menos mal que estás conmigo, hija.","Ešte šťastie, že si so mnou, dcérka."],["breve","¡Qué faena!","To je nepríjemné!"]],
 ["Hay que ir al mostrador de equipajes perdidos. ¿Llevabas algo importante?","Treba ísť k prepážke so stratenou batožinou. Mala si v ňom niečo dôležité?"],
 [["breve","Ropa y algunos regalos.","Oblečenie a nejaké darčeky."],["expl","Las medicinas de la tensión y la ropa de toda la semana.","Lieky na tlak a oblečenie na celý týždeň."],["si","Por suerte, las pastillas las llevo en el bolso.","Našťastie tabletky mám v kabelke."],["cuenta","Los regalos para los niños. ¡Qué pena!","Darčeky pre deti. To je škoda!"],["preg","¿Tú crees que la encontrarán pronto?","Myslíš, že ho čoskoro nájdu?"],["hum","Lo más importante era mi pijama favorito. ¡Una tragedia!","Najdôležitejšie bolo moje obľúbené pyžamo. Tragédia!"]],
 ["Dicen que la traerán a casa mañana. Mientras tanto, te dejo ropa mía, ¿vale?","Vraj ho zajtra prinesú domov. Zatiaľ ti požičiam svoje oblečenie, dobre?"],
 [["preg","¿Te han dado algún número para llamar? Y si no llega, mañana vamos de compras.","Dali ti nejaké číslo, kam volať? A ak nepríde, zajtra ideme nakupovať."],["grac","Gracias, hija. Me salvas la vida.","Ďakujem, dcérka. Zachraňuješ mi život."],["hum","Vale, pero tu ropa me queda como a una adolescente.","Dobre, ale tvoje oblečenie mi pristane ako tínedžerke."],["si","Perfecto. Y si no llega, mañana vamos de compras.","Výborne. A ak nepríde, zajtra pôjdeme nakupovať."],["cari","Lo importante es que estamos juntas. La maleta ya aparecerá.","Dôležité je, že sme spolu. Kufor sa nájde."],["breve","Vale, gracias.","Dobre, ďakujem."]],
 ["Sí, tengo el número y la referencia. ¡Y si no llega, plan de compras, que me apetece!","Áno, mám číslo aj referenciu. A ak nepríde, ideme nakupovať, mám chuť!"]
]);
D("travel",["Elegir destino","Vybrať cieľ cesty"],["Tu marido Pedro","Tvoj manžel Pedro"],[
 ["Este otoño podríamos hacer un viaje los dos solos. ¿Adónde te gustaría ir?","Túto jeseň by sme mohli ísť na výlet len my dvaja. Kam by si chcela ísť?"],
 [["recu","¿Y si volvemos a Praga, donde fuimos de luna de miel?","A čo keby sme sa vrátili do Prahy, kam sme išli na svadobnú cestu?"],["opin","Me encantaría conocer Portugal. Dicen que Oporto es precioso.","Rada by som spoznala Portugalsko. Vraj je Porto nádherné."],["preg","¿Algo cerca o lejos? ¿Cuántos días?","Niečo blízko alebo ďaleko? Na koľko dní?"],["cari","A cualquier sitio contigo. Es lo que importa.","Kamkoľvek s tebou. To je dôležité."],["hum","A un sitio con playa, sol y sin nietos. Es broma... más o menos.","Niekam s plážou, slnkom a bez vnúčat. Žartujem... viac-menej."],["duda","No sé... Tú decides mejor estas cosas.","Neviem... Ty sa v takých veciach rozhoduješ lepšie."]],
 ["¡Praga! Qué buena idea. Hace cuarenta años... ¿Crees que habrá cambiado mucho?","Praha! Aký dobrý nápad. Pred štyridsiatimi rokmi... Myslíš, že sa veľmi zmenila?"],
 [["preg","¿Vamos en tren, como aquella vez? Y quiero buscar aquel hotel pequeño junto al río.","Pôjdeme vlakom, ako vtedy? A chcem nájsť ten malý hotel pri rieke."],["opin","Seguro que sí, pero el puente de Carlos seguirá igual.","Určite áno, ale Karlov most bude rovnaký."],["recu","¿Te acuerdas del hotel pequeño junto al río? Quiero buscarlo.","Pamätáš na ten malý hotel pri rieke? Chcem ho nájsť."],["hum","Ella habrá cambiado; nosotros, desde luego.","Ona sa zmenila; my určite."],["cari","Lo que no ha cambiado es lo que siento por ti.","Čo sa nezmenilo, je to, čo k tebe cítim."],["breve","¡Seguro que sí!","Určite áno!"]],
 ["En tren, como entonces. Y buscamos el hotel. ¿Lo reservo para octubre?","Vlakom, ako vtedy. A pohľadáme ten hotel. Mám rezervovať na október?"],
 [["si","¡Sí! Reserva para la segunda semana de octubre.","Áno! Rezervuj na druhý októbrový týždeň."],["cari","Me has hecho muy feliz con esta idea.","Týmto nápadom si ma veľmi potešil."],["preg","¿Y los gatos? ¿Quién se queda con ellos?","A mačky? Kto bude s nimi?"],["hum","Sí, pero esta vez yo elijo el restaurante. La otra vez cenamos fatal.","Áno, ale tentoraz vyberám reštauráciu ja. Minule sme večerali hrozne."],["lim","Sí, pero cinco días como mucho, que luego echo de menos a los niños.","Áno, ale najviac päť dní, potom mi chýbajú deti."],["breve","¡Resérvalo!","Rezervuj!"]],
 ["Reservado mentalmente. Mañana miro billetes. ¡Nuestra segunda luna de miel!","V duchu rezervované. Zajtra pozriem lístky. Naša druhá svadobná cesta!"]
]);
D("travel",["Visitar Eslovaquia","Návšteva Slovenska"],["Tu nieto Hugo","Tvoj vnuk Hugo"],[
 ["Abuela, este verano vamos a Eslovaquia contigo, ¿verdad? ¿Qué vamos a hacer allí?","Babi, toto leto ideme s tebou na Slovensko, však? Čo tam budeme robiť?"],
 [["expl","Vamos a subir a las montañas, a los Tatras, y a bañarnos en un lago.","Pôjdeme do hôr, do Tatier, a budeme sa kúpať v jazere."],["cuenta","Vamos a visitar la casa donde yo crecí.","Navštívime dom, v ktorom som vyrastala."],["hum","Vamos a comer tantos halušky que vas a volver redondo.","Zjeme toľko halušiek, že sa vrátiš guľatý."],["cari","Te voy a enseñar todos mis lugares favoritos.","Ukážem ti všetky moje obľúbené miesta."],["preg","¿Tú qué te gustaría hacer?","Čo by si chcel robiť ty?"],["breve","¡Muchísimas cosas!","Strašne veľa vecí!"]],
 ["¿Hay osos en las montañas? Me lo ha dicho un amigo del cole.","Sú v horách medvede? Povedal mi to kamarát zo školy."],
 [["cuenta","Una vez vi uno de lejos, cuando tenía tu edad.","Raz som jedného videla z diaľky, keď som mala toľko rokov ako ty."],["si","Sí, hay osos, pero son tímidos y no se acercan a la gente.","Áno, sú tam medvede, ale sú plaché a k ľuďom sa nepribližujú."],["expl","Hay osos, pero vamos por caminos seguros, con guías.","Sú tam medvede, ale chodíme po bezpečných chodníkoch so sprievodcami."],["hum","Sí, y les encantan los niños que no se comen las verduras.","Áno, a zbožňujú deti, čo nejedia zeleninu."],["preg","¿Te daría miedo ver uno?","Bál by si sa, keby si nejakého videl?"],["breve","Sí, pero lejos.","Áno, ale ďaleko."]],
 ["¡Qué guay! ¿Me enseñarás a decir algo en eslovaco antes de ir?","Super! Naučíš ma pred cestou niečo povedať po slovensky?"],
 [["hum","Sí, y la primera palabra será «zmrzlina», que es «helado».","Áno, a prvé slovo bude „zmrzlina“, čo je „helado“."],["si","¡Claro! Empezamos hoy: «ahoj» significa «hola».","Jasné! Začneme dnes: „ahoj“ znamená „hola“."],["cari","Me hace muchísima ilusión que quieras aprender mi idioma.","Strašne ma teší, že sa chceš naučiť môj jazyk."],["expl","Te enseñaré a decir «gracias»: «ďakujem».","Naučím ťa povedať „gracias“: „ďakujem“."],["preg","¿Cuántas palabras quieres aprender antes del viaje?","Koľko slov sa chceš naučiť pred cestou?"],["breve","¡Por supuesto!","Samozrejme!"]],
 ["¡Zmrzlina! Esa me la aprendo seguro. ¡Ahoj, abuela!","Zmrzlina! Tú sa naučím určite. Ahoj, babi!"]
]);
D("calls",["Una videollamada","Videohovor"],["Tu nieta Lucía, desde Berlín","Tvoja vnučka Lucía z Berlína"],[
 ["¡Hola, abuela! ¿Me ves bien? Aquí la conexión va un poco lenta.","Ahoj, babi! Vidíš ma dobre? Tu je pripojenie trochu pomalé."],
 [["hum","Te veo, pero solo la frente. Baja un poco el móvil.","Vidím ťa, ale len čelo. Daj mobil trochu nižšie."],["si","Te veo muy bien, cariño. ¡Qué guapa estás!","Vidím ťa veľmi dobre, zlatko. Aká si pekná!"],["duda","Te veo, pero se te congela la cara a ratos.","Vidím ťa, ale chvíľami ti zamrzne tvár."],["expl","Te veo, pero no te oigo bien. ¿Puedes hablar más alto?","Vidím ťa, ale zle ťa počujem. Môžeš hovoriť hlasnejšie?"],["cari","¡Qué alegría verte! Te echo mucho de menos.","Aká radosť ťa vidieť! Veľmi mi chýbaš."],["breve","¡Sí, perfecto!","Áno, výborne!"]],
 ["¡Ja, ja! ¿Mejor así? Te enseño mi piso nuevo. Mira, esta es mi habitación.","Ha-ha! Lepšie takto? Ukážem ti môj nový byt. Pozri, toto je moja izba."],
 [["preg","¿Y con quién compartes el piso? Te veo con jersey; ¿hace frío ahí?","A s kým bývaš v byte? Vidím ťa vo svetri; je tam zima?"],["cari","¡Qué bonita! Y qué luminosa.","Aká pekná! A aká svetlá."],["opin","Es pequeña, pero muy acogedora.","Je malá, ale veľmi útulná."],["hum","Muy bonita. Ya veo que la cama la haces igual que en casa: nunca.","Veľmi pekná. Vidím, že posteľ si ustieľaš rovnako ako doma: nikdy."],["preg","¿Hace mucho frío ahí? Te veo con jersey.","Je tam veľká zima? Vidím ťa vo svetri."],["breve","¡Preciosa!","Nádherná!"]],
 ["Con dos chicas: una de Italia y otra de Polonia. Y sí, aquí ya hace frío. Oye, ¿qué tal estáis vosotros?","S dvoma dievčatami: jedna je z Talianska a druhá z Poľska. A áno, už je tu zima. Počuj, a ako sa máte vy?"],
 [["preg","Bien. ¿Y tú comes bien? ¿Te haces la comida?","Dobre. A ty dobre ješ? Varíš si?"],["cuenta","Muy bien. El abuelo ha empezado clases de guitarra.","Veľmi dobre. Dedko začal chodiť na hodiny gitary."],["si","Bien, todos bien. Y con ganas de verte en Navidad.","Dobre, všetci dobre. A tešíme sa na teba na Vianoce."],["hum","Bien, aunque la casa está demasiado tranquila sin ti.","Dobre, aj keď bez teba je dom až príliš tichý."],["cari","Bien, pero contando los días para que vengas.","Dobre, ale počítame dni, kým prídeš."],["breve","Muy bien, cariño.","Veľmi dobre, zlatko."]],
 ["¡Sí, abuela, como bien! Bueno, a veces pizza. ¡Te llamo el domingo otra vez!","Áno, babi, jem dobre! No, niekedy pizzu. V nedeľu ti zase zavolám!"]
]);
D("calls",["Un mensaje confuso","Nejasná správa"],["Tu hijo Javier, por mensaje","Tvoj syn Javier, správou"],[
 ["«Mamá, llámame cuando puedas. No es urgente.»","„Mami, zavolaj mi, keď budeš môcť. Nie je to naliehavé.“"],
 [["preg","Hola, hijo. ¿Ha pasado algo? Me has asustado un poco.","Ahoj, synček. Stalo sa niečo? Trochu si ma vyľakal."],["si","Ahora mismo te llamo.","Hneď ti zavolám."],["alt","Estoy en el médico. Te llamo en una hora, ¿vale?","Som u lekára. Zavolám ti o hodinu, dobre?"],["hum","«No es urgente» es lo más urgente que existe. Te llamo ya.","„Nie je to naliehavé“ je to najnaliehavejšie, čo existuje. Volám ti hneď."],["duda","¿Seguro que no es urgente? Te llamo en cinco minutos.","Si si istý, že to nie je naliehavé? Zavolám ti o päť minút."],["breve","Te llamo enseguida.","Hneď ti zavolám."]],
 ["Nada malo, tranquila. Es que Sofía y yo queremos preguntaros algo, pero mejor por teléfono.","Nič zlé, pokojne. Len sa vás so Sofiou chceme na niečo spýtať, ale radšej telefonicky."],
 [["lim","Vale, pero la próxima vez no me escribas así, que me preocupo.","Dobre, ale nabudúce mi takto nepíš, robím si starosti."],["preg","Ahora me tienes en ascuas. ¿Es algo bueno?","Teraz ma necháš v napätí. Je to niečo dobré?"],["si","Vale. Te llamo esta tarde, cuando esté papá también.","Dobre. Zavolám ti poobede, keď bude doma aj otec."],["hum","¡Ay! ¿No me digas que vais a tener otro niño?","Joj! Nehovor mi, že budete mať ďalšie dieťa?"],["cari","Qué misterio. Bueno, mientras sea bueno, espero.","Aké tajomstvo. No, pokiaľ je to dobré, počkám."],["breve","Vale, luego hablamos.","Dobre, potom sa porozprávame."]],
 ["Ja, ja. Perdona. Es algo bueno. Te llamo a las siete y os lo cuento a los dos.","Ha-ha. Prepáč. Je to niečo dobré. Zavolám vám o siedmej a poviem vám to obom."],
 [["preg","¿Ni una pista? ¿Aunque sea pequeña?","Ani náznak? Aspoň malý?"],["si","Perfecto. A las siete estamos los dos al lado del teléfono.","Výborne. O siedmej budeme obaja pri telefóne."],["hum","Vale. Hasta las siete, me como las uñas.","Dobre. Do siedmej si budem obhrýzať nechty."],["cari","Me alegro de que sea bueno. Un beso, hijo.","Teším sa, že je to niečo dobré. Pusa, synček."],["form","De acuerdo. Esperamos tu llamada.","Dobre. Čakáme na tvoj telefonát."],["breve","¡Hasta luego!","Zatiaľ!"]],
 ["Ni una pista. Solo te digo que necesitaréis la maleta. ¡A las siete!","Ani náznak. Len ti poviem, že budete potrebovať kufor. O siedmej!"]
]);
D("calls",["Llamar a una tienda","Volať do obchodu"],["Una dependienta, por teléfono","Predavačka, telefonicky"],[
 ["Muebles Sánchez, buenos días. ¿En qué puedo ayudarle?","Nábytok Sánchez, dobrý deň. Ako vám môžem pomôcť?"],
 [["disc","Buenos días, perdone. Hablo despacio, que mi español no es perfecto.","Dobrý deň, prepáčte. Hovorím pomaly, moja španielčina nie je dokonalá."],["form","Buenos días. Llamo porque compré un sofá y todavía no me lo han traído.","Dobrý deň. Volám, lebo som kúpila pohovku a ešte mi ju nepriviezli."],["preg","Buenos días. ¿Podría hablar con el encargado, por favor?","Dobrý deň. Mohla by som hovoriť s vedúcim, prosím?"],["expl","Hola. Tenía una entrega prevista para hoy entre las nueve y las dos.","Dobrý deň. Dnes mi mali niečo doručiť medzi deviatou a druhou."],["breve","Buenos días. Es por un pedido.","Dobrý deň. Ide o objednávku."],["colo","Hola, buenas. Es por lo del sofá.","Dobrý deň. Volám kvôli tej pohovke."]],
 ["Claro, no se preocupe. ¿Me dice su número de pedido, por favor?","Jasné, nerobte si starosti. Poviete mi, prosím, číslo objednávky?"],
 [["duda","Un momento, que lo busco... Aquí está: cuatro, ocho, dos, siete, uno.","Moment, pohľadám ho... Tu je: štyri, osem, dva, sedem, jeden."],["expl","Sí, es el cuatro, ocho, dos, siete, uno.","Áno, je to štyri, osem, dva, sedem, jeden."],["preg","¿Dónde viene el número? ¿En el tique?","Kde je to číslo? Na bločku?"],["alt","No lo tengo a mano, pero el pedido está a nombre de Pedro Hudák.","Nemám ho poruke, ale objednávka je na meno Pedro Hudák."],["form","Por supuesto. Le doy también mi teléfono, por si acaso.","Samozrejme. Dám vám aj svoje telefónne číslo, pre istotu."],["breve","Cuatro, ocho, dos, siete, uno.","Štyri, osem, dva, sedem, jeden."]],
 ["Gracias. Veo que hubo un retraso en el almacén. Se lo podemos llevar mañana por la mañana. ¿Le va bien?","Ďakujem. Vidím, že v sklade nastalo meškanie. Môžeme vám ju priviezť zajtra ráno. Vyhovuje vám to?"],
 [["preg","¿Me pueden avisar media hora antes de llegar?","Môžete mi dať vedieť pol hodiny pred príchodom?"],["si","Sí, mañana por la mañana estoy en casa. Perfecto.","Áno, zajtra ráno som doma. Výborne."],["alt","Mañana no puedo. ¿Podría ser el jueves?","Zajtra nemôžem. Mohlo by to byť vo štvrtok?"],["lim","Bien, pero les pido que esta vez me avisen si hay algún cambio.","Dobre, ale prosím vás, aby ste mi tentoraz dali vedieť, ak bude nejaká zmena."],["grac","Muchas gracias por su ayuda. Muy amable.","Ďakujem pekne za pomoc. Veľmi milé."],["breve","Sí, me va bien.","Áno, vyhovuje."]],
 ["Perfecto. Le llamaremos media hora antes. Disculpe las molestias y que tenga un buen día.","Výborne. Zavoláme vám pol hodiny vopred. Prepáčte za nepríjemnosti a pekný deň."]
]);
D("calls",["No contesta","Nedvíha telefón"],["Tu hermana Rosa","Tvoja sestra Rosa"],[
 ["¿Has hablado con mamá hoy? La he llamado tres veces y no contesta.","Hovorila si dnes s mamou? Volala som jej trikrát a nedvíha."],
 [["preg","¿Has llamado al fijo también?","Volala si aj na pevnú linku?"],["duda","No, no he hablado con ella. Me estás preocupando.","Nie, nehovorila som s ňou. Začínam si robiť starosti."],["apoyo","Tranquila, seguro que se ha dejado el móvil en casa.","Pokojne, určite si nechala mobil doma."],["ofre","Llamo a la vecina, que tiene llaves.","Zavolám susede, má kľúče."],["hum","Estará en la peluquería. Allí no oye ni las campanas.","Asi je u kaderníčky. Tam nepočuje ani zvony."],["breve","No. ¿Llamo yo?","Nie. Mám zavolať ja?"]],
 ["Sí, al fijo también. Nada. Normalmente a esta hora está en casa.","Áno, aj na pevnú. Nič. Zvyčajne je v tento čas doma."],
 [["preg","¿Hoy no tenía la revisión del médico?","Nemala dnes kontrolu u lekára?"],["ofre","Llamo a la vecina ahora mismo y te digo algo.","Hneď zavolám susede a dám ti vedieť."],["opin","Si en media hora no sabemos nada, voy a su casa.","Ak o polhodinu nebudeme nič vedieť, pôjdem k nej domov."],["apoyo","No nos pongamos en lo peor. Seguro que hay una explicación.","Nemyslime hneď na najhoršie. Určite je na to vysvetlenie."],["cari","No te preocupes, hermana. Yo me encargo.","Neboj sa, sestra. Postarám sa o to."],["breve","Voy ahora mismo.","Hneď idem."]],
 ["¡Ah, es verdad! Tenía médico a las doce. No me acordaba.","Á, to je pravda! O dvanástej mala lekára. Nespomenula som si."],
 [["hum","¡Qué susto nos hemos dado por nada!","Aký strach sme mali zbytočne!"],["si","Seguro que es eso. En el médico siempre lo apaga.","Určite je to tým. U lekára ho vždy vypína."],["ofre","De todas formas, la llamo dentro de una hora para quedarme tranquila.","Aj tak jej o hodinu zavolám, aby som bola pokojná."],["opin","Deberíamos regalarle un móvil más sencillo, con el volumen alto.","Mali by sme jej darovať jednoduchší mobil s hlasným zvonením."],["cari","Menos mal. Me había asustado.","Ešte šťastie. Vyľakala som sa."],["breve","¡Qué alivio!","Aká úľava!"]],
 ["Sí, menudo susto. Seguro que ha apagado el móvil en la consulta. Cuando conteste, le decimos que nos avise antes de apagarlo.","Áno, to bol ale strach. Určite vypla mobil v ambulancii. Keď sa ozve, povieme jej, nech nám dá vedieť, skôr ako ho vypne."]
]);
D("calls",["Mensajes del grupo familiar","Správy v rodinnej skupine"],["Tu nieto Pablo","Tvoj vnuk Pablo"],[
 ["Abuela, ¿por qué has mandado al grupo de la familia veinte fotos de flores?","Babi, prečo si do rodinnej skupiny poslala dvadsať fotiek kvetov?"],
 [["disc","¡Ay! Quería mandarlas solo a tu tía. Me he equivocado.","Joj! Chcela som ich poslať len tvojej tete. Pomýlila som sa."],["hum","¡Porque son preciosas! Alguien tiene que alegraros el día.","Lebo sú nádherné! Niekto vám musí spríjemniť deň."],["preg","¿Tantas eran? Yo solo pulsé una vez.","Toľko ich bolo? Ja som klikla len raz."],["expl","Son de mi jardín. Quería que vierais cómo han crecido.","Sú z mojej záhrady. Chcela som, aby ste videli, ako vyrástli."],["duda","¿Veinte? No sé cómo ha pasado eso.","Dvadsať? Neviem, ako sa to stalo."],["breve","Para que las veáis.","Aby ste ich videli."]],
 ["Ja, ja. Son muy bonitas, pero se ha llenado el chat. ¿Quieres que te enseñe a mandarlas a una sola persona?","Ha-ha. Sú veľmi pekné, ale zaplnil sa chat. Chceš, aby som ťa naučil posielať ich len jednej osobe?"],
 [["breve","¡Sí, enséñame!","Áno, nauč ma!"],["si","Sí, por favor. Así no molesto a todo el mundo.","Áno, prosím. Tak nebudem otravovať všetkých."],["grac","Gracias, cariño. Tienes mucha paciencia conmigo.","Ďakujem, zlatko. Máš so mnou veľa trpezlivosti."],["hum","Vale, pero a ti te seguiré mandando flores.","Dobre, ale tebe budem kvety posielať aj naďalej."],["preg","¿Y cómo se borran las que ya he mandado?","A ako sa vymažú tie, čo som už poslala?"],["opin","Vale, pero creo que a tu madre le han gustado.","Dobre, ale myslím, že tvojej mame sa páčili."]],
 ["Mira: pulsas en el nombre de la persona, no en el grupo, y luego en el clip para elegir las fotos.","Pozri: klikneš na meno osoby, nie na skupinu, a potom na sponku, aby si vybrala fotky."],
 [["preg","¿Lo puedo probar ahora contigo, para ver si lo hago bien?","Môžem to teraz vyskúšať s tebou, či to robím dobre?"],["si","¡Ah, qué fácil! Lo apunto en mi libreta.","Aha, aké jednoduché! Zapíšem si to do zápisníka."],["duda","Espera, más despacio. ¿El clip es esto que parece una pinza?","Počkaj, pomalšie. Sponka je toto, čo vyzerá ako štipec?"],["hum","Fácil para ti, que naciste con el móvil en la mano.","Ľahké pre teba, narodil si sa s mobilom v ruke."],["grac","Muchas gracias. Eres mi profesor favorito.","Veľmi pekne ďakujem. Si môj obľúbený učiteľ."],["breve","¡Entendido!","Rozumiem!"]],
 ["¡Claro, pruébalo conmigo! Mándame una flor... solo una, ¿eh?","Jasné, vyskúšaj to so mnou! Pošli mi jeden kvet... len jeden, jasné?"]
]);
D("celebrations",["Un cumpleaños","Narodeniny"],["Tu hija Laura","Tvoja dcéra Laura"],[
 ["¡Feliz cumpleaños, mamá! ¡Setenta años! ¿Cómo te sientes?","Všetko najlepšie k narodeninám, mami! Sedemdesiatka! Ako sa cítiš?"],
 [["grac","¡Gracias, hija! Me siento muy querida.","Ďakujem, dcérka! Cítim sa veľmi milovaná."],["hum","Como de sesenta y nueve, pero con más velas.","Ako na šesťdesiatdeväť, len s viac sviečkami."],["cari","Feliz de tenerte a mi lado.","Šťastná, že ťa mám pri sebe."],["recu","Me acuerdo de cuando cumplí veinte. Parece ayer.","Pamätám si, keď som mala dvadsať. Akoby to bolo včera."],["duda","Un poco rara. Setenta suena a mucho.","Trochu zvláštne. Sedemdesiat znie ako veľa."],["breve","¡Muy bien!","Veľmi dobre!"]],
 ["Te hemos preparado una sorpresa para esta noche. Pero no te puedo decir nada más.","Na dnes večer sme ti pripravili prekvapenie. Ale nemôžem ti povedať nič viac."],
 [["preg","¿Tengo que arreglarme o puedo ir así?","Musím sa nastrojiť, alebo môžem ísť takto?"],["preg","¿Una sorpresa? ¿Qué es? ¡Dime algo!","Prekvapenie? Čo je to? Povedz mi niečo!"],["cari","No hacía falta nada. Con vosotros tengo de sobra.","Nič nebolo treba. S vami mám všetkého dosť."],["hum","Espero que no sea una fiesta con cien personas cantando.","Dúfam, že to nie je oslava so stovkou spievajúcich ľudí."],["lim","Vale, pero que no sea muy tarde, que me canso.","Dobre, ale nech to nie je príliš neskoro, unavím sa."],["si","¡Qué ilusión! Me encantan las sorpresas.","Aká radosť! Zbožňujem prekvapenia."]],
 ["Ponte guapa, que es especial. Pasamos a buscarte a las ocho.","Nastroj sa, je to niečo výnimočné. Prídeme po teba o ôsmej."],
 [["preg","¿Viene también tu hermano?","Príde aj tvoj brat?"],["si","A las ocho estaré lista y guapísima.","O ôsmej budem pripravená a nádherná."],["cari","Gracias por todo, hija. Eres un regalo.","Ďakujem za všetko, dcérka. Si dar."],["hum","Vale. Me pongo el vestido de la boda de tu prima.","Dobre. Oblečiem si šaty zo svadby tvojej sesternice."],["grac","Muchas gracias por preparar algo para mí.","Veľmi pekne ďakujem, že ste pre mňa niečo pripravili."],["breve","¡Allí estaré!","Budem pripravená!"]],
 ["¡Viene todo el mundo! Uy, ya he dicho demasiado. ¡A las ocho!","Prídu všetci! Joj, už som povedala priveľa. O ôsmej!"]
]);
D("celebrations",["Dar las gracias","Poďakovať"],["Tu vecina Encarna","Tvoja susedka Encarna"],[
 ["Hola, te he traído un poco de tarta. Es para daros las gracias por cuidar a mi gato.","Ahoj, priniesla som vám trochu torty. Je to poďakovanie, že ste sa starali o moju mačku."],
 [["preg","¡Qué buena pinta! ¿La has hecho tú?","Ako dobre vyzerá! Upiekla si ju sama?"],["grac","¡Qué detalle, Encarna! No tenías que molestarte.","To je od teba milé, Encarna! Nemusela si sa obťažovať."],["cari","Lo hicimos encantados. Tu gato es un amor.","Robili sme to radi. Tvoja mačka je zlatá."],["hum","Por esta tarta, cuido a tu gato todos los veranos.","Za túto tortu sa budem o tvoju mačku starať každé leto."],["form","Muchísimas gracias. Es usted muy amable.","Veľmi pekne ďakujem. Ste veľmi milá."],["breve","¡Gracias!","Ďakujem!"]],
 ["Sí, es la tarta de queso de mi madre. Espero que os guste. ¿Se portó bien Michi?","Áno, je to tvarohová torta podľa mojej mamy. Dúfam, že vám bude chutiť. Správal sa Michi dobre?"],
 [["preg","¿Y qué tal tu viaje? ¿Lo pasaste bien?","A aká bola tvoja cesta? Užila si si ju?"],["si","Muy bien. Solo se escondió debajo de la cama el primer día.","Veľmi dobre. Len prvý deň sa schoval pod posteľ."],["hum","Muy bien, aunque creo que ahora prefiere nuestro sofá.","Veľmi dobre, aj keď myslím, že teraz má radšej náš gauč."],["cuenta","Pedro le leía el periódico por las mañanas. Creo que le gustaba.","Pedro mu ráno čítal noviny. Myslím, že sa mu to páčilo."],["cari","Fue un placer. Nos hizo mucha compañía.","Bolo nám potešením. Robil nám veľkú spoločnosť."],["breve","Fenomenal.","Výborne."]],
 ["¡Precioso! Oye, ¿por qué no pasáis a merendar el sábado y os enseño las fotos?","Nádherne! Počuj, prečo by ste neprišli v sobotu na olovrant? Ukážem vám fotky."],
 [["hum","Con una condición: que haya más tarta de esta.","Pod jednou podmienkou: že bude viac tejto torty."],["si","¡Nos encantaría! ¿A qué hora?","Veľmi radi! O koľkej?"],["ofre","Encantados. Nosotros llevamos el café.","Radi. My prinesieme kávu."],["alt","El sábado no podemos. ¿Qué tal el domingo?","V sobotu nemôžeme. Čo tak v nedeľu?"],["cari","Qué buenos vecinos somos, ¿eh?","Akí sme dobrí susedia, však?"],["breve","¡Allí estaremos!","Prídeme!"]],
 ["¡Trato hecho! A las cinco, con tarta y fotos. ¡Y Michi también os espera!","Platí! O piatej, s tortou a fotkami. A aj Michi vás čaká!"]
]);
D("celebrations",["Unas bodas de oro","Zlatá svadba"],["Tu hijo Javier","Tvoj syn Javier"],[
 ["Papá, mamá, el mes que viene cumplís cincuenta años de casados. ¿Cómo queréis celebrarlo?","Oci, mami, budúci mesiac budete mať päťdesiat rokov od svadby. Ako to chcete osláviť?"],
 [["preg","¿Tú qué propones?","Čo navrhuješ ty?"],["cari","Con vosotros, en familia. Es lo único que queremos.","S vami, v rodine. To je jediné, čo chceme."],["opin","Algo sencillo. Una comida en casa con todos.","Niečo jednoduché. Obed doma so všetkými."],["hum","¿Cincuenta? ¡Cómo pasa el tiempo cuando te aguantas!","Päťdesiat? Ako ten čas letí, keď sa znášate!"],["duda","No sé... No nos gustan mucho las fiestas grandes.","Neviem... Veľké oslavy nemáme veľmi radi."],["recu","Cincuenta años... Me acuerdo del día de la boda como si fuera ayer.","Päťdesiat rokov... Na deň svadby si spomínam, akoby to bolo včera."]],
 ["Habíamos pensado en reservar un restaurante e invitar a la familia de Eslovaquia también.","Mysleli sme, že zarezervujeme reštauráciu a pozveme aj rodinu zo Slovenska."],
 [["preg","¿Y quién organiza todo eso? Es mucho trabajo.","A kto to všetko zorganizuje? Je to veľa práce."],["cari","¿De Eslovaquia? ¡Sería un sueño tenerlos aquí!","Zo Slovenska? Bol by to sen mať ich tu!"],["duda","Es mucho dinero para ellos el viaje. No sé si podrán.","Cesta je pre nich veľa peňazí. Neviem, či budú môcť."],["ofre","Si vienen, pueden quedarse en nuestra casa.","Ak prídu, môžu bývať u nás."],["lim","Restaurante sí, pero nada de discursos largos, ¿eh?","Reštaurácia áno, ale žiadne dlhé prejavy, jasné?"],["grac","Gracias, hijo. Es un detalle precioso.","Ďakujem, synček. Je to krásna pozornosť."]],
 ["Lo organizamos Laura y yo. Vosotros solo tenéis que venir y disfrutar. ¿Os parece?","Zorganizujeme to s Laurou. Vy musíte len prísť a užívať si. Čo poviete?"],
 [["recu","Y que pongan la canción de nuestra boda, por favor.","A nech zahrajú pieseň z našej svadby, prosím."],["si","Nos parece maravilloso. Gracias a los dos.","Je to nádherné. Ďakujeme vám obom."],["cari","No sabes la ilusión que nos hace. Nos has emocionado.","Ani nevieš, akú nám to robí radosť. Dojal si nás."],["hum","Perfecto. Yo me encargo de bailar con tu madre.","Výborne. Ja sa postarám o tanec s tvojou mamou."],["ofre","Al menos dejadnos elegir el menú.","Aspoň nám nechajte vybrať menu."],["breve","¡Nos encanta!","Zbožňujeme to!"]],
 ["¡La canción de la boda está apuntada! Vais a tener una fiesta inolvidable.","Pieseň zo svadby je zapísaná! Budete mať nezabudnuteľnú oslavu."]
]);
D("celebrations",["Felicitar un éxito","Zablahoželať k úspechu"],["Tu nuera Sofía","Tvoja nevesta Sofía"],[
 ["¡Ya es oficial! He terminado el doctorado. Hoy ha sido la defensa.","Už je to oficiálne! Dokončila som doktorát. Dnes bola obhajoba."],
 [["preg","¡Qué maravilla! ¿Qué te ha dicho el tribunal?","To je úžasné! Čo ti povedala komisia?"],["cari","¡Enhorabuena, Sofía! Estamos orgullosísimos de ti.","Blahoželám, Sofía! Sme na teba strašne hrdí."],["hum","¡Doctora en la familia! Ahora ya sé a quién preguntar cuando me duela algo.","Doktorka v rodine! Teraz už viem, koho sa pýtať, keď ma niečo bolí."],["anim","Te lo mereces. Has trabajado muchísimo.","Zaslúžiš si to. Strašne veľa si pracovala."],["form","Muchísimas felicidades. Es un logro enorme.","Srdečne blahoželám. Je to obrovský úspech."],["colo","¡Toma ya! ¡Eres una máquina!","No toto! Si mašina!"]],
 ["¡Gracias! Me han dado la nota máxima. Y eso que estaba temblando.","Ďakujem! Dostala som najvyššie hodnotenie. A to som sa triasla."],
 [["preg","¿Y ahora qué vas a hacer? Aparte de dormir una semana entera, claro.","A čo budeš robiť teraz? Okrem toho, že budeš týždeň spať, samozrejme."],["anim","¡Sobresaliente! Eso demuestra lo buena que eres.","Najvyššie hodnotenie! To ukazuje, aká si dobrá."],["cuenta","Yo también temblaba en mis exámenes, y eso que no eran un doctorado.","Aj ja som sa triasla na skúškach, a to nebol doktorát."],["cari","Temblar es normal. Lo importante es que lo has conseguido.","Triasť sa je normálne. Dôležité je, že si to dokázala."],["hum","Temblando y con nota máxima. ¡Imagínate si llegas a estar tranquila!","Trasúc sa a s najvyšším hodnotením. Predstav si, keby si bola pokojná!"],["breve","¡Qué orgullo!","Aká hrdosť!"]],
 ["Ja, ja. De momento, celebrarlo. ¿Venís a cenar el sábado? Invito yo.","Ha-ha. Zatiaľ to osláviť. Prídete v sobotu na večeru? Pozývam ja."],
 [["ofre","Vamos, y te llevo un regalo que tengo guardado para este momento.","Prídeme a donesiem ti darček, ktorý som si odložila na túto chvíľu."],["si","¡Por supuesto! Allí estaremos.","Samozrejme! Prídeme."],["alt","Vamos, pero el postre lo llevamos nosotros. Es tu día.","Prídeme, ale dezert donesieme my. Je to tvoj deň."],["no","De eso nada. Hoy invitamos nosotros, que es tu celebración.","To nie. Dnes pozývame my, je to tvoja oslava."],["cari","Encantados. Brindaremos por la doctora de la familia.","S radosťou. Pripijeme na doktorku v rodine."],["breve","¡Claro que sí!","Jasné, že áno!"]],
 ["¡Qué ilusión! El sábado a las nueve. ¡Y con regalo, ya no puedo esperar!","Aká radosť! V sobotu o deviatej. A s darčekom, už sa neviem dočkať!"]
]);
D("celebrations",["La Nochevieja","Silvester"],["Tu nieto Pablo","Tvoj vnuk Pablo"],[
 ["Abuelo, ¿tú sabes lo de las uvas? Hay que comerse doce con las campanadas.","Dedo, vieš o tých hroznách? Treba zjesť dvanásť pri odbíjaní zvonov."],
 [["cuenta","En Eslovaquia no comemos uvas; brindamos y comemos lentejas.","Na Slovensku hrozno nejeme; pripíjame si a jeme šošovicu."],["si","Sí, ya lo sé. Pero el año pasado me atraganté con la quinta.","Áno, viem. Ale minulý rok mi zabehlo pri piatej."],["preg","¿Doce? ¿Y si no te da tiempo?","Dvanásť? A čo ak to nestihneš?"],["hum","¿Doce uvas en doce segundos? Eso es un deporte olímpico.","Dvanásť hrozien za dvanásť sekúnd? To je olympijský šport."],["cari","Este año me las como contigo, a ver quién termina antes.","Tento rok ich zjem s tebou, uvidíme, kto skončí skôr."],["breve","¡Claro que lo sé!","Jasné, že viem!"]],
 ["¡Lentejas! ¿Y por qué coméis lentejas en Eslovaquia?","Šošovicu! A prečo na Slovensku jete šošovicu?"],
 [["preg","¿Quieres que este año comamos uvas y lentejas?","Chceš, aby sme tento rok jedli hrozno aj šošovicu?"],["expl","Porque se parecen a monedas. Dicen que traen dinero en el año nuevo.","Pretože sa podobajú na mince. Vraj prinášajú v novom roku peniaze."],["hum","Para tener dinero. Por lo visto, no funcionan muy bien.","Aby sme mali peniaze. Zjavne veľmi nefungujú."],["recu","Mi madre las hacía con salchicha y las comíamos al día siguiente.","Mama ich robila s klobásou a jedli sme ich na druhý deň."],["opin","Cada país tiene su tradición, y todas son bonitas.","Každá krajina má svoju tradíciu a všetky sú pekné."],["breve","Por la suerte y el dinero.","Pre šťastie a peniaze."]],
 ["¡Las dos cosas! Uvas a las doce y lentejas el día uno. ¡Doble suerte!","Obe! Hrozno o polnoci a šošovica prvého. Dvojité šťastie!"],
 [["preg","¿Me ayudas a pelar las uvas esa noche?","Pomôžeš mi v ten večer ošúpať hrozno?"],["si","¡Trato hecho! Doble tradición, doble suerte.","Platí! Dvojitá tradícia, dvojité šťastie."],["hum","Y yo pido uvas sin pepitas, que con mi dentadura no me arriesgo.","A ja chcem hrozno bez semienok, s mojimi zubami neriskujem."],["cari","Me encanta que mezclemos las dos culturas.","Páči sa mi, že miešame obe kultúry."],["ofre","Las lentejas las preparo yo, como las hacía mi madre.","Šošovicu pripravím ja, ako ju robila moja mama."],["breve","¡Perfecto!","Výborne!"]],
 ["¡Te ayudo! Y practicamos antes con uvas normales, por si acaso.","Pomôžem ti! A predtým si to nacvičíme s obyčajným hroznom, pre istotu."]
]);
D("younger",["La música de hoy","Dnešná hudba"],["Tu nieta Lucía","Tvoja vnučka Lucía"],[
 ["Abuela, escucha esta canción. ¿A que es buenísima?","Babi, vypočuj si túto pieseň. Je super, však?"],
 [["preg","¿Quién canta? ¿Es muy famoso?","Kto spieva? Je veľmi slávny?"],["opin","Tiene mucho ritmo, pero no entiendo nada de la letra.","Má veľa rytmu, ale textu vôbec nerozumiem."],["hum","Muy buena... para bailar con tapones en los oídos.","Veľmi dobrá... na tancovanie so štupľami v ušiach."],["cari","Si a ti te gusta, me gusta a mí también.","Ak sa páči tebe, páči sa aj mne."],["duda","Hmm... Es distinta a lo que yo escucho.","Hmm... Je iná, než čo počúvam ja."],["breve","¡Tiene marcha!","Má to šťavu!"]],
 ["Es una cantante española muy famosa. Habla de su abuela, por cierto.","Je to veľmi slávna španielska speváčka. Mimochodom, spieva o svojej babke."],
 [["preg","¿Y qué dice de su abuela?","A čo hovorí o svojej babke?"],["cari","¿De su abuela? ¡Ahora me gusta todavía más!","O svojej babke? Teraz sa mi páči ešte viac!"],["hum","Pues entonces es una canción muy inteligente.","Tak to je veľmi inteligentná pieseň."],["opin","Las mejores canciones hablan de la familia.","Najlepšie piesne sú o rodine."],["cuenta","En mi época también había canciones sobre las abuelas, pero más lentas.","Za mojich čias boli tiež piesne o babkách, ale pomalšie."],["breve","¡Qué bonito!","Aké pekné!"]],
 ["Dice que su abuela le enseñó a ser valiente. Ahora ponme tú una canción de tu época.","Hovorí, že ju babka naučila byť odvážnou. Teraz mi pusť ty pieseň zo svojej doby."],
 [["preg","¿La buscas tú en el móvil? Yo no sé.","Nájdeš ju v mobile ty? Ja neviem."],["si","¡Claro! Te pongo una que bailábamos en Eslovaquia los sábados.","Jasné! Pustím ti jednu, na ktorú sme v sobotu tancovali na Slovensku."],["hum","Vale, pero prepárate, que no tiene ni un solo ritmo electrónico.","Dobre, ale priprav sa, nemá ani jeden elektronický rytmus."],["cari","Qué bonito intercambio. Me encanta compartir esto contigo.","Aká pekná výmena. Rada sa s tebou o toto delím."],["recu","Te pongo la que sonaba cuando conocí a tu abuelo.","Pustím ti tú, ktorá hrala, keď som spoznala tvojho dedka."],["breve","¡Ahora mismo!","Hneď!"]],
 ["¡Búscala tú y te ayudo! A ver si esa sí la bailamos juntas.","Hľadaj ju ty a ja ti pomôžem! Uvidíme, či na ňu spolu zatancujeme."]
]);
D("younger",["Las redes sociales","Sociálne siete"],["Tu nieto Pablo, de quince años","Tvoj pätnásťročný vnuk Pablo"],[
 ["Abuela, ¿por qué no te haces una cuenta en Instagram? Así ves mis fotos.","Babi, prečo si nezaložíš účet na Instagrame? Tak by si videla moje fotky."],
 [["duda","No sé... Eso de las redes me da un poco de miedo.","Neviem... Tie siete ma trochu desia."],["preg","¿Y eso cómo funciona? ¿Es difícil?","A ako to funguje? Je to ťažké?"],["hum","¿Yo en Instagram? ¿Para subir fotos de mis croquetas?","Ja na Instagrame? Aby som zverejňovala fotky svojich krokiet?"],["si","Vale, ¿me ayudas a hacerla?","Dobre, pomôžeš mi ho založiť?"],["cari","Si es para ver tus fotos, me lo pienso.","Ak je to kvôli tvojim fotkám, porozmýšľam o tom."],["no","Prefiero que me enseñes las fotos tú, en persona.","Radšej mi fotky ukáž ty, osobne."]],
 ["Es muy fácil. Y puedes poner la cuenta en privado, para que solo te vea la familia.","Je to veľmi ľahké. A účet môžeš nastaviť ako súkromný, aby ťa videla len rodina."],
 [["hum","Vale. Pero si subo fotos de flores, no te quejes.","Dobre. Ale ak budem dávať fotky kvetov, nesťažuj sa."],["si","Ah, si es privada, entonces sí.","Aha, ak je súkromný, tak áno."],["preg","¿Y cómo sé que nadie más ve mis cosas?","A ako viem, že moje veci nikto iný nevidí?"],["opin","Me parece bien, pero no quiero pasarme el día mirando el móvil.","Súhlasím, ale nechcem celý deň pozerať do mobilu."],["lim","Vale, pero solo te sigo a ti y a tu hermana.","Dobre, ale budem sledovať len teba a tvoju sestru."],["breve","Bueno, probamos.","No, skúsime."]],
 ["¡Genial! Y si subes flores, te doy «me gusta», prometido. Dame tu móvil.","Super! A ak dáš kvety, dám ti „páči sa mi“, sľubujem. Daj mi mobil."],
 [["preg","¿Necesito una contraseña? ¿Cuál pongo?","Potrebujem heslo? Aké mám dať?"],["si","Toma. Pero explícamelo todo despacio.","Na. Ale vysvetli mi všetko pomaly."],["hum","Toma. Y elige una foto de perfil en la que salga guapa, por favor.","Na. A vyber profilovú fotku, na ktorej vyzerám pekne, prosím."],["grac","Gracias por tener tanta paciencia con tu abuela.","Ďakujem, že máš s babkou toľko trpezlivosti."],["cari","Me hace ilusión esto. Así estoy más cerca de vosotros.","Teším sa z toho. Tak budem bližšie k vám."],["breve","¡Aquí lo tienes!","Tu ho máš!"]],
 ["¡Una contraseña que solo sepas tú! Venga, empezamos. Primero, tu nombre.","Heslo, ktoré budeš vedieť len ty! Tak začneme. Najprv tvoje meno."]
]);
D("younger",["Un niño que no quiere dormir","Dieťa, ktoré nechce spať"],["Tu nieto Hugo, de seis años","Tvoj šesťročný vnuk Hugo"],[
 ["Abuelo, no tengo sueño. ¿Puedo quedarme un ratito más?","Dedo, nie som ospalý. Môžem zostať ešte chvíľočku hore?"],
 [["preg","¿Qué te pasa? ¿Estás preocupado por algo?","Čo sa deje? Trápi ťa niečo?"],["lim","Ya es muy tarde, campeón. Mañana tienes colegio.","Už je veľmi neskoro, šampión. Zajtra máš školu."],["alt","Vale, pero en la cama. Te leo un cuento.","Dobre, ale v posteli. Prečítam ti rozprávku."],["hum","¿No tienes sueño? Qué raro, porque bostezas como un león.","Nie si ospalý? To je čudné, lebo zívaš ako lev."],["cari","Cinco minutos, y luego a dormir, ¿vale?","Päť minút a potom spať, dobre?"],["breve","A la cama, pequeño.","Do postele, maličký."]],
 ["Es que tengo miedo de la oscuridad. Hay ruidos raros.","Bojím sa tmy. Sú tu čudné zvuky."],
 [["cuenta","Yo de pequeño también tenía miedo. Mi abuelo me cantaba una canción.","Aj ja som sa ako malý bál. Môj dedko mi spieval pesničku."],["cari","Ven, que me quedo contigo hasta que te duermas.","Poď, zostanem s tebou, kým nezaspíš."],["expl","Los ruidos son la nevera y el viento. No pasa nada.","Tie zvuky sú chladnička a vietor. Nič sa nedeje."],["ofre","Te dejo la lucecita del pasillo encendida.","Nechám ti rozsvietené svetielko na chodbe."],["hum","¿Ruidos? Seguro que es tu abuela roncando.","Zvuky? Určite je to tvoja babka, čo chrápe."],["preg","¿Qué ruidos oyes? Vamos a mirarlos juntos.","Aké zvuky počuješ? Poďme sa na ne pozrieť spolu."]],
 ["¿Me cantas la canción de tu abuelo? ¿Es en eslovaco?","Zaspievaš mi tú pesničku od svojho dedka? Je po slovensky?"],
 [["si","Sí, es en eslovaco. Cierra los ojos y escucha.","Áno, je po slovensky. Zavri oči a počúvaj."],["cari","Claro que sí. Es una canción sobre una estrella que cuida a los niños.","Jasné, že áno. Je to pesnička o hviezdičke, ktorá stráži deti."],["hum","Sí, pero te aviso: canto fatal. Te dormirás para no oírme.","Áno, ale upozorňujem ťa: spievam hrozne. Zaspíš, aby si ma nepočul."],["expl","Es una nana. Habla de un pájaro que vuelve a su nido.","Je to uspávanka. Je o vtáčikovi, ktorý sa vracia do hniezda."],["ofre","Te la canto, y mañana te enseño a cantarla tú.","Zaspievam ti ju a zajtra ťa naučím spievať ju aj teba."],["breve","Cierra los ojos.","Zavri oči."]],
 ["Vale... cierro los ojos. Pero no te vayas hasta que me duerma, ¿eh?","Dobre... zatváram oči. Ale neodchádzaj, kým nezaspím, dobre?"]
]);
D("younger",["Ayudar con los deberes","Pomoc s domácimi úlohami"],["Tu nieta Marta, de diez años","Tvoja desaťročná vnučka Marta"],[
 ["Abuela, ¿me ayudas con los deberes de lengua? No entiendo qué es un adjetivo.","Babi, pomôžeš mi s úlohami z jazyka? Nerozumiem, čo je prídavné meno."],
 [["preg","¿Qué te pide exactamente el ejercicio?","Čo presne od teba cvičenie chce?"],["expl","Un adjetivo es una palabra que dice cómo es algo: grande, rojo, bonito.","Prídavné meno je slovo, ktoré hovorí, aké niečo je: veľký, červený, pekný."],["si","¡Claro! Siéntate a mi lado y lo vemos juntas.","Jasné! Sadni si ku mne a pozrieme sa na to spolu."],["hum","¡Qué casualidad! Yo también estoy aprendiendo español.","Aká náhoda! Aj ja sa učím španielčinu."],["cari","Me encanta que me lo pidas a mí.","Som rada, že o to žiadaš práve mňa."],["breve","Claro, vamos a verlo.","Jasné, pozrime sa."]],
 ["Tengo que buscar adjetivos en esta frase: «El perro pequeño come una galleta dulce».","Mám nájsť prídavné mená v tejto vete: „Malý pes je sladkú sušienku.“"],
 [["preg","A ver, ¿cómo es el perro?","Pozrime sa, aký je ten pes?"],["expl","Pregúntate cómo son las cosas. El perro es... ¿cómo?","Pýtaj sa, aké sú veci. Pes je... aký?"],["hum","Esa frase me ha dado hambre. ¿Hay galletas dulces en casa?","Z tej vety som dostala hlad. Máme doma sladké sušienky?"],["anim","Tú puedes encontrarlos sola. Inténtalo primero.","Ty ich vieš nájsť sama. Najprv to skús."],["cuenta","En eslovaco también tenemos adjetivos, y son más difíciles.","V slovenčine máme tiež prídavné mená, a sú ťažšie."],["breve","Busca palabras que describan.","Hľadaj slová, ktoré opisujú."]],
 ["¡Pequeño! El perro es pequeño. Y la galleta es... ¡dulce! ¿Son esos?","Malý! Pes je malý. A sušienka je... sladká! Sú to tie?"],
 [["preg","Muy bien. ¿Te inventas tú una frase con dos adjetivos?","Výborne. Vymyslíš ty vetu s dvoma prídavnými menami?"],["si","¡Exacto! «Pequeño» y «dulce». ¡Muy bien!","Presne! „Malý“ a „sladký“. Výborne!"],["anim","¿Lo ves? Sabías hacerlo. Eres muy lista.","Vidíš? Vedela si to. Si veľmi múdra."],["hum","Perfecto. Y ahora, como premio, una galleta dulce de verdad.","Výborne. A teraz ako odmena naozajstná sladká sušienka."],["cari","¡Qué orgullosa estoy de ti!","Aká som na teba hrdá!"],["breve","¡Perfecto!","Výborne!"]],
 ["Mmm... «Mi abuela simpática hace croquetas riquísimas». ¡Dos adjetivos!","Hmm... „Moja milá babka robí výborné krokety.“ Dve prídavné mená!"]
]);
D("younger",["Un adolescente callado","Mlčanlivý tínedžer"],["Tu nieto Pablo","Tvoj vnuk Pablo"],[
 ["Hola, abuela. El instituto, bien. Como siempre.","Ahoj, babi. V škole dobre. Ako vždy."],
 [["hum","«Bien». Qué conversación tan apasionante. Me has dejado sin palabras.","„Dobre.“ Aký vzrušujúci rozhovor. Úplne si ma ohromil."],["preg","¿Solo «bien»? ¿Ha pasado algo interesante en el instituto?","Len „dobre“? Stalo sa v škole niečo zaujímavé?"],["cari","Vale, cariño. Si te apetece hablar luego, aquí estoy.","Dobre, zlatko. Ak budeš chcieť potom hovoriť, som tu."],["cuenta","Yo a tu edad también contestaba con una palabra.","Aj ja som v tvojom veku odpovedala jedným slovom."],["alt","¿Te apetece una merienda? A veces con hambre no se habla.","Dáš si olovrant? Niekedy sa s hladom nedá rozprávať."],["breve","Me alegro.","Teším sa."]],
 ["Ja, ja. Vale... Bueno, hay una chica en clase que me gusta. Pero no se lo digas a nadie.","Ha-ha. Dobre... No, v triede je dievča, ktoré sa mi páči. Ale nikomu to nehovor."],
 [["preg","¿Ah, sí? ¿Y cómo se llama?","Naozaj? A ako sa volá?"],["cari","Tu secreto está a salvo conmigo.","Tvoje tajomstvo je u mňa v bezpečí."],["hum","¡Ajá! Por eso estás tan callado últimamente.","Aha! Preto si v poslednom čase taký tichý."],["recu","Yo me enamoré por primera vez a tu edad. Se llamaba Jozef.","Ja som sa prvýkrát zaľúbila v tvojom veku. Volal sa Jozef."],["apoyo","Es normal estar nervioso. Es algo muy bonito.","Je normálne byť nervózny. Je to niečo veľmi pekné."],["breve","No diré nada.","Nič nepoviem."]],
 ["Se llama Elena. No sé cómo hablar con ella. Me pongo rojo.","Volá sa Elena. Neviem, ako sa s ňou rozprávať. Červenám sa."],
 [["cuenta","Tu abuelo tardó un mes en hablarme. ¡Y mira, cincuenta años juntos!","Tvojmu dedkovi trvalo mesiac, kým sa so mnou dal do reči. A pozri, päťdesiat rokov spolu!"],["opin","Pregúntale algo sencillo, de clase. Así empieza todo.","Spýtaj sa jej niečo jednoduché, zo školy. Tak sa všetko začína."],["cari","Ponerse rojo es bonito. Significa que te importa.","Červenať sa je pekné. Znamená to, že ti na nej záleží."],["hum","Rojo como un tomate. Igualito que tu abuelo.","Červený ako paradajka. Presne ako tvoj dedko."],["anim","Sé tú mismo. Eres un chico estupendo.","Buď sám sebou. Si skvelý chlapec."],["preg","¿Qué cosas le gustan a ella?","Čo má ona rada?"]],
 ["¿El abuelo tardó un mes? ¡Ja, ja! Vale, mañana le pregunto por los deberes de mates.","Dedkovi to trvalo mesiac? Ha-ha! Dobre, zajtra sa jej spýtam na úlohy z matiky."]
]);
D("farewells",["Despedirse después de una visita","Rozlúčka po návšteve"],["Tu hija Laura, en la puerta","Tvoja dcéra Laura pri dverách"],[
 ["Bueno, mamá, nos vamos ya. Gracias por la comida, estaba todo buenísimo.","Tak, mami, už ideme. Vďaka za obed, všetko bolo výborné."],
 [["ofre","Esperad, que os pongo un táper con las croquetas que han sobrado. ¿Y un café rápido?","Počkajte, dám vám do krabičky krokety, čo zostali. A rýchlu kávu?"],["cari","Gracias a vosotros por venir. Ha sido un día precioso.","Vďaka vám, že ste prišli. Bol to nádherný deň."],["preg","¿Ya os vais? ¿No os quedáis a tomar un café?","Už idete? Nezostanete na kávu?"],["hum","Ha sido un placer. La próxima vez fregáis vosotros.","Bolo mi potešením. Nabudúce umývate riad vy."],["grac","Me alegro de que os haya gustado. Volved pronto.","Teším sa, že vám chutilo. Príďte zas čoskoro."],["breve","¡Gracias por venir!","Vďaka, že ste prišli!"]],
 ["¡Las croquetas, sí, por favor! Y el café lo dejamos para la próxima, que los niños mañana madrugan.","Krokety áno, prosím! A kávu necháme nabudúce, deti zajtra skoro vstávajú."],
 [["preg","¿Cuándo volvemos a vernos?","Kedy sa znova uvidíme?"],["si","Claro. Aquí tienes las croquetas. Ponlas en la nevera.","Jasné. Tu máš krokety. Daj ich do chladničky."],["cari","Lo entiendo. Dales un beso de buenas noches de mi parte.","Chápem. Daj im odo mňa pusu na dobrú noc."],["ofre","¿Queréis que os acompañe hasta el coche?","Chcete, aby som vás odprevadila k autu?"],["hum","Croquetas para mañana. Así la abuela sigue presente.","Krokety na zajtra. Aby bola babka stále prítomná."],["breve","Muy bien.","Dobre."]],
 ["Nos vemos el domingo que viene, si os va bien. ¡Avisadnos cuando os acostéis!","Uvidíme sa budúcu nedeľu, ak vám to vyhovuje. Dajte vedieť, keď pôjdete spať!"],
 [["si","El domingo, perfecto. Y avisadnos vosotros al llegar a casa.","Nedeľa je výborná. A vy nám dajte vedieť, keď prídete domov."],["cari","Conducid con cuidado. Os quiero mucho.","Šoférujte opatrne. Veľmi vás ľúbim."],["hum","¿Avisaros cuando nos acostemos? Si a las diez ya estamos dormidos.","Dať vám vedieť, keď pôjdeme spať? Veď o desiatej už spíme."],["lim","El domingo sí, pero que sea a comer, no a cenar.","V nedeľu áno, ale nech je to na obed, nie na večeru."],["grac","Gracias por todo, hija. Hasta el domingo.","Vďaka za všetko, dcérka. Do nedele."],["breve","¡Hasta el domingo!","Do nedele!"]],
 ["¡Te mando un mensaje al llegar! Un beso muy fuerte, mamá.","Pošlem ti správu, keď prídeme! Silná pusa, mami."]
]);
D("farewells",["Un adiós largo","Dlhá rozlúčka"],["Tu nieta Lucía, antes de irse a vivir fuera","Tvoja vnučka Lucía pred odchodom do zahraničia"],[
 ["Abuela, mañana me voy a Berlín. Voy a echarte muchísimo de menos.","Babi, zajtra odchádzam do Berlína. Strašne mi budeš chýbať."],
 [["cari","Y yo a ti, mi niña. Pero estoy muy orgullosa de ti.","Aj ty mne, dievčatko moje. Ale som na teba veľmi hrdá."],["anim","Vas a vivir algo maravilloso. Aprovéchalo al máximo.","Zažiješ niečo nádherné. Využi to naplno."],["duda","Me da pena, la verdad. Pero sé que es bueno para ti.","Pravdupovediac, je mi to ľúto. Ale viem, že je to pre teba dobré."],["cuenta","Yo también dejé mi país, y fue lo mejor que hice.","Aj ja som opustila svoju krajinu a bolo to to najlepšie, čo som urobila."],["hum","Berlín no sabe lo que le espera.","Berlín ani netuší, čo ho čaká."],["breve","Te voy a echar de menos.","Budeš mi chýbať."]],
 ["¿Me prometes que harás videollamadas conmigo? Aunque te cueste el móvil.","Sľúbiš mi, že budeme mať videohovory? Aj keď ti to s mobilom nejde."],
 [["preg","¿Y tú me prometes comer bien y abrigarte?","A ty mi sľúbiš, že budeš dobre jesť a teplo sa obliekať?"],["si","Te lo prometo. Cada domingo a las seis.","Sľubujem. Každú nedeľu o šiestej."],["hum","Prometido. Y si no sé, le pido ayuda a tu hermano.","Sľubujem. A ak nebudem vedieť, poprosím o pomoc tvojho brata."],["cari","Claro que sí. Verte la cara me dará la vida.","Jasné, že áno. Vidieť tvoju tvár mi dodá život."],["ofre","Y te mandaré cartas de papel, como antes.","A budem ti posielať papierové listy, ako kedysi."],["breve","Prometido.","Sľubujem."]],
 ["Te lo prometo, abuela. Y en Navidad vuelvo. Cuídate mucho, ¿vale?","Sľubujem, babi. A na Vianoce sa vrátim. Dávaj na seba pozor, dobre?"],
 [["ofre","Toma, te he hecho galletas para el viaje. Te quiero muchísimo.","Na, upiekla som ti sušienky na cestu. Veľmi ťa ľúbim."],["cari","Tú también, cariño. Ve con cuidado y sé feliz.","Ty tiež, zlatko. Choď opatrne a buď šťastná."],["hum","Me cuidaré. Tú no te olvides de tu abuela con tantos alemanes guapos.","Budem dávať pozor. Ty nezabudni na babku medzi toľkými peknými Nemcami."],["recu","Me recuerdas a mí con tu edad, maleta en mano y el corazón a mil.","Pripomínaš mi mňa v tvojom veku, s kufrom v ruke a búšiacim srdcom."],["grac","Gracias por venir a despedirte. Te quiero muchísimo.","Ďakujem, že si sa prišla rozlúčiť. Mám ťa strašne rada."],["breve","Un abrazo enorme.","Obrovské objatie."]],
 ["Yo también te quiero, abuela. ¡Hasta Navidad! Y las galletas me las como en el avión.","Aj ja ťa ľúbim, babi. Do Vianoc! A sušienky zjem v lietadle."]
]);
D("farewells",["Al final de las vacaciones","Na konci dovolenky"],["Tu consuegra Carmen","Tvoja svatka Carmen"],[
 ["Qué rápido se ha pasado la semana. Ya os vais mañana, ¿no?","Ako rýchlo ten týždeň ubehol. Zajtra už odchádzate, však?"],
 [["grac","Sí. Muchas gracias por recibirnos tan bien.","Áno. Veľmi pekne ďakujeme, že ste nás tak pekne prijali."],["si","Sí, mañana a primera hora. Se nos ha hecho cortísimo.","Áno, zajtra skoro ráno. Ubehlo to strašne rýchlo."],["cari","Sí. Ha sido una semana preciosa gracias a vosotros.","Áno. Vďaka vám to bol nádherný týždeň."],["hum","Sí, y me llevo dos kilos más en la maleta y en el cuerpo.","Áno, a odnášam si o dve kilá viac v kufri aj na sebe."],["duda","Sí... Qué pena, me había acostumbrado a esta rutina.","Áno... Škoda, už som si zvykla na tento režim."],["breve","Sí, mañana.","Áno, zajtra."]],
 ["Para nosotros ha sido un placer. Tenéis que volver pronto, ¿eh?","Pre nás to bolo potešenie. Musíte sa čoskoro vrátiť, jasné?"],
 [["ofre","En primavera os invitamos a Eslovaquia. Os enseñaremos los Tatras.","Na jar vás pozveme na Slovensko. Ukážeme vám Tatry."],["si","Por supuesto. Y la próxima vez, venid vosotros a vernos.","Samozrejme. A nabudúce príďte vy k nám."],["cari","Nos sentimos como en casa. Eso no tiene precio.","Cítili sme sa ako doma. To je na nezaplatenie."],["preg","¿Habéis estado alguna vez en Eslovaquia?","Boli ste niekedy na Slovensku?"],["hum","Volveremos, aunque solo sea por tu tortilla de patatas.","Vrátime sa, aj keby len kvôli tvojej tortille."],["breve","¡Seguro que sí!","Určite áno!"]],
 ["¡Nunca hemos estado! Me encantaría ir. ¿Hace mucho frío en primavera?","Nikdy sme tam neboli! Rada by som išla. Je na jar veľká zima?"],
 [["expl","En mayo hace buen tiempo, unos veinte grados. Es la mejor época.","V máji je pekné počasie, okolo dvadsať stupňov. Je to najlepšie obdobie."],["hum","Más que aquí seguro. Os prestaremos abrigos.","Určite viac ako tu. Požičiame vám kabáty."],["si","Un poco, pero los paisajes son preciosos. Os encantará.","Trochu, ale krajina je nádherná. Bude sa vám páčiť."],["ofre","Venid en mayo y os enseño a hacer halušky.","Príďte v máji a naučím vás robiť halušky."],["cari","Lo importante es que estemos juntas, haga el tiempo que haga.","Dôležité je, aby sme boli spolu, nech je počasie akékoľvek."],["breve","En mayo, nada.","V máji vôbec."]],
 ["¡Mayo, entonces! Lo apunto. Y esta noche, cena de despedida en mi casa.","Tak máj! Zapíšem si to. A dnes večer rozlúčková večera u mňa."]
]);
D("farewells",["Un compañero se jubila","Kolega ide na dôchodok"],["Tu antiguo compañero Ernesto","Tvoj bývalý kolega Ernesto"],[
 ["Bueno, pues ya está. Hoy es mi último día de trabajo. Cuarenta y dos años...","Tak a je to. Dnes je môj posledný pracovný deň. Štyridsaťdva rokov..."],
 [["preg","¿Y cómo te sientes? ¿Contento o un poco triste?","A ako sa cítiš? Spokojný alebo trochu smutný?"],["cari","¡Enhorabuena, Ernesto! Te lo has ganado de sobra.","Blahoželám, Ernesto! Úplne si si to zaslúžil."],["recu","Me acuerdo de tu primer día. Llegaste con una corbata horrible.","Pamätám si tvoj prvý deň. Prišiel si v hroznej kravate."],["hum","¡Por fin! Ahora podrás dormir hasta las siete y media.","Konečne! Teraz budeš môcť spať do pol ôsmej."],["form","Muchas felicidades por esta nueva etapa.","Srdečne blahoželám k tejto novej etape."],["breve","¡Felicidades!","Blahoželám!"]],
 ["Contento, pero raro. No sé qué voy a hacer los lunes por la mañana.","Spokojný, ale zvláštne. Neviem, čo budem robiť v pondelok ráno."],
 [["ofre","Los lunes a las diez quedamos varios jubilados a tomar café. ¡Vente!","V pondelok o desiatej sa schádzame viacerí dôchodcovia na kávu. Poď s nami!"],["cuenta","Yo los primeros meses también estaba perdida. Luego encontré mi ritmo.","Aj ja som bola prvé mesiace stratená. Potom som našla svoj rytmus."],["opin","Date tiempo. Al principio es normal sentirse así.","Daj si čas. Na začiatku je normálne cítiť sa takto."],["hum","Los lunes por la mañana: dormir y no pensar en reuniones.","Pondelok ráno: spať a nemyslieť na porady."],["preg","¿Tienes algún proyecto pendiente, algo que siempre quisiste hacer?","Máš nejaký nevybavený plán, niečo, čo si vždy chcel robiť?"],["anim","Ahora tienes tiempo para todo lo que dejaste para «cuando tenga tiempo».","Teraz máš čas na všetko, čo si odkladal na „keď budem mať čas“."]],
 ["Lo del café de los lunes me encanta. Y quiero aprender a pintar, como tú.","Káva v pondelok je super. A chcem sa naučiť maľovať, ako ty."],
 [["si","¡Te apunto al café! Y te presento a mi profesora de pintura.","Zapíšem ťa na kávu! A predstavím ťa svojej učiteľke maľovania."],["cari","Qué bonito. Así nos seguimos viendo, aunque ya no trabajemos juntos.","Aké pekné. Tak sa budeme naďalej vídať, aj keď už spolu nepracujeme."],["hum","Perfecto, pero te aviso: en pintura soy mejor que tú.","Výborne, ale upozorňujem ťa: v maľovaní som lepšia ako ty."],["ofre","Te presto mis pinceles para empezar.","Požičiam ti štetce, aby si mohol začať."],["grac","Gracias por todos estos años de compañerismo.","Ďakujem za všetky tie roky kolegiality."],["breve","¡Te espero el lunes!","Čakám ťa v pondelok!"]],
 ["¡El lunes a las diez allí estaré! Gracias por todo, de verdad.","V pondelok o desiatej tam budem! Naozaj ďakujem za všetko."]
]);
D("farewells",["Seguir en contacto","Zostať v kontakte"],["Tu amiga Paula, que se muda a otra ciudad","Tvoja kamarátka Paula, ktorá sa sťahuje do iného mesta"],[
 ["Bueno, ya tengo todo en cajas. El sábado me mudo a Valencia.","Tak, všetko mám v škatuliach. V sobotu sa sťahujem do Valencie."],
 [["preg","¿Ya tienes piso allí? ¿Cerca de tu hija?","Už tam máš byt? Blízko dcéry?"],["cari","Te voy a echar mucho de menos, Paula.","Budeš mi veľmi chýbať, Paula."],["ofre","¿Necesitas ayuda con la mudanza? Pedro puede ir con el coche.","Potrebuješ pomoc so sťahovaním? Pedro môže prísť autom."],["anim","Qué bien que vayas a estar cerca de tus nietos.","Aké dobré, že budeš blízko vnúčat."],["hum","¿A Valencia? Qué envidia: paella todos los días.","Do Valencie? Závidím: paella každý deň."],["breve","¡Qué pena!","Aká škoda!"]],
 ["Sí, a dos calles de mi hija. Pero me da pena dejar el barrio y a las amigas.","Áno, dve ulice od dcéry. Ale je mi ľúto opustiť štvrť a kamarátky."],
 [["ofre","Iremos a verte. Valencia está a solo dos horas en tren.","Prídeme ťa navštíviť. Valencia je vlakom len dve hodiny."],["apoyo","Es normal. Son muchos años aquí. Pero allí te espera tu familia.","To je normálne. Je to veľa rokov tu. Ale tam ťa čaká rodina."],["opin","Las amistades de verdad no dependen de la distancia.","Skutočné priateľstvá nezávisia od vzdialenosti."],["cuenta","Cuando yo me mudé a España, mis amigas me escribían cartas cada mes.","Keď som sa presťahovala do Španielska, kamarátky mi každý mesiac písali listy."],["cari","Y el barrio también te va a echar de menos a ti.","A aj štvrti budeš chýbať ty."],["breve","Te entiendo.","Chápem ťa."]],
 ["¿De verdad vendréis a verme? Prometédmelo.","Naozaj ma prídete navštíviť? Sľúbte mi to."],
 [["ofre","Y para Fallas, si nos invitas, allí estamos.","A na Fallas, ak nás pozveš, prídeme."],["si","Prometido. En primavera, en cuanto haga buen tiempo.","Sľubujem. Na jar, hneď ako bude pekne."],["cari","Te lo prometo. Y tú llámame cada semana, ¿eh?","Sľubujem. A ty mi volaj každý týždeň, jasné?"],["hum","Prometido. Y te llevaremos tortilla, por si en Valencia no saben hacerla.","Sľubujem. A donesieme ti tortillu, keby ju vo Valencii nevedeli robiť."],["grac","Gracias por tantos años de amistad. Han sido un regalo.","Ďakujem za toľké roky priateľstva. Boli darom."],["breve","Palabra.","Čestné slovo."]],
 ["¡Para Fallas os invito, seguro! Y os guardo la mejor habitación. Os quiero mucho.","Na Fallas vás určite pozvem! A odložím vám najlepšiu izbu. Mám vás veľmi rada."]
]);
RDMContent.register("family",{schemaVersion:1,topics:[{"id":"visits","title":{"es":"Organizar una visita","sk":"Dohodnúť návštevu"},"note":{"es":"Propón algo concreto y deja espacio para que la otra persona lo cambie.","sk":"Navrhnite niečo konkrétne a nechajte druhému priestor na zmenu."}},{"id":"arrivals","title":{"es":"Llegar y recibir","sk":"Príchod a privítanie"},"note":{"es":"Al recibir a alguien, orienta y ofrece sin dar nada por supuesto.","sk":"Pri privítaní poraďte a ponúknite pomoc bez zbytočných predpokladov."}},{"id":"table","title":{"es":"En la mesa","sk":"Pri stole"},"note":{"es":"Habla de gustos y cantidades con naturalidad; se puede rechazar algo con amabilidad.","sk":"O chutiach a množstve hovorte prirodzene, odmietnuť sa dá aj milo."}},{"id":"kitchen","title":{"es":"Cocinar juntos","sk":"Spoločné varenie"},"note":{"es":"Reparte tareas concretas y comprueba antes de cambiar una receta.","sk":"Rozdeľte konkrétne úlohy a pred zmenou receptu sa opýtajte."}},{"id":"home","title":{"es":"Compartir la casa","sk":"Spoločná domácnosť"},"note":{"es":"Pedir colaboración funciona mejor con una tarea clara que con un reproche general.","sk":"O spoluprácu požiadajte konkrétnou úlohou namiesto všeobecnej výčitky."}},{"id":"plans","title":{"es":"Decidir qué hacer","sk":"Rozhodnúť sa, čo podniknúť"},"note":{"es":"Una propuesta puede ser flexible: ofrece una alternativa y acepta un cambio.","sk":"Návrh môže byť pružný, ponúknite alternatívu a prijmite zmenu."}},{"id":"errands","title":{"es":"Recados y favores","sk":"Vybavovanie a láskavosti"},"note":{"es":"Aclara qué necesitas y permite que la otra persona diga que no puede.","sk":"Povedzte jasne, čo potrebujete, a nechajte druhému možnosť odmietnuť."}},{"id":"news","title":{"es":"Ponerse al día","sk":"Povedať si novinky"},"note":{"es":"Pregunta sin interrogar y distingue lo que sabes de lo que solo te han contado.","sk":"Pýtajte sa bez vypočúvania a rozlišujte vlastné informácie od sprostredkovaných."}},{"id":"wellbeing","title":{"es":"Cómo te encuentras","sk":"Ako sa cítiš"},"note":{"es":"Pregunta por la experiencia de la persona y escucha lo que necesita.","sk":"Pýtajte sa na to, ako sa človek cíti, a počúvajte, čo potrebuje."}},{"id":"support","title":{"es":"Escuchar y apoyar","sk":"Počúvať a podporiť"},"note":{"es":"Antes de aconsejar, averigua si la otra persona quiere ideas o solo compañía.","sk":"Pred radou zistite, či druhý chce návrhy alebo len spoločnosť."}},{"id":"boundaries","title":{"es":"Poner límites con cariño","sk":"Láskavo určiť hranice"},"note":{"es":"Un límite claro puede ser amable: di lo que puedes ofrecer y lo que no.","sk":"Jasná hranica môže byť láskavá, povedzte, čo môžete ponúknuť a čo nie."}},{"id":"disagreements","title":{"es":"Discrepar y reparar","sk":"Nesúhlasiť a napraviť nedorozumenie"},"note":{"es":"Separa la idea de la persona y comprueba qué quiso decir antes de responder.","sk":"Oddeľte názor od človeka a pred odpoveďou si overte, čo chcel povedať."}},{"id":"memories","title":{"es":"Recuerdos y otras épocas","sk":"Spomienky a iné obdobia"},"note":{"es":"Puedes contar un recuerdo sin exigir que todos lo recuerden igual.","sk":"Spomienku môžete rozprávať bez očakávania, že si ju všetci pamätajú rovnako."}},{"id":"interests","title":{"es":"Libros, ideas y aficiones","sk":"Knihy, myšlienky a záľuby"},"note":{"es":"Pide razones y ejemplos; un gusto distinto también puede abrir una buena charla.","sk":"Pýtajte sa na dôvody a príklady, aj odlišný vkus môže otvoriť dobrý rozhovor."}},{"id":"outings","title":{"es":"Paseos y salidas","sk":"Prechádzky a spoločné aktivity"},"note":{"es":"Hablad del ritmo y de las preferencias antes de dar por hecho el plan.","sk":"O tempe a záľubách hovorte skôr, než budete plán považovať za samozrejmý."}},{"id":"travel","title":{"es":"Viajar en familia","sk":"Spoločné cestovanie"},"note":{"es":"Comparte la organización y confirma los detalles que pueden causar confusión.","sk":"Podeľte si organizáciu a overte podrobnosti, ktoré môžu viesť k nedorozumeniu."}},{"id":"calls","title":{"es":"Llamadas y mensajes","sk":"Telefonáty a správy"},"note":{"es":"Si falla la comunicación, confirma lo importante en vez de fingir que has entendido.","sk":"Ak komunikácia zlyhá, overte si dôležité veci namiesto predstierania, že rozumiete."}},{"id":"celebrations","title":{"es":"Celebrar y agradecer","sk":"Oslavy a poďakovanie"},"note":{"es":"Agradece algo concreto; una celebración puede ser sencilla y compartida.","sk":"Poďakujte sa za niečo konkrétne, oslava môže byť jednoduchá a spoločná."}},{"id":"younger","title":{"es":"Hablar con los más jóvenes","sk":"Rozhovory s mladšími"},"note":{"es":"La curiosidad sincera abre más conversación que fingir que ya conoces su mundo.","sk":"Úprimná zvedavosť otvára lepší rozhovor než predstieranie, že už poznáte ich svet."}},{"id":"farewells","title":{"es":"Despedirse y seguir en contacto","sk":"Rozlúčiť sa a zostať v kontakte"},"note":{"es":"Cierra el encuentro con algo concreto y sin prometer lo que no sabes si podrás cumplir.","sk":"Stretnutie uzavrite niečím konkrétnym a nesľubujte to, čo možno nesplníte."}}],dialogues:familyDialogues,styles:familyAnswerStyles});
